window.IDIOM_BANK = [
  { w: "安然如故", p: ["ān", "rán", "rú", "gù"], e: "还象原来那样安安稳稳。", s: "元·纪君祥《赵氏孤儿》第四折你只看这一个，那一个，都是为谁而卒？岂可我做儿的倒安然如故？”" },
  { w: "安然无事", p: ["ān", "rán", "wú", "shì"], e: "犹言平安无事。", s: "清·夏敬渠《野叟曝言》第三十二回四嫂不来聒噪，耳根清净，倒也安然无事，除非把你两家合成一家，我一个人就好照顾了。”" },
  { w: "安如太山", p: ["ān", "rú", "tài", "shān"], e: "形容极其平安稳固。泰，也写作太”。同安如泰山”。", s: "汉·焦赣《易林·坤之中孚》安如太山，福禧屡臻。虽有豺虎，不致危身。”" },
  { w: "安身之处", p: ["ān", "shēn", "zhī", "chù"], e: "指得以立足容身的地方。", s: "明·罗贯中《三国演义》第四十回近闻刘景升病在危笃，可乘此机会，取得荆州为安身之地。”" },
  { w: "安身之地", p: ["ān", "shēn", "zhī", "dì"], e: "存身的地方。批在某地居住、生活，或以某地作为建业的根基。", s: "明·罗贯中《三国演义》第四十回近闻刘景升病在危笃，可乘此机会，取得荆州为安身之地。”" },
  { w: "安心定志", p: ["ān", "xīn", "dìng", "zhì"], e: "指安下心来。", s: "明·吴承恩《西游记》第四回又差五斗星君送悟空去到任，外赐御酒一瓶，金花十朵，着他安心定志，再勿胡为。”" },
  { w: "安心乐意", p: ["ān", "xīn", "lè", "yì"], e: "原指心情安宁，情绪愉快◇多指内心情愿，十分愉快。", s: "清·曹雪芹《红楼梦》第一百十四回我看二嫂子如今倒是安心乐意的孝敬我妈妈，比亲媳妇还强十倍呢。”" },
  { w: "八面见光", p: ["bā", "miàn", "jiàn", "guāng"], e: "形容人非常世故，各方面都能应付得很周到。", s: "清·文康《儿女英雄传》第十回张姑娘这几句话，说得软中带硬，八面见光，包罗万象。”" },
  { w: "白面书生", p: ["bái", "miàn", "shū", "shēng"], e: "指缺乏阅历经验的读书人。也指面孔白净的读书人。", s: "《宋书·沈庆之传》陛下今欲伐国，而与白面书生辈谋之，事何由济。”" },
  { w: "白日作梦", p: ["bái", "rì", "zuò", "mèng"], e: "比喻幻想不可能实现。同白日做梦”。", s: "刘绍棠《狼烟》二十二金镶玉走进舱去，嘻笑道‘老昏君白日作梦，自以为是九五之尊，不肯有失万岁爷的身份，迎接一位七品县令。’…" },
  { w: "白日做梦", p: ["bái", "rì", "zuò", "mèng"], e: "大白天做梦。比喻根本不能实现的梦想。", s: "明·豫章醉月子《精选雅笑·送匾》以为必中而遍问星相者，亦是白日做梦。”" },
  { w: "白手成家", p: ["bái", "shǒu", "chéng", "jiā"], e: "没有依恃，而独立兴起的家业或事业。", s: "周而复《上海的早晨》第一部十二朱延年是商人的儿子，他的福佑药房是白手成家的。”" },
  { w: "白手起家", p: ["bái", "shǒu", "qǐ", "jiā"], e: "白手空手；起家创建家业。形容在没有基础和条件很差的情况下自力更生，艰苦创业。", s: "《朱子语类》卷一０七今士大夫白屋起家，以致荣显。”" },
  { w: "白头到老", p: ["bái", "tóu", "dào", "lǎo"], e: "白头头发白。夫妻相亲相爱，一直到老。", s: "《诗经·卫风·氓》及尔偕老。”明·陆采《怀香记·奉诏班师》孩儿，我与你母亲白头偕老，富贵双全。”" },
  { w: "白头而新", p: ["bái", "tóu", "ér", "xīn"], e: "指相交虽久而并不知己，像新知一样。同白头如新”。", s: "明·杨慎《白头而新》《汉书》‘白头如新，倾盖如故。’《说苑》作‘白头而新，倾盖而故’。‘而’、‘如’，古字通用。白头而新…" },
  { w: "白头如新", p: ["bái", "tóu", "rú", "xīn"], e: "白头头发白了；新新交。指交朋友彼此不能了解，时间虽久，仍跟刚认识一样。", s: "汉·邹阳《狱中上书自明》语曰白头如新，倾盖如故，何则？”《史记·鲁仲连邹阳列传》谚曰‘有白头如新，倾盖如故。’何则？知与…" },
  { w: "百不当一", p: ["bǎi", "bù", "dāng", "yī"], e: "当抵挡。一百个抵挡不住一个。", s: "汉·荀悦《汉纪·文帝纪下》平易相远，山谷幽涧，仰高临下，此弓弩之地也，短兵百不当一。”" },
  { w: "百不失一", p: ["bǎi", "bù", "shī", "yī"], e: "一百次中无一次失误。表示射箭或打枪命中率高，或做事有充分把握。", s: "汉·王充《论衡·须颂》从门应庭，听堂室之言，什而失九，如升堂窥室，百不失一。”" },
  { w: "百花生日", p: ["bǎi", "huā", "shēng", "rì"], e: "旧指阴历二月十二日，即花朝。", s: "清·秦味芸《月令粹编》卷五《陶朱公书》‘二月十二日为百花生日。无雨，百花熟。’”" },
  { w: "百里之才", p: ["bǎi", "lǐ", "zhī", "cái"], e: "百里方圆百里之地。指能治理方圆百里地区的人才◇称才能平常的人。", s: "《三国志·蜀志·蒋琬传》蒋琬，社稷之器，非百里之才也。”" },
  { w: "百年好合", p: ["bǎi", "nián", "hǎo", "hé"], e: "夫妻永远和好之意。", s: "《粉妆楼》第一回百年和合，千载团圆恭喜！”" },
  { w: "百年好事", p: ["bǎi", "nián", "hǎo", "shì"], e: "指婚姻喜事。", s: "明·凌濛初《二刻拍案惊奇》卷九我与你姐姐百年好事，千金重担只在此两件上面了！万望龙香姐竭力周全，讨个回音则个。”" },
  { w: "百年之好", p: ["bǎi", "nián", "zhī", "hǎo"], e: "永久的好合。指男女结为夫妇。", s: "宋·罗烨《醉翁谈录·张氏夜奔吕星哥》今宁随君远奔，以结百年之好。”明·凌濛初《初刻拍案惊奇》卷三十二我方壮年，未曾娶妻。…" },
  { w: "百年之后", p: ["bǎi", "nián", "zhī", "hòu"], e: "死的讳称。", s: "《曹操集·卷二·军谯令》为存者立庙，使视其先人。魂而有灵，吾百年之后何恨哉！”元·武汉臣《老生儿》第三折俺女儿百年之后，…" },
  { w: "百世不易", p: ["bǎi", "shì", "bù", "yì"], e: "千秋万代永不改变。", s: "《汉书·邹阳传》积德累行，不知其善，有时而用；弃义背理，不知其恶，有时而亡。臣愿大王孰计而身行之，此百世不易之道也。”" },
  { w: "百世一人", p: ["bǎi", "shì", "yī", "rén"], e: "指极难得的人才。", s: "宋·苏轼《祭司马君实文》百世一人，千载一时，惟时与人，鲜偶常奇。”" },
  { w: "百世之利", p: ["bǎi", "shì", "zhī", "lì"], e: "世世代代长远的利益。", s: "《吕氏春秋·义赏》文公曰‘雍季之言，百世之利也。”" },
  { w: "百事无成", p: ["bǎi", "shì", "wú", "chéng"], e: "犹言一事无成。什么事情都没成功。", s: "唐·刘禹锡《陪崔大尚书及诸阁老宴杏园》诗更将何面上春台，百事无成老又催。”" },
  { w: "百死一生", p: ["bǎi", "sǐ", "yī", "shēng"], e: "形容生命极其危险，处于死亡的边缘。", s: "《北齐书·杜弼传》诸勋人身触锋刃，百死一生，纵其贪鄙，所取处大，不可同之循常例也。”" },
  { w: "百无是处", p: ["bǎi", "wú", "shì", "chù"], e: "犹言一无是处。形容全都是错的，没有一点对的地方。", s: "宋·辛弃疾《浣溪沙·漫兴作》词一似旧时春意思，百无是处老形骸，也曾头上带花来。”" },
  { w: "百无所成", p: ["bǎi", "wú", "suǒ", "chéng"], e: "犹言一事无成。", s: "明·王守仁《教条示龙场诸生》今学者旷废隳惰，玩岁愒时而百无所成，皆由于志之未立耳。”" },
  { w: "百无一成", p: ["bǎi", "wú", "yī", "chéng"], e: "百一切。形容一切的努力和作为没有一样成功，即毫无成就。", s: "清·曾国藩《圣哲画象记》志学不早……驽缓多病，百无一成。”" },
  { w: "百无一能", p: ["bǎi", "wú", "yī", "néng"], e: "能能力，胜任。什么都不会做。", s: "明·施耐庵《水浒全传》第三十二回宋江道‘我自百无一能，虽有忠心，不能得进步。’”" },
  { w: "百无一失", p: ["bǎi", "wú", "yī", "shī"], e: "形容有充分把握，绝对不会出差错。", s: "汉·王充《论衡·须颂》从门应庭，听堂室之言，什而失九，如升堂窥室，百不失一。”" },
  { w: "百无一是", p: ["bǎi", "wú", "yī", "shì"], e: "干一百件事，也没有做对一件。形容全都做错了，一无是处。", s: "宋·袁采《袁氏世范》至于百无一是，且朝夕以此相临，极为难处。”" },
  { w: "百无一用", p: ["bǎi", "wú", "yī", "yòng"], e: "百样之中无一有用的。形容毫无用处。", s: "清·黄景仁《杂感》十有九人堪白眼，百无一用是书生。”" },
  { w: "百下百全", p: ["bǎi", "xià", "bǎi", "quán"], e: "犹言百发百中，万无一失。", s: "汉·班固《汉书·冯奉世传》以将军材质之美，奋精兵，诛不轨，百下百全之道也。”" },
  { w: "百折不回", p: ["bǎi", "zhé", "bù", "huí"], e: "折挫折。比喻意志坚强，无论受到多少次挫折，毫不动摇退缩。", s: "汉·蔡邕《太尉乔玄碑》其性庄，疾华尚朴，有百折不挠，临大节而不可夺之风。”" },
  { w: "本来面目", p: ["běn", "lái", "miàn", "mù"], e: "原为佛家语，指人的本性◇多比喻事物原来的模样。", s: "唐·慧能《六祖坛经·行由品》不思善，不思恶，正与么时，那个是明上座本来面目。”宋·苏轼《老人行》诗一任秋霜换鬓毛，本来面…" },
  { w: "比物此志", p: ["bǐ", "wù", "cǐ", "zhì"], e: "比物比类，比喻；志心意。指用事物行为来寄托、表达自己的心意。", s: "《汉书·贾谊传》圣人有金城者，比物此志也。”" },
  { w: "比众不同", p: ["bǐ", "zhòng", "bù", "tóng"], e: "与大家相比，大不一样。", s: "明·吴承恩《西游记》第四回原来悟空筋斗云比众不同，十分快疾，把个金星撇在脑后，先至南天门外。”" },
  { w: "必不得已", p: ["bì", "bù", "dé", "yǐ"], e: "必然不能得止。指形势使得非如此不可。表示无可奈何的意思。", s: "《论语·颜渊》子贡问政。子曰‘足食，足兵，民信之矣。’子贡曰‘必不得已而去，于斯三者何先？’曰‘去兵。’”" },
  { w: "必也正名", p: ["bì", "yě", "zhèng", "míng"], e: "指必须按照正统伦理观念和礼仪关系来端正纲纪名分。", s: "《论语·子路》子路曰‘卫君待子而为政，子将奚先？’子曰‘必也正名乎！’”" },
  { w: "变动不居", p: ["biàn", "dòng", "bù", "jū"], e: "指事物不断变化，没有固定的形态。", s: "《易系辞下》《易》之为书也不可远；为道也，屡迁，变动不居，周流六虚。”孔颖达疏言阴阳六爻更互变动，不恒居一体也。”" },
  { w: "变古易常", p: ["biàn", "gǔ", "yì", "cháng"], e: "改变传统的法制和准则。", s: "语出《韩非子·南面》不知治者，必曰‘无变古，毋易常。’”" },
  { w: "变色易容", p: ["biàn", "sè", "yì", "róng"], e: "变、易改变。色、容脸色、表情。形容惊惶失措的神情。", s: "《战国策·秦策·范睢说秦王》是日见范睢，见者无不变色易容。”" },
  { w: "变色之言", p: ["biàn", "sè", "zhī", "yán"], e: "使脸色改变的话。多指为争论是非曲直而冲动发怒时说的话。", s: "《汉书·匡衡传》朝有变色之言，则下有争斗之患。”" },
  { w: "表里不一", p: ["biǎo", "lǐ", "bù", "yī"], e: "表面与内在不一样。", s: "《逸周书·谥法解》行见中外曰悫。”" },
  { w: "表里如一", p: ["biǎo", "lǐ", "rú", "yī"], e: "表外表；里内心。表面和内心象一个东西。形容言行和思想完全一致。", s: "南朝·梁·刘勰《文心雕龙·附会》首尾周密，表里一体。”《朱子全书·论语》行之以忠者，是事事要着实，故某集注云‘以忠，则表…" },
  { w: "表面文章", p: ["biǎo", "miàn", "wén", "zhāng"], e: "比喻浮夸或不切实际，敷衍塞责的做法。", s: "无" },
  { w: "别出新意", p: ["bié", "chū", "xīn", "yì"], e: "指独创一格，与众不同。", s: "宋·司马光《与王介甫书》大抵所利不能补其所伤，所得不能偿其所亡，徒欲别出新意，以自为功名耳。”" },
  { w: "别开生面", p: ["bié", "kāi", "shēng", "miàn"], e: "生面新的面目。原意是凌烟阁里的功臣画像本已褪色，经曹将军重画之后才显得有生气。比喻另外创出一种新的形式或局面。", s: "唐·杜甫《丹青诗》凌烟功臣少颜色，将军下笔开生面。”" },
  { w: "别无他物", p: ["bié", "wú", "tā", "wù"], e: "除此之外没有多余的东西。同别无长物”。", s: "明·冯梦龙《喻世明言》第七卷伯桃视之，止有一塌，塌上堆积书卷，别无他物。”" },
  { w: "别无长物", p: ["bié", "wú", "cháng", "wù"], e: "长物多余的东西。除一身之外再没有多余的东西。原指生活俭朴。现形容贫穷。", s: "南朝·宋·刘义庆《世说新语·德行》丈人不悉恭，恭作人无长物。”" },
  { w: "别有人间", p: ["bié", "yǒu", "rén", "jiān"], e: "犹别有天地。", s: "清·卓发之《裓园嫘史》诗序清凉山之畔，竹径数转，别有人间。”" },
  { w: "别有天地", p: ["bié", "yǒu", "tiān", "dì"], e: "天地境界。比喻另有一番境界。形容风景或艺术创作的境界引人入胜。", s: "唐·李白诗《山中问答》桃花流水窅然去，别有天地非人间。”" },
  { w: "别有用心", p: ["bié", "yǒu", "yòng", "xīn"], e: "用心居心，打算。心中另有算计。指言论或行动另有不可告人的企图。", s: "清·吴趼人《二十年目睹之怪现状》第九十九回王太尊也是说他办事可靠，那里知道他是别有用心的呢。”" },
  { w: "兵出无名", p: ["bīng", "chū", "wú", "míng"], e: "出兵没有正当理由。亦泛指行事无正当理由。同师出无名”", s: "《汉书·高帝纪》兵出无名，事故不成。”" },
  { w: "兵无常势", p: ["bīng", "wú", "cháng", "shì"], e: "常不变；势形势。用兵无一成不变的形势。用以说明办事要因时、因地制宜，具体问题要用具体办法去解决。", s: "《孙子·虚实》夫兵形象水，水之行，避高而趋下；兵之形，避实而击虚。水因地而制流，兵因敌而制胜。故兵无常势，水无常形，能因…" },
  { w: "兵无常形", p: ["bīng", "wú", "cháng", "xíng"], e: "用兵无一成不变的形势。指办事要因时、因地制宜，具体问题要用具体办法去解决。", s: "《孙子·计》兵者，诡道也”三国·魏·曹操注兵无常形，以诡诈为道。”" },
  { w: "不臣之心", p: ["bù", "chén", "zhī", "xīn"], e: "不臣不守臣子的本分，封建社会中不忠君。意指不忠君的思想◇也指犯上作乱的野心。", s: "《三国志·魏书·二公孙陶四张传》是时术阴有不臣之心，不利国家有长主，外托公义以答拒之。”《晋书·周处传》闻敦有不臣之心，…" },
  { w: "不当不正", p: ["bù", "dāng", "bù", "zhèng"], e: "不语助词，没有实际意思。表示端端正正。", s: "元·无名氏《渔樵记》第三折老汉也分开人丛，不当不正，站在那相公马前。”" },
  { w: "不当人子", p: ["bù", "dāng", "rén", "zǐ"], e: "表示歉意或感谢的话，意思是罪过，不敢当。", s: "明·冯梦龙《醒世恒言》卷十多谢厚情，只是无功受禄，不当人子，老汉转来，定当奉酬。”" },
  { w: "不得而知", p: ["bù", "dé", "ér", "zhī"], e: "得能够。没有办法知道。", s: "《后汉书·桓谭传》盖天道性命，圣人所难言也。自子贡以下，不得而闻。”唐·韩愈《争臣论》故虽谏且议，使人不得而知焉。”" },
  { w: "不得其死", p: ["bù", "dé", "qí", "sǐ"], e: "指人不得好死。也表示对恶人的诅咒。", s: "《论语·先进》若由也，不得其死然。”" },
  { w: "不得其所", p: ["bù", "dé", "qí", "suǒ"], e: "原指未得善终，后指没有得到适当的安顿。也指不能达到目的。", s: "《谷梁传·成公八年》媵，浅事也，不志。此其志何也？以伯姬之不得其所，故尽其事也。”" },
  { w: "不得人心", p: ["bù", "dé", "rén", "xīn"], e: "心心愿，愿望。得不到群众的支持拥护；得不到众人的好评。", s: "《旧唐书·哥舒翰传》先是，翰数奏禄山虽窃河朔，而不得人心，请持重以弊之，彼自离心，因而翦灭之，可不伤兵擒兹寇矣。”" },
  { w: "不动声色", p: ["bù", "dòng", "shēng", "sè"], e: "声言谈；色脸色。在紧急情况下，说话、神态仍跟平时一样没有变化。形容非常镇静。", s: "宋·欧阳修《相州昼锦堂记》垂绅正笏，不动声色，而措天下于泰山之安。”" },
  { w: "不二法门", p: ["bù", "èr", "fǎ", "mén"], e: "不二指不是两极端；法门佧行入道的门径。原为佛家语，意为直接入道，不可言传的法门◇比喻最好的或独一无二的方法。", s: "《维摩诘经·入不二法门品》如我意者，于一切法无言无说，无示无识，离诸问答，是为入不二法门。”" },
  { w: "不法常可", p: ["bù", "fǎ", "cháng", "kě"], e: "法当做模式、法则；常可长久被人们认可的成规惯例。不把常规惯例当做永远不变的模式。", s: "《韩非子·五蠹》是以圣人不期修古，不法常可。”" },
  { w: "不古不今", p: ["bù", "gǔ", "bù", "jīn"], e: "指事物不正常，古代现代都不曾有过。原讥讽人学无所得却故作诡异◇常比喻折衷。", s: "汉·扬雄《太玄经·更》童牛角马，不今不古。”" },
  { w: "不好意思", p: ["bù", "hǎo", "yì", "sī"], e: "①表示碍于情面而只能怎样或不便怎样。②害羞；难为情。", s: "无" },
  { w: "不见天日", p: ["bù", "jiàn", "tiān", "rì"], e: "比喻社会黑暗，见不到一点光明。", s: "宋·魏泰《东轩笔录》卷八福州之人，以为终世不见天日也，岂料端公赐问，然某尤为绛所苦者也。”" },
  { w: "不今不古", p: ["bù", "jīn", "bù", "gǔ"], e: "指事物不正常，古代现代都不曾有过。原讥讽人学无所得却故作诡异◇常比喻折衷。", s: "汉·扬雄《太玄经·更》童牛角马，不今不古。”" },
  { w: "不经世故", p: ["bù", "jīng", "shì", "gù"], e: "经经历；世故人情世事的变故。形容缺乏为人处世的经验。", s: "鲁迅《花边文学·序言》然而他们不经世故，偶尔‘忘其所以’也就大碰其钉子。”" },
  { w: "不经之说", p: ["bù", "jīng", "zhī", "shuō"], e: "指荒诞无稽、没有根据的话。", s: "唐·无稹《迁庙议状》曷若削汉朝不经之说，征殷周可久之文，从亲尽则迁之常规，为万代不朽之定制。”" },
  { w: "不经之语", p: ["bù", "jīng", "zhī", "yǔ"], e: "指荒诞无稽、没有根据的话。", s: "宋·王辟之《渑水燕谈录·杂录》神宗顾问左右‘青唇’何事，皆不能对。乃以问赵元老。元老奏‘不经之语，不敢以闻’。”" },
  { w: "不可多得", p: ["bù", "kě", "duō", "dé"], e: "形容非常稀少，很难得到（多指人才或稀有物品）。", s: "汉·王充《论衡·超奇篇》譬珠玉不可多得，以其珍也。”" },
  { w: "不可理喻", p: ["bù", "kě", "lǐ", "yù"], e: "喻开导，晓喻。没法跟他讲道理。形容蛮横或固执。", s: "明·沈德符《万历野获编·褐盖》此辈不可理喻，亦不足深诘也。”" },
  { w: "不可言传", p: ["bù", "kě", "yán", "chuán"], e: "言言语。指对某些事理只能揣摩领悟，不能用言语来表达。", s: "宋·释道原《景德传灯录》卷二十五诸法寂灭相，不可以宣言，和尚如何为人？” 明·圆极居顶《续传灯录》卷二十四妙契不可以意到…" },
  { w: "不可言喻", p: ["bù", "kě", "yán", "yù"], e: "喻说明，告知。不能用言语来说明。", s: "宋·沈括《梦溪笔谈·象数一》其术可以心得，不可言喻。”" },
  { w: "不可一世", p: ["bù", "kě", "yī", "shì"], e: "一世一时。认为当代的人都不行。形容目空一切、狂妄自大到了极点。", s: "宋·罗大经《鹤林玉露补遗》卷十五荆公少年，不可一世。”" },
  { w: "不名一文", p: ["bù", "míng", "yī", "wén"], e: "名占有。一个钱也没有。形容极其贫穷。", s: "姚雪垠《李自成》第二卷第十六章老兄明白，弟半生书剑飘零，寄食江湖，囊中不名一文。”" },
  { w: "不明不白", p: ["bù", "míng", "bù", "bái"], e: "指说话含含糊糊，很不清楚。也形容行为暧昧。", s: "元·无名氏《连环计》第四折怎么不明不白，着他父子每胡厮闹了一夜。”" },
  { w: "不能自已", p: ["bù", "néng", "zì", "yǐ"], e: "已停止。指无法控制自己，使激动的情绪平静下来。", s: "唐·卢照邻《寄裴舍人书》慨然而咏‘富贵他人合，贫贱亲戚离’，因泣下交颐，不能自已。”" },
  { w: "不日不月", p: ["bù", "rì", "bù", "yuè"], e: "指不计日月，没有期限。", s: "《诗经·王风·君子于役》君子于役，不日不月。”" },
  { w: "不容分说", p: ["bù", "róng", "fēn", "shuō"], e: "分说辩白，解说。不容人分辩解释。", s: "元·武汉臣《生金阁》三折怎么不由分说，便将我飞拳走踢只是打。”" },
  { w: "不三不四", p: ["bù", "sān", "bù", "sì"], e: "指不正派，也指不象样子。", s: "明·施耐庵《水浒全传》第七回这伙人不三不四，又不肯近前来，莫不要攧洒家。”" },
  { w: "不上不下", p: ["bù", "shàng", "bù", "xià"], e: "上不去，下不来。形容进退两难。", s: "《庄子·达生》上而不下，则使人善怒；下而不上，则使人善忘；不上不下，中身当心，则为病。”" },
  { w: "不声不气", p: ["bù", "shēng", "bù", "qì"], e: "指不说话；不出声。", s: "周立波《山乡巨变》上一你们只想自己的爱人像旧式妇女一样，百依百顺，不声不气，来服侍你们。”" },
  { w: "不食之地", p: ["bù", "shí", "zhī", "dì"], e: "不食不生产粮食。指不能耕种的土地。", s: "《礼记·檀弓上》我死则择不食之地而莽我焉。”" },
  { w: "不文不武", p: ["bù", "wén", "bù", "wǔ"], e: "既不能文，又不能武。", s: "唐·韩愈《泷吏》诗不知官在朝，有益国家不？得无虱其间，不文亦不武。”" },
  { w: "不闻不问", p: ["bù", "wén", "bù", "wèn"], e: "闻听。人家说的不听，也不主动去问。形容对事情不关心。", s: "清·石玉昆《三侠五义》第七十六回也不想想朝廷家平空的丢了一个太守，也就不闻不问，焉有是理。”" },
  { w: "不问不闻", p: ["bù", "wèn", "bù", "wén"], e: "闻听。人家说的不听，也不主动去问。形容对事情不关心。", s: "清·曹雪芹《红楼梦》第四回所以这李纨虽青春丧偶，且居处于膏梁锦绣之中，竟如‘槁木死灰’一般，一概不问不闻，惟知恃亲养子。…" },
  { w: "不相上下", p: ["bù", "xiāng", "shàng", "xià"], e: "分不出高低好坏。形容水平相当。", s: "唐·陆龟蒙《蠹化》翳叶仰啮，如饥蚕之速，不相上下。”" },
  { w: "不相闻问", p: ["bù", "xiāng", "wén", "wèn"], e: "闻问通消息，通音讯。指没有联系或断绝往来。", s: "《汉书·严助传》于是拜为会稽太守。数年，不闻问。" },
  { w: "不相问闻", p: ["bù", "xiāng", "wèn", "wén"], e: "指没有联系或断绝往来。", s: "无" },
  { w: "不言不语", p: ["bù", "yán", "bù", "yǔ"], e: "不说话，闷声不响。", s: "明·冯梦龙《醒世恒言·吴衙内邻舟赴约》秀娥一心忆着吴衙内，坐在旁边，不言不语，如醉如痴，酒也不沾一滴，箸也不动一动。”" },
  { w: "不言而喻", p: ["bù", "yán", "ér", "yù"], e: "喻了解，明白。不用说话就能明白。形容道理很明显。", s: "《孟子·尽心上》仁义礼智根于心，其生色也，然见于面。盎于背，施于四体，四体不言而喻。”" },
  { w: "不一而足", p: ["bù", "yī", "ér", "zú"], e: "足充足。指同类的事物不只一个而是很多，无法列举齐全。", s: "《公羊传·文公九年》始有大夫，则何以不氏？许夷狄者，不一而足也。”" },
  { w: "不易之论", p: ["bù", "yì", "zhī", "lùn"], e: "易改变。不可更改的言论。形容论断或意见非常正确。", s: "宋·惠洪《冷斋夜话》卷一○成周三代之际，圣人多生儒中，两汉以下圣人多生佛中，此不易之论也。”" },
  { w: "不远万里", p: ["bù", "yuǎn", "wàn", "lǐ"], e: "不以万里为远。形容不怕路途遥远。", s: "《孟子·梁惠王上》王曰‘叟，不远千里而来，亦将有以利吾国乎？’”" },
  { w: "不在话下", p: ["bù", "zài", "huà", "xià"], e: "指事物轻微，或者理所当然，不值得一提。", s: "元·秦简夫《赵礼让肥》四折以下各随次第加官赐赏，这且不在话下。”" },
  { w: "不正之风", p: ["bù", "zhèng", "zhī", "fēng"], e: "不正当的社会风气。", s: "《抱朴子·辩问》移不正之风，易流遁之俗。”" },
  { w: "不知高下", p: ["bù", "zhī", "gāo", "xià"], e: "指说话做事不知轻重。", s: "明·康海《中山狼》第三折先生，谢得您救俺也，只俺有句不知高下的话儿敢说么？”" },
  { w: "不知就里", p: ["bù", "zhī", "jiù", "lǐ"], e: "就里其中，内情。不知道内幕。", s: "清·宣鼎《夜雨秋灯录·麻疯女邱丽玉》生不知就里，趋近软语，代为卸妆。”" },
  { w: "不知所出", p: ["bù", "zhī", "suǒ", "chū"], e: "①不知道从哪里来的。②不知道该怎么办。", s: "《文选·宋玉》卒愕异物，不知所出。”李善注不知所从来。”" },
  { w: "不知所可", p: ["bù", "zhī", "suǒ", "kě"], e: "不知道该怎么办才好。", s: "《儿女英雄传》第三一回不想这番好意把个可左可右的安公子此时倒弄到左右不知所可。”" },
  { w: "不知所言", p: ["bù", "zhī", "suǒ", "yán"], e: "形容说话内容混乱，无法理解。同不知所云”。", s: "《三国志·蜀书·诸葛亮传》臣不胜受恩感激，今当远离，临表涕零，不知所言。”" },
  { w: "不知所以", p: ["bù", "zhī", "suǒ", "yǐ"], e: "以原因。不明白为什么是这样。指不知道原因。", s: "唐·张彦远《法书要录·购兰亭序》遽见追乎，不知所以。”" },
  { w: "不知所云", p: ["bù", "zhī", "suǒ", "yún"], e: "云说。不知道说得是些么。形容说话内容混乱，无法理解。", s: "三国·蜀·诸葛亮《出师表》临表涕泣，不知所云。”" },
  { w: "不主故常", p: ["bù", "zhǔ", "gù", "cháng"], e: "故常旧的常规、习惯。不拘于老的一套。", s: "《庄子·天运》其声能短能长，能柔能刚，变化齐一，不主故常。”" },
  { w: "不足为法", p: ["bù", "zú", "wéi", "fǎ"], e: "不值得学习、效法。", s: "清·赵翼《瓯北诗话·李青莲诗》开口便说《大雅》不作，骚人斯起，然词多哀怨，已非正声；至杨、马益流宕。建安以后更绮丽，不足…" },
  { w: "不足为意", p: ["bù", "zú", "wéi", "yì"], e: "不值得介意。", s: "明·张居正《答郑范溪》公但自信此心，秉公任直，纷纷之言，不足为意。”" },
  { w: "才大难用", p: ["cái", "dà", "nán", "yòng"], e: "原意是能力强难用于小事◇形容怀才不遇。同材大难用”。", s: "无" },
  { w: "才高气清", p: ["cái", "gāo", "qì", "qīng"], e: "指才能高超而气质清峻。", s: "唐·韩愈《与孟东野书》足下才高气清，行古道，处今世，无田而衣食，事亲左右无违，足下用心勤矣。”" },
  { w: "才气过人", p: ["cái", "qì", "guò", "rén"], e: "才才能；气气魄。才能气魄胜过一般的人。", s: "《史记·项羽本纪》籍长八尺余，力能扛鼎，才气过人，虽吴中子弟皆己惮籍矣。”" },
  { w: "臣心如水", p: ["chén", "xīn", "rú", "shuǐ"], e: "心地洁净如水。比喻为官清廉。", s: "《汉书·郑崇传》臣门如市，臣心如水。”" },
  { w: "成己成物", p: ["chéng", "jǐ", "chéng", "wù"], e: "自身有所成就，也要使自身以外的一切有所成就。", s: "《礼记·中庸》诚者，非自成己而已也，所以成物也。成己，仁也；成物，知也。性之德也，合内外之道也。”" },
  { w: "成名成家", p: ["chéng", "míng", "chéng", "jiā"], e: "树立名声，成为专家。", s: "《易系·辞下》善不积，不足以成名。”" },
  { w: "成年古代", p: ["chéng", "nián", "gǔ", "dài"], e: "犹言长期以来。", s: "元·刘君锡《来生债》第一折这灶成年古代不烧火，埋上这银子，扒上些灰儿盖着，谁知道灶窝里有银子？”" },
  { w: "成人之美", p: ["chéng", "rén", "zhī", "měi"], e: "成成就。成全别人的好事。", s: "《论语·颜渊》君子成人之美，不成人之恶。小人反是。”" },
  { w: "成事不说", p: ["chéng", "shì", "bù", "shuō"], e: "说解说。原指事情已成，不要在解说；后指事情已过，不要再解说。", s: "《论语·八佾》子闻之曰‘成事不说，遂事不谏，既往不咎。’”邢昺疏‘事已成不可复说也。’" },
  { w: "出其不意", p: ["chū", "qí", "bù", "yì"], e: "其代词，对方；不意没有料到。趁对方没有意料到就采取行动。", s: "《孙子·计篇》攻其无备，出其不意。”" },
  { w: "出人头地", p: ["chū", "rén", "tóu", "dì"], e: "指高人一等。形容德才超众或成就突出。", s: "宋·欧阳修《与梅圣俞书》老夫当避路，放他出一头地也。”" },
  { w: "出人意表", p: ["chū", "rén", "yì", "biǎo"], e: "表外。出乎人们意料之外。", s: "《南史·袁宪传》宪常招引诸生与之谈论新义，出人意表，同辈咸嗟服焉。”宋·苏轼《举何去非换文资状》其论历代所以废兴成败，皆…" },
  { w: "出人意外", p: ["chū", "rén", "yì", "wài"], e: "出于人们的意料之外，都没想到的。", s: "明·凌濛初《初刻拍案惊奇》卷一却又有转眼贫富出人意外，眼前事分毫算不得准的哩！”" },
  { w: "出头之日", p: ["chū", "tóu", "zhī", "rì"], e: "出头摆脱困境等。指从困厄、冤屈、压抑的处境中摆脱出来的日子。", s: "元·无名氏《庞娟夜走马陵道》第三折如今佯推风疾举发，白日里与儿童作戏，到晚间共羊犬同眠。不知几时才得个出头之日。”" },
  { w: "出言成章", p: ["chū", "yán", "chéng", "zhāng"], e: "本意是出言便成为规范，后多用以形容文思敏捷。", s: "《诗经·小雅·都人士》彼都人士，狐裘黄黄，其容不改，出言成章。”" },
  { w: "出言有章", p: ["chū", "yán", "yǒu", "zhāng"], e: "说话有条理。", s: "《诗经·小雅·都人士之什》 彼都人士，狐裘黄黄，其容不改，出言有章。行归于周，万民所望。”" },
  { w: "出一头地", p: ["chū", "yī", "tóu", "dì"], e: "指当避开此人让其高出众人一头之地◇以之比喻高人一着。", s: "宋·欧阳修《与梅圣俞书》读轼（苏轼）书，不觉汗出。快哉快哉！老夫当避路，放他出一头地也。”" },
  { w: "出以公心", p: ["chū", "yǐ", "gōng", "xīn"], e: "指考虑事情以国家和集体的利益为出发点。", s: "无" },
  { w: "出于意表", p: ["chū", "yú", "yì", "biǎo"], e: "指出乎人的意料之外。", s: "唐·张读《宣室志》卷四一夕，风月晴莹，有扣门者，出视之，见一丈夫，衣冠甚伟，仪状秀逸。乔延入与坐，谈议朗畅，出于意表。乔…" },
  { w: "出于意外", p: ["chū", "yú", "yì", "wài"], e: "指出乎人的意料之外。", s: "《黄绣球》第四回自想这件事真出于意外，必须自家投到，中诉明白，不能平白地叫妻子良受诬辱。”" },
  { w: "出语成章", p: ["chū", "yǔ", "chéng", "zhāng"], e: "说出话来就成文章。形容文思敏捷，口才好。", s: "范文澜《唐代佛教·佛教各宗派》玄奘精通汉梵文，又深探佛学，译经出语成章，笔人随写，即可披玩。”" },
  { w: "出自意外", p: ["chū", "zì", "yì", "wài"], e: "出于意料之外。", s: "唐·柳宗元《鈷鉧潭西小丘记》丘之小不能一亩……余怜惜而售之。李深源、元克己时同游，皆大喜，出自意外。”" },
  { w: "从容就义", p: ["cóng", "róng", "jiù", "yì"], e: "就义为正义而死。无所畏惧地为正义事业而牺牲。", s: "宋·朱熹《近思录》感慨杀身者易，从容就义者难。”" },
  { w: "从容自如", p: ["cóng", "róng", "zì", "rú"], e: "不慌不忙，得心应手。", s: "吴伯箫《记一辆纺车》熟练的纺手趁着一线灯光或者朦胧的月色也能摇车，抽线，上线，一切做得从容自如。”" },
  { w: "从容自若", p: ["cóng", "róng", "zì", "ruò"], e: "从容不慌不忙，很镇静；自若自在，如常，保持原样。不慌不忙，沉着镇定。", s: "《旧唐书·刘世龙传》而思礼以为得计，从容自若，尝与相忤者，必引令枉诛。”" },
  { w: "从天而下", p: ["cóng", "tiān", "ér", "xià"], e: "比喻出于意外，突然出现。", s: "《汉书·周亚夫传》直入武库，击鸣鼓。诸侯闻之，以为将军从天而下也。”" },
  { w: "大得人心", p: ["dà", "dé", "rén", "xīn"], e: "人心即民心。指受百姓热烈拥护。", s: "《魏书·昭成子孙传》太祖命督屯田于河北，自五原至棝杨塞外，分农稼，大得人心。”" },
  { w: "大方之家", p: ["dà", "fāng", "zhī", "jiā"], e: "大方大道理。原指懂得大道理的人◇泛指见识广博或学有专长的人。", s: "《庄子·秋水》吾长见笑于大方之家。”" },
  { w: "大经大法", p: ["dà", "jīng", "dà", "fǎ"], e: "根本的原则和法规。", s: "唐·韩愈《与孟尚书》其大经大法，皆亡灭而不救，坏烂而不收。”" },
  { w: "大开大合", p: ["dà", "kāi", "dà", "hé"], e: "形容文思跌荡，放得开，收得拢。", s: "清·赵翼《忧旱》今年天作奇文章，大开大合为弛张。”" },
  { w: "大名难居", p: ["dà", "míng", "nán", "jū"], e: "指盛名之下不易自处", s: "《史记·越王勾践世家》句践以霸，而范蠡称上将军。还反国，范蠡以为大名之下，难以久居……乃装其轻宝珠玉，自与其私徒属乘舟浮…" },
  { w: "大人先生", p: ["dà", "rén", "xiān", "sheng"], e: "旧时指有身分有地位的人。有时带讽刺意味。", s: "晋·刘伶《酒德颂》有大人先生以天地为一朝，万期为须臾，日月为扃牖，八荒为庭衢。”" },
  { w: "大势已去", p: ["dà", "shì", "yǐ", "qù"], e: "大势事情发展的趋势。有利的形势已经丧失，前途已经没有希望。", s: "宋·朱熹《朱子谏类》卷五十一程子说天命之改，莫是大势已去。”" },
  { w: "大是大非", p: ["dà", "shì", "dà", "fēi"], e: "指带有原则性、根本性的是非问题。", s: "徐迟《歌德巴赫猜想》一页一页的历史写出来了，大是大非，终于有了无私的公论。”" },
  { w: "大天白日", p: ["dà", "tiān", "bái", "rì"], e: "白天。强调跟暮夜黑暗对照。", s: "清·曹雪芹《红楼梦》第十二回大天白日，人来人往，你就在这里忆不方便。”" },
  { w: "大有见地", p: ["dà", "yǒu", "jiàn", "dì"], e: "很有见解。", s: "无" },
  { w: "大有起色", p: ["dà", "yǒu", "qǐ", "sè"], e: "明显地出现好转的样子（多指焕散的工作或觉重的疾病）。", s: "清·张集馨《道咸宦海见闻录》皖省惟英、霍有零贼，余亦肃清，南中军务，大有起色。”" },
  { w: "大有人在", p: ["dà", "yǒu", "rén", "zài"], e: "形容某一种人为数不少。", s: "《资治通鉴·隋纪炀帝大业十一年》帝至东都，顾眄街衢，谓侍臣曰‘犹大有人在。’意谓向日平杨玄感，杀人尚少故也。”" },
  { w: "大有文章", p: ["dà", "yǒu", "wén", "zhāng"], e: "指话语、文章、或已表露的现象之中，很有令人难以捉摸的意思或别的情况。", s: "清·无名氏《三侠五义》艾虎听了，暗暗思忖道‘这话语之中大有文章。’”" },
  { w: "大张声势", p: ["dà", "zhāng", "shēng", "shì"], e: "大造声势，扩大影响。", s: "《宋史·李师中传》今修筑必广发兵，大张声势。”" },
  { w: "大中至正", p: ["dà", "zhōng", "zhì", "zhèng"], e: "极为公正，不偏不倚。", s: "明·王守仁《传习录》上卷不知先生居夷三载，处困养静，精一之功，固已超入圣城，粹然大中至正之归矣。”" },
  { w: "大做文章", p: ["dà", "zuò", "wén", "zhāng"], e: "比喻为达到某种目的，在某些问题上横生枝节，或借题发挥，扩大事态。", s: "无" },
  { w: "代代相传", p: ["dài", "dài", "xiāng", "chuán"], e: "一代接一代地相继传下去。", s: "无" },
  { w: "代人受过", p: ["dài", "rén", "shòu", "guò"], e: "受承受，担待；过过失，过错。替别人承担过错的责任。", s: "陶菊隐《北洋军阀统治时期史话》各省系军阀慑于人民的巨大力量，都不肯代人受过，曹辊也就不敢一意孤行。”" },
  { w: "当家作主", p: ["dāng", "jiā", "zuò", "zhǔ"], e: "本指主管家政，有权对家事做出决定。比喻在单位或国家中居主人翁地位。", s: "沙汀《风浪》申大嫂可以说是全家真正当家作主的人，申大哥也事事听她安排。”" },
  { w: "当头对面", p: ["dāng", "tóu", "duì", "miàn"], e: "当面商量或面对面辩论。", s: "无" },
  { w: "当行出色", p: ["dāng", "háng", "chū", "sè"], e: "指做本行本业的事，成绩特别显著。", s: "《负曝闲谈》第十一回涂了又涂，改了又改，看看终究不能当行出色，急得他抓耳挠腮。”" },
  { w: "道德文章", p: ["dào", "dé", "wén", "zhāng"], e: "指思想品德和学识学问。", s: "宋·辛弃疾《渔家傲·为余伯熙察院寿》道德文章传几世，到君合上三台位。”" },
  { w: "道东说西", p: ["dào", "dōng", "shuō", "xī"], e: "指乱加谈论。同道西说东”。", s: "《刘知远诸宫调·知远别三娘太原投事》自入舍做女婿，觑俺咱似儿戏，使着后，道东说西畅憋气。”" },
  { w: "道高德重", p: ["dào", "gāo", "dé", "zhòng"], e: "道德高尚，很有威信。", s: "艾芜《回家》水元伯伯打发人来叫丁永森到他家去坐，丁永森知道定是讲这件不愉快的事情的，但因为水元伯伯是这村里道高德重的人，…" },
  { w: "道合志同", p: ["dào", "hé", "zhì", "tóng"], e: "指彼此的志趣理想一致。", s: "三国·魏·曹植《陈审举表》昔伊尹之为媵臣，至贱也；吕尚之处屠，至陋也。及其见举于汤武、周文，诚道合志同，玄谟神通。”" },
  { w: "道同义合", p: ["dào", "tóng", "yì", "hé"], e: "犹言道合志同。", s: "清·李渔《蜃中楼·婚诺》他第三个兄弟钱塘君与我道同义合，相得甚欢。”" },
  { w: "道同志合", p: ["dào", "tóng", "zhì", "hé"], e: "犹言道合志同。", s: "宋·司马光《又谢庞参政启》尝托僚寀，获友高明，道同志合，出处如一。”" },
  { w: "道西说东", p: ["dào", "xī", "shuō", "dōng"], e: "指乱加谈论。", s: "《敦煌变文集·茶酒论》阿你两个，何用匆匆？阿谁许你，各拟论功！言词相毁，道西说东。”" },
  { w: "道学先生", p: ["dào", "xué", "xiān", "shēng"], e: "指思想、作风特别迂腐的读书人。", s: "明·凌濛初《二刻拍案惊奇》卷十二仲友喜的是俊爽名流，恼的是道学先生。”" },
  { w: "道在人为", p: ["dào", "zài", "rén", "wéi"], e: "犹言事在人为。", s: "《金瓶梅词话》第三一回净云不打紧，道在人为，你见那里又一位王勃殿试来了。”" },
  { w: "得马失马", p: ["dé", "mǎ", "shī", "mǎ"], e: "指世事多变，得失无常。", s: "典出《淮南子·人间训》。见得马生灾”。" },
  { w: "得人死力", p: ["dé", "rén", "sǐ", "lì"], e: "死力以死效力。得到别人以死来效力。形容非常得人拥护。", s: "无" },
  { w: "得失在人", p: ["dé", "shī", "zài", "rén"], e: "指人生的胜利失败就取决与本人的努力与否。强调人的主观能动性。", s: "无" },
  { w: "得意门生", p: ["dé", "yì", "mén", "shēng"], e: "得意称心如意；门生亲授业的弟子或科举中试者对座师的自称◇泛指学生。最满意的弟子或学生。", s: "清·文康《儿女英雄传》第二回他虽然和咱们满州汉军隔旗，却是我第一个得意门生，他待我也实在亲热，那个人将来不可限量。”" },
  { w: "得意之色", p: ["dé", "yì", "zhī", "sè"], e: "得意称心如意。因非常称心如意而露出傲慢的神色。", s: "鲁迅《书信集·答有恒先生》血的游戏已经开头，而角色又是青年，并且有得意之色。”" },
  { w: "得意之作", p: ["dé", "yì", "zhī", "zuò"], e: "指自己认为非常满意的作品。", s: "曹靖华《哪有闲情话年月》作者仿佛要为我开小型展览会似的，把自己的得意之作都陈列在我面前了。”" },
  { w: "地利人和", p: ["dì", "lì", "rén", "hé"], e: "地利地理的优势；人和得人心。表示优越的地理条件和群众基础。", s: "《孟子·公孙丑下》天时不如地利，地利不如人和。”" },
  { w: "地平天成", p: ["dì", "píng", "tiān", "chéng"], e: "平治平；成成功。原指禹治水成功而使天之生物得以有成◇常比喻一切安排妥帖。", s: "《尚书·大禹谟》帝曰‘俞！地平天成，六府三事，允治。万世永赖，时乃工。’”《左传·文公十八年》舜臣尧，举八恺，使主后土，…" },
  { w: "地上天官", p: ["dì", "shàng", "tiān", "guān"], e: "比喻社会生活繁华安乐。", s: "无" },
  { w: "东道主人", p: ["dōng", "dào", "zhǔ", "rén"], e: "泛指接待或宴客的主人。同东道主”。", s: "《周书·文帝纪上》令亲人蔡儁作牧河济，厚相恩赡，以为东道主人。”" },
  { w: "东方将白", p: ["dong", "fang", "jiang", "bai"], e: "指天将破晓。", s: "无" },
  { w: "东风人面", p: ["dōng", "fēng", "rén", "miàn"], e: "指一年一度的春风依旧，而当年邂逅含情之人却不得重见。", s: "清·缪艮《珠江名花小传》第三卷迨素秋过访，询知其迁徒梧江，东风人面，未尝不有崔护当年之感云。”" },
  { w: "东来西去", p: ["dōng", "lái", "xī", "qù"], e: "指行人来来往往。", s: "唐·李商隐《关门柳》诗永定河边一行柳，依依长发故年春。东来西去人情薄，不为清阴减路尘。”" },
  { w: "东流西上", p: ["dōng", "liú", "xī", "shàng"], e: "水向东流，人往西走。比喻人们对故乡的思恋。", s: "无" },
  { w: "东南之美", p: ["dōng", "nán", "zhī", "měi"], e: "指东南人物中之佼佼者。", s: "晋·潘尼《赠陆机出为吴王郎中令》东南之美，曩惟延州；显允陆生，于今鲜俦。”" },
  { w: "东山之志", p: ["dōng", "shān", "zhī", "zhì"], e: "指隐居的念头。", s: "《晋书·谢安传》安虽受朝寄，然东山之志始末不渝，每形于言色。”" },
  { w: "东西易面", p: ["dōng", "xi", "yì", "miàn"], e: "指东西方向颠倒◇比喻是非颠倒，视听淆乱。", s: "汉·贾谊《新书·审微》事之適乱，如地形之惑人也，机渐而往，俄而东西易面，人不自知也。故墨子见衢路而哭之，悲一跬而缪千里也…" },
  { w: "东张西张", p: ["dōng", "zhāng", "xī", "zhāng"], e: "形容这里那里地到处看。同东张西望”。", s: "方志敏《可爱的中国》三人挤在一个舱角里，看他们的眼睛，偷偷地东张西张的神气。”" },
  { w: "动不失时", p: ["dòng", "bù", "shī", "shí"], e: "时时宜，时机。行动不失时机。指不做不切合时宜的事。", s: "汉·刘安《淮南子·人间训》圣人敬小慎微，动不失机。”" },
  { w: "动之以情", p: ["dòng", "zhī", "yǐ", "qíng"], e: "用感情来打动他的心。", s: "无" },
  { w: "多情多义", p: ["duō", "qíng", "duō", "yì"], e: "指重情谊。", s: "《品花宝鉴》第三回聘才已知富三是个热心肠、多情多义的人。”" },
  { w: "多言多语", p: ["duō", "yán", "duō", "yǔ"], e: "指不该说而说。", s: "《水浒传》第六一回卢俊义道‘你妇人家省得什么！宁可信其有，不可信其无。自古祸出师人口，必主吉凶。我既主意定了，你都不得多…" },
  { w: "多言或中", p: ["duō", "yán", "huò", "zhōng"], e: "或有的。中正好对上。指多方面讨论之，有的可能中的。", s: "《云笈七签》卷七十凡我同志，庶几于此者，要在细求真诀，务以师授，不可以谀闻浅说、多言或中之义，所希企及矣。”" },
  { w: "儿女成行", p: ["ér", "nǚ", "chéng", "háng"], e: "可以把儿女排成一个行列。形容子女很多。", s: "唐·杜甫《赠卫八处士》昔别君未婚，儿女忽成行。”" },
  { w: "儿女情长", p: ["ér", "nǚ", "qíng", "cháng"], e: "指过分看重爱情。", s: "南朝·梁·钟嵘《诗品》中尤恨其儿女情多，风云气少。”" },
  { w: "儿女之情", p: ["ér", "nǚ", "zhī", "qíng"], e: "特指男女之间缠绵的恋情。同儿女私情”。", s: "无" },
  { w: "而今而后", p: ["ér", "jīn", "ér", "hòu"], e: "而语助词。从今以后。", s: "《吕氏春秋·恃君览·长利》臣而今而后知吾先君周公之不若太公望封之知也。”《旧唐书·卢藏用传》而今而后，焚蓍龟，毁律历，废…" },
  { w: "二分明月", p: ["èr", "fēn", "míng", "yuè"], e: "古人认为天下明月共三分，扬州独占二分。原用于形容扬州繁华昌盛的景象。今用以比喻当地的月色格外明朗。", s: "唐·徐凝《忆扬州》诗萧娘脸上难生泪，桃叶眉头易得愁。天下三分明月夜，二分无赖是扬州。”" },
  { w: "二话不说", p: ["èr", "huà", "bù", "shuō"], e: "不说任何别的话。指立即行动。", s: "老舍《四世同堂》九八‘日本鬼子完蛋了，投降了，’方六低声回答。丁约翰象在教堂里说‘阿门’那样，把眼睛闭了一闭。二话不说，…" },
  { w: "二三君子", p: ["èr", "sān", "jūn", "zǐ"], e: "犹二三子。", s: "《左传·僖公二十四年》主晋祀者，非君而谁，天实置之，而二三子以为己力，不亦诬乎。”《汉书·楚元王传》故下明诏，试《左氏》…" },
  { w: "二三其德", p: ["èr", "sān", "qí", "dé"], e: "二三不专一。形容三心二意。", s: "《诗经·卫风·氓》士也罔极，二三其德。”" },
  { w: "二三其意", p: ["èr", "sān", "qí", "yì"], e: "即三心二意。指心意不专一，反复无常。", s: "《三国志·袁绍传》裴松之注引《汉晋春秋》是时外为御难，内实乞罪，既不见赦，而屠各二三其心，临阵叛戾。”" },
  { w: "二心两意", p: ["èr", "xīn", "liǎng", "yì"], e: "形容意志不专一、不坚定。", s: "汉·王充《论衡·时》夫地之神，用心等也。人民无状，加罪行罚，非有二心两意，前后相反也。”" },
  { w: "二心三意", p: ["èr", "xīn", "sān", "yì"], e: "想这样又想那样。形容意念不专，主意不定。同三心二意”。", s: "明·方汝浩《禅真逸史》第六回念佛是一桩正事，岂有二心三意？”" },
  { w: "发人深思", p: ["fā", "rén", "shēn", "sī"], e: "深无限，没有穷尽。启发人深入地思考。形容语言或文章有深刻的含意，耐人寻味。", s: "唐·刘禹锡《柳花词三进首（其二）》轻飞不假风，轻落不委地。撩乱舞晴空，发人无限思。”" },
  { w: "法出多门", p: ["fǎ", "chū", "duō", "mén"], e: "门门径。指各部门各自为政，自立法制，使法令不能统一，无从执行。", s: "北宋·欧阳修《新唐书·刘贲传》或正刑于外则破律于中，法出多门，人无所措。”" },
  { w: "法出一门", p: ["fǎ", "chū", "yī", "mén"], e: "指法律统一，前后一致，不能随意变通。", s: "《艺文类聚》卷五四引晋杜预《奏事》法出一门，然后人知恒禁，吏无淫巧，政明于上，民安于下。”" },
  { w: "法无二门", p: ["fǎ", "wú", "èr", "mén"], e: "指法律统一，前后一致，不能随意变通。同法出一门”。", s: "《金史·高德基传》有犯罪当死者，宰相欲从末减。德基曰‘法无二门，失出犹失入也。’不从。”" },
  { w: "方外之人", p: ["fāng", "wài", "zhī", "rén"], e: "方外世外。原指言行超脱于世俗礼教之外的人◇指僧道。", s: "《庄子·大宗师》彼游方之外者也。”" },
  { w: "非同小可", p: ["fēi", "tóng", "xiǎo", "kě"], e: "小可寻常的。指情况严重或事情重要，不能轻视。", s: "元·孟汉卿《魔合罗》第三折”萧令史，我与你说，人命事关天关地，非同小可！”" },
  { w: "分三别两", p: ["fēn", "sān", "bié", "liǎng"], e: "详细分说；清楚，明白。同分星擘两”。", s: "老舍《牛天赐传》二十更使他惭愧的是，他分三别两，谁的是谁的。”" },
  { w: "分文不名", p: ["fēn", "wén", "bù", "míng"], e: "名占有。一分钱一个铜板也没有。比喻非常贫困。", s: "无" },
  { w: "分文不取", p: ["fēn", "wén", "bù", "qǔ"], e: "一个钱也不要。比喻不计报酬。", s: "明·冯梦龙《醒世恒言·一文钱小隙造奇冤》又且一清如水，分文不取。”" },
  { w: "分文未取", p: ["fēn", "wén", "wèi", "qǔ"], e: "一个钱也不要。比喻不计报酬。同分文不取”。", s: "无" },
  { w: "分形同气", p: ["fēn", "xíng", "tóng", "qì"], e: "形容父母与子女的关系十分密切。", s: "《吕氏春秋·精通》父母之于子也，子之于父母也，一体而两分，同气而异息。”" },
  { w: "风和日美", p: ["fēng", "hé", "rì", "měi"], e: "微风和畅，阳光明丽。同风和日丽”。", s: "清·黄宗羲《敬槐诸君墓志铭》风和日美，余掉短胕，老母揭女孙泛汝仇湖。”" },
  { w: "风流才子", p: ["fēng", "liú", "cái", "zǐ"], e: "旧指洒脱不拘，富有才学的人。", s: "唐·元稹《莺莺传》风流才子多春思，肠断萧娘一纸书。”" },
  { w: "风流人物", p: ["fēng", "liú", "rén", "wù"], e: "风流英俊的、杰出的。指对一个时代有很大影响的人物。有时也指举止潇洒或惯于调情的人。", s: "宋·苏轼《念奴娇·赤壁怀古》词大江东去，浪淘尽，千古风流人物。”" },
  { w: "风前月下", p: ["fēng", "qián", "yuè", "xià"], e: "指良辰美景。", s: "唐·刘禹锡《洛中逢白监同话游梁之乐因寄宣武令孤相公》诗借问风前兼月下，不知何客对胡床。”" },
  { w: "风清月白", p: ["fēng", "qīng", "yuè", "bái"], e: "微风清凉，月色皎洁。形容夜景幽美宜人。同风清月皎”。", s: "宋·欧阳修《采桑子》词风清月白偏宜夜，一片琼田。”" },
  { w: "风清月明", p: ["fēng", "qīng", "yuè", "míng"], e: "微风清凉，月光明朗。形容夜景美好。同风清月朗”。", s: "明·刘基《横碧楼记》又闻柯亭有美竹，可为笛，风清月明，登楼一吹，可以来凤凰，惊蛰龙，真奇事也。”" },
  { w: "风情月思", p: ["fēng", "qíng", "yuè", "sī"], e: "指男女相互爱恋的情思。亦作风情月意”。", s: "明·高濂《玉簪记·合庆》京兆府当年指腹，女贞观重会玉簪。慢写出风情月思，画堂前侑酒承欢。”明·杨柔胜《玉环记·韦皋延宾》…" },
  { w: "风情月意", p: ["fēng", "qíng", "yuè", "yì"], e: "指男女相互爱恋的情思。同风情月思”。", s: "明·兰陵笑笑生《金瓶梅词话》第九回眉似初春柳叶，超着雨恨云愁；脸如三月桃花，暗带着风情月意。”" },
  { w: "风言风语", p: ["fēng", "yán", "fēng", "yǔ"], e: "没有根据的、不怀好意的、带有讥讽的话。另指私下议论暗中传说。", s: "汉·焦赣《易林》华言风语，乱相诳误。”" },
  { w: "风云人物", p: ["fēng", "yún", "rén", "wù"], e: "指活跃一时，言论行为能影响大局的人物。", s: "毛泽东《别了，司徒雷登》因此被马歇尔看中，做了驻华大使，成为马歇尔系统中的风云人物之一。”" },
  { w: "风云之志", p: ["fēng", "yún", "zhī", "zhì"], e: "像风云那样雄大高远的志向。", s: "北周·庚信《周兖州剌史广饶公宇文公神道碑》始游庠塾，不无儒者之荣；或见兵书，遂有风云之志。”" },
  { w: "夫子自道", p: ["fū", "zǐ", "zì", "dào"], e: "指本意是说别人好处，而事实上却正道着了自己。也用在不好的一面，意思是指摘别人，却正指摘了自己。", s: "《论语·宪问》子曰‘君子有道者三，我无能焉；仁者不忧，智者不惑，勇者不惧。’子贡曰‘夫子自道也。’”" },
  { w: "高才大德", p: ["gāo", "cái", "dà", "dé"], e: "高才有杰出的才能。大德有极高尚的品德。才能和品德都很好。", s: "无" },
  { w: "高才大学", p: ["gāo", "cái", "dà", "xué"], e: "高才才能杰出。大学学识渊博。才能高超，学识渊博。亦作高才博学”、高才硕学”。", s: "无" },
  { w: "高高在上", p: ["gāo", "gāo", "zài", "shàng"], e: "原指地位高，现在形容领导者脱离实际，脱离群众。", s: "《诗经·周颂·敬之》无曰高高在上，陟降厥士，日监在兹。”" },
  { w: "高情远意", p: ["gāo", "qíng", "yuǎn", "yì"], e: "高尚的品格或情趣。同高情远致”。", s: "宋·胡仔《苕溪渔隐丛话前集·西昆体》义山诗世人但称颂其巧丽，至与温庭筠齐名。盖俗学只见其皮肤，其高情远意，皆不识也。”" },
  { w: "高山流水", p: ["gāo", "shān", "liú", "shuǐ"], e: "比喻知己或知音。也比喻乐曲高妙。", s: "《列子·汤问》伯牙鼓琴，志在登高山，钟子期曰‘善哉，峨峨兮若泰山。’志在流水，曰‘善哉，洋洋兮若江河。’”" },
  { w: "高头大马", p: ["gāo", "tóu", "dà", "mǎ"], e: "指体形高大的马。也比喻人的体形高大。", s: "清·禇人获《隋唐演义》第十一回这个人浑身都是新衣服，铺盖齐整，随身有兵器，骑的是高头大马。”" },
  { w: "高下其手", p: ["gāo", "xià", "qí", "shǒu"], e: "犹言上下其手。比喻玩弄手法，串通做弊。", s: "宋·王辟之《渑水燕谈录·官制》五代以来，诸州马步军虞侯以衙校为之，太祖虑其任私，高下其手，乃置司寇参军，以进士、‘九经’…" },
  { w: "高下在手", p: ["gāo", "xià", "zài", "shǒu"], e: "犹言上下其手。比喻玩弄手法，串通做弊。同高下其手”。", s: "宋·叶適《观文殿学士知枢密院事陈公文集序》同列或二心二意，高下在手，必正色力争，宁亟去，无苟徇，亦以此见排于俗。”" },
  { w: "高下在心", p: ["gāo", "xià", "zài", "xīn"], e: "高下比喻伸和屈。原意是做事要斟酌情况，采取适当办法◇形容能胸有成竹地处理事情。", s: "《左传·宣公十五年》天方授楚，未可与争，虽晋之强，能违天乎？谚曰高下在心。”" },
  { w: "公道合理", p: ["gōng", "dào", "hé", "lǐ"], e: "指处理事情公正符合情理。同公平合理”。", s: "西戎《纠纷》工要评的公道合理，确实是件不容易的事。”" },
  { w: "公明正大", p: ["gōng", "míng", "zhèng", "dà"], e: "公正无私，光明磊落。", s: "清·陈确《翠薄山房帖》若一本于公明正大之心，则岂直如此而已。”" },
  { w: "公平合理", p: ["gōng", "píng", "hé", "lǐ"], e: "指处理事情公正符合情理。", s: "毛泽东《三大运动的伟大胜利》只要美国政府愿意在公平合理的基础上解决问题，不再如过去那样用种种可耻的方法破坏和阻挠谈判的进…" },
  { w: "公是公非", p: ["gōng", "shì", "gōng", "fēi"], e: "公认的是非。", s: "唐·刘禹锡《天论上》人能胜乎天者，法也。法大行，则是为公是，非为公非，天下之人蹈道必赏，违之必罚。”" },
  { w: "公之于众", p: ["gōng", "zhī", "yú", "zhòng"], e: "公公开；之代指事物的内容；于向；众大众。把事情真相向大家公布。", s: "无" },
  { w: "古今中外", p: ["gǔ", "jīn", "zhōng", "wài"], e: "指从古代到现代，从国内到国外。泛指时间久远，空间广阔。", s: "茅盾《子夜》九翻遍了古今中外的历史，没有一个国家曾经用这种所谓示威运动而变成了既富且强。”" },
  { w: "故人之意", p: ["gù", "rén", "zhī", "yì"], e: "故人旧友。指老朋友的情意。", s: "西汉·司马迁《史记·范雎蔡泽列传》然公之所以得无死者，以绨袍恋恋，有故人之意，故释公。”" },
  { w: "故作高深", p: ["gù", "zuò", "gāo", "shēn"], e: "本来并不高深，故意装出高深的样子。多指文章故意用些艰深词语，掩饰内容的浅薄。", s: "无" },
  { w: "官官相为", p: ["guān", "guān", "xiāng", "wéi"], e: "指官员之间互相包庇。同官官相护”。", s: "元·关汉卿《蝴蝶梦》第二折你都官官相为倚亲属，更做道国戚皇族。”" },
  { w: "官样文章", p: ["guān", "yàng", "wén", "zhāng"], e: "旧时官场中有固定格式和套语的例行公文。比喻光注意形式，没有实际内容的空话，或照例敷衍的虚文滥调。", s: "宋·吴处厚《青箱杂记·文章官样》王安国曰‘文章格调须是官样。’”" },
  { w: "光明正大", p: ["guāng", "míng", "zhèng", "dà"], e: "原指明白不偏邪。现多指心怀坦白，言行正派。", s: "宋·朱熹《朱子语类》卷七三圣人所说底话，光明正大，须是先理会光明正大底纲领条目。”" },
  { w: "国将不国", p: ["guó", "jiāng", "bù", "guó"], e: "国家将无法维持下去了。指国家的局势很坏，有亡国的危险。", s: "清·曾朴《孽海花》第三十二回庄寿香号称名臣，听说在和议开始时，他主张把台湾赠英……国将不国，这才是糊涂到底了呢！”" },
  { w: "国无二君", p: ["guó", "wú", "èr", "jūn"], e: "一个国家不能有两个皇帝。", s: "《礼记·丧服四制》天无二日，土无二王，国无二君，家无二尊。”" },
  { w: "好好先生", p: ["hǎo", "hǎo", "xiān", "shēng"], e: "与人无争，只求相安无事的人。", s: "南朝·宋·刘义庆《世说新语·言语》南郡庞士元闻司马德操在颍川”刘孝标注引《司马徽别传》载司马徽称一切东西皆佳”，故有好好…" },
  { w: "好梦不长", p: ["hǎo", "mèng", "bù", "cháng"], e: "指不切实际的幻想是不能实现的，只能存在于梦幻之中。", s: "无" },
  { w: "好梦难成", p: ["hǎo", "mèng", "nán", "chéng"], e: "在睡眠时，要想做个好梦也是不轻而易举的。比喻美好的幻想难以变成现实。", s: "宋·聂胜琼《鹧鸪天·寄李之问》寻好梦，梦难成；有谁知我此时情。枕前泪共帘前雨，隔个窗儿滴到明。" },
  { w: "好声好气", p: ["hǎo", "shēng", "hǎo", "qì"], e: "形容语调柔和，态度温和。", s: "无" },
  { w: "好心好意", p: ["hǎo", "xīn", "hǎo", "yì"], e: "指怀着善意。", s: "老舍《茶馆》第三幕我好心好意来告诉你，你可不能卖了我呀！”" },
  { w: "好言好语", p: ["hǎo", "yán", "hǎo", "yǔ"], e: "好美好，友善。指友善和中听的言语。", s: "洪深《香稻米》第三幕我晓得乡下人是刁恶不过，好言好语不肯听的！”" },
  { w: "合二为一", p: ["hé", "èr", "wéi", "yī"], e: "指将两者合为一个整体。", s: "清·袁枚《新齐谐·佟觭角》一人劈面来，急走如飞，势甚猛，傅不及避，两胸相撞，竟与己身合二为一。”" },
  { w: "合两为一", p: ["hé", "liǎng", "wéi", "yī"], e: "指将两者合为一个整体。同合二为一”。", s: "《后汉书·杨震传》伏见诏书为阿母兴起津城门内第舍，，连里竟街，雕修缮饰，穷极巧伎。”李贤注合两坊而为一宅。”" },
  { w: "合情合理", p: ["hé", "qíng", "hé", "lǐ"], e: "符合情理。", s: "陈残云《山谷风烟》第11章黄为民心情显得轻松，觉得周祺这个人很可爱，既有原则，又能合情合理地帮助他解除思想包袱。”" },
  { w: "何去何从", p: ["hé", "qù", "hé", "cóng"], e: "去离开；从跟随。离开哪儿，走向哪儿。多指在重大问题上选择什么方向。", s: "战国·楚·屈原《卜居》此孰吉孰凶？何去何从？”" },
  { w: "何所不为", p: ["hé", "suǒ", "bù", "wéi"], e: "用反问的语气表示无所不为。", s: "无" },
  { w: "何所不有", p: ["hé", "suǒ", "bù", "yǒu"], e: "用反问的语气表示无所不有。", s: "宋·周密《齐东野语·黄婆》此事前所未闻，是知穷荒绝檄，天奇地怪，亦何所不有，未可以见闻所未及，遂以为诞也。”" },
  { w: "何所不至", p: ["hé", "suǒ", "bù", "zhì"], e: "①用反问的语气表示无所不至。指没有达不到的地方。②指什么坏事都干。", s: "无" },
  { w: "和而不同", p: ["hé", "ér", "bù", "tóng"], e: "和和睦；同苟同⊥睦地相处，但不随便附和。", s: "《论语·子路》君子和而不同，小人同而不和。”" },
  { w: "后来居上", p: ["hòu", "lái", "jū", "shàng"], e: "后来的超过先前的。有以称赞后起之秀超过前辈。", s: "《史记·汲郑列传》陛下用群臣，如积薪耳，后来者居上。”" },
  { w: "后生小子", p: ["hòu", "shēng", "xiǎo", "zǐ"], e: "指年轻晚辈。", s: "宋·俞文豹《吹剑四录》恐数十年后老成凋丧，后生小子，不知根柢，耳濡目染，目变而复还。”" },
  { w: "花花公子", p: ["huā", "huā", "gōng", "zǐ"], e: "指衣着华丽，只会吃喝玩乐，不务正业的、有钱有势人家的女弟。", s: "清·张南庄《何典》第六回活死人便知他是个仗官托势的花花公子了。”" },
  { w: "花前月下", p: ["huā", "qián", "yuè", "xià"], e: "本指游乐休息的环境◇多指谈情说爱的处所。", s: "唐·白居易《老病》诗尽听笙歌夜醉眠，若非月下即花前。”" },
  { w: "话里有话", p: ["huà", "lǐ", "yǒu", "huà"], e: "话里含有别的意思。", s: "清·曹雪芹《红楼梦》第第一百十回邢夫人等听了话中有话，不想到自己不令凤姐便宜行事，反说‘凤丫头果然有些不用心。’”" },
  { w: "话言话语", p: ["huà", "yán", "huà", "yǔ"], e: "犹谈话。", s: "柳青《创业史》第二部第七章并且话言话语间，很不满意郭振山。”" },
  { w: "话中有话", p: ["huà", "zhōng", "yǒu", "huà"], e: "话里含有别的意思。", s: "清·曹雪芹《红楼梦》第第一百十回邢夫人等听了话中有话，不想到自己不令凤姐便宜行事，反说‘凤丫头果然有些不用心。’”" },
  { w: "回生起死", p: ["huí", "shēng", "qǐ", "sǐ"], e: "起死回生。形容医道高明，能把垂死的人求活。也用以形容挽回了看来没有希望的事物。", s: "明·施耐庵《水浒传》第七十回回生起死妙难言，拯惫扶危更多益。”" },
  { w: "回天无力", p: ["huí", "tiān", "wú", "lì"], e: "回天比喻力量大，能移转极难挽回的时势；无力没有力量。比喻局势或病情严重，已无法挽救。", s: "清·冯起凤《昔柳摭谈·秋风自悼》后探得的耗，万箭攒心，脏腑欲裂。但木已成舟，回天乏术。”" },
  { w: "回天之力", p: ["huí", "tiān", "zhī", "lì"], e: "原比喻言论正确，极有力量，影响深远。现多比喻能挽回严重局势的力量。", s: "《魏书·帝纪篇末史臣总论》佞阉处当轴之权，婢媪擅回天之力，卖官鬻狱，乱政淫刑。”《新唐书·张玄素传》张公论事，有回天之力…" },
  { w: "会道能说", p: ["huì", "dào", "néng", "shuō"], e: "形容很会讲话。同能说会道”。", s: "明·无名氏《渔樵闲话》第二折但熟甜瓜软处偏捏，蜡枪头会道能说。”" },
  { w: "极而言之", p: ["jí", "ér", "yán", "zhī"], e: "从最极端的情况来说。指把话说到头。", s: "无" },
  { w: "记问之学", p: ["jì", "wèn", "zhī", "xué"], e: "只是记诵书本，以资谈助或应答问难的学问。指对学问未融会贯通，不成体系。", s: "《礼记·学记》记问之学，不足以为人师，必也其听语乎？”" },
  { w: "家无常礼", p: ["jiā", "wú", "cháng", "lǐ"], e: "指家人之间平居不必拘礼。", s: "无" },
  { w: "家无二主", p: ["jiā", "wú", "èr", "zhǔ"], e: "指一家之内，不可以有两个主人，否则会发生争吵，不得安静。", s: "《礼记·坊记》天无二日，土无二王，家无二主，尊无二上。”" },
  { w: "家至人说", p: ["jiā", "zhì", "rén", "shuō"], e: "传到每一家，人人都知道。", s: "《汉书·匡衡传》臣闻教化之流之流，非家至而人说之也。”" },
  { w: "见可而进", p: ["jiàn", "kě", "ér", "jìn"], e: "见到形势有利就进军◇指有把握就行动。", s: "《左传·宣公十二年》见可而进，知难而退，军之善政也。”" },
  { w: "见利思义", p: ["jiàn", "lì", "sī", "yì"], e: "看到货财，要想到道义。", s: "《论语·宪问》见利思义，见危授命，久要不忘平生之言，亦可以为成人矣。”" },
  { w: "见事风生", p: ["jiàn", "shì", "fēng", "shēng"], e: "指遇事雷厉风行。", s: "无" },
  { w: "见事生风", p: ["jiàn", "shì", "shēng", "fēng"], e: "形容遇到事情，兴风作浪。", s: "清·和邦额《夜谭随录·棘闱志异》第少年喜事，每捕风捉影，见事生风。”" },
  { w: "见所不见", p: ["jiàn", "suǒ", "bù", "jiàn"], e: "看到从来没有看到过的。形容事物十分稀罕。同见所未见”。", s: "无" },
  { w: "见所未见", p: ["jiàn", "suǒ", "wèi", "jiàn"], e: "看到从来没有看到过的。形容事物十分稀罕。", s: "汉·扬雄《法言·渊骞》日闻所不闻，见所不见。”" },
  { w: "见义必为", p: ["jiàn", "yì", "bì", "wéi"], e: "指看到正义的事情就去做。", s: "无" },
  { w: "见义当为", p: ["jiàn", "yì", "dāng", "wéi"], e: "指看到正义的事情就去做。同见义必为”。", s: "无" },
  { w: "将天就地", p: ["jiāng", "tiān", "jiù", "dì"], e: "指以高就低。", s: "无" },
  { w: "将无作有", p: ["jiāng", "wú", "zuò", "yǒu"], e: "把没有的事情当作有。", s: "元·康进之《李逵负荆》第一折不要你将无来作有，则要你依前来依后。”" },
  { w: "将无做有", p: ["jiāng", "wú", "zuò", "yǒu"], e: "把没有的事情当作有。同将无作有”。", s: "无" },
  { w: "将心比心", p: ["jiāng", "xīn", "bǐ", "xīn"], e: "设身处地地为别人着想。", s: "宋·朱熹《朱子语类·大学三》俗语所谓将心比心，如此则各得其平矣。”" },
  { w: "今生今世", p: ["jīn", "shēng", "jīn", "shì"], e: "此生此世。指有生之年。", s: "元·关汉卿《窦娥冤》第一折这歪剌骨便是黄花女儿，刚刚扯的一把，也不消这等使性，平空的推了我一交，我肯干罢！就当面赌个誓与…" },
  { w: "今月古月", p: ["jīn", "yuè", "gǔ", "yuè"], e: "指月亮古今如一，而人事代谢无常。", s: "唐·李白《把酒问月》诗今人不见古时月，今月曾经照古人。”" },
  { w: "金声玉色", p: ["jīn", "shēng", "yù", "sè"], e: "比喻人的坚贞品格和操守。", s: "无" },
  { w: "金玉之言", p: ["jīn", "yù", "zhī", "yán"], e: "金玉黄金和美玉。象黄金美玉那样珍贵的话语。比喻可贵而有价值的劝告。", s: "元·王实甫《西厢记》第四本第三折小姐金玉之言，小生一一铭之肺腑。”" },
  { w: "尽其所长", p: ["jìn", "qí", "suǒ", "cháng"], e: "尽全部用出；长特长，擅长。把所擅长的东西全部发挥出来。", s: "无" },
  { w: "尽如人意", p: ["jìn", "rú", "rén", "yì"], e: "尽全；如依照，符合。事情完全符合人的心意。", s: "宋·刘克庄《后村全集·李艮翁礼部墓志铭》然议者但以为恩泽侯挟贵临民，安得尽如人意。”" },
  { w: "尽心尽力", p: ["jìn", "xīn", "jìn", "lì"], e: "指费尽心力。", s: "《晋书·王坦之传》且受遇先帝，绸缪缱绻，并志竭忠贞，尽心尽力，归诚陛下，以报先帝。”" },
  { w: "经国之才", p: ["jīng", "guó", "zhī", "cái"], e: "经治理。有治理国家的才能。形容才能卓著。", s: "晋·葛洪《抱朴子·外篇自序》一时莫论，经国之才。”" },
  { w: "经史百子", p: ["jīng", "shǐ", "bǎi", "zǐ"], e: "经经学，经书，儒家经典著作；史史学，史书；百子诸子百家之学。旧指各个方面的很需要学问。", s: "唐·韩愈《柳子厚墓志铭》子厚少精敏，无不通达……议论证据古今，出入经史百子。”" },
  { w: "经世之才", p: ["jīng", "shì", "zhī", "cái"], e: "经世经济、济民。称治国安民的才能。", s: "唐·杜甫《舟中上水遗怀》古来经济才，何事独罕有。”" },
  { w: "九流百家", p: ["jiǔ", "liú", "bǎi", "jiā"], e: "泛指各种学术流派。同九流一家”。", s: "无" },
  { w: "九流人物", p: ["jiǔ", "liú", "rén", "wù"], e: "指社会上的各种人物。", s: "唐·薛逢《送西川杜司空赴镇》诗莫遣洪炉旷真宰，九流人物待陶甄。”" },
  { w: "九流十家", p: ["jiǔ", "liú", "shí", "jiā"], e: "先秦到汉初各种学说派别的总称。", s: "汉·刘安《七略·诸子略》中把诸子思想分为十家，即儒、道、阴阳、法、名、墨、纵横、杂、农、小说十家，除掉小说家，就称为九流…" },
  { w: "九死一生", p: ["jiǔ", "sǐ", "yī", "shēng"], e: "九表示极多。形容经历很大危险而幸存。也形容处在生死关头，情况十分危急。", s: "战国·楚·屈原《离骚》亦余心之所善兮，虽九死其犹未悔。”刘良注虽九死无一生，未足悔恨。”" },
  { w: "九天九地", p: ["jiǔ", "tiān", "jiǔ", "dì"], e: "原指天上的最高层和地的最深处◇比喻两者相差极远。", s: "《孙子·形篇》善守者藏于九地之下，善攻者动乎九天之上。”" },
  { w: "九原可作", p: ["jiǔ", "yuán", "kě", "zuò"], e: "九原春秋时晋国卿大夫的墓地在九原，因称墓地；作起，兴起。设想死者再生。", s: "《国语·晋语八》赵文子与叔向游于九原，曰‘死者若可作也，吾谁与归？’”" },
  { w: "就地正法", p: ["jiù", "dì", "zhèng", "fǎ"], e: "正法执行死刑。在犯罪的当地执行死刑。", s: "清·吴趼人《二十年目睹之怪现状》第六十五回因为案情重大，并且是积案累累的，就办了个就地正法。”" },
  { w: "就事论事", p: ["jiù", "shì", "lùn", "shì"], e: "按照事物本身的性质来评定是非得失。现常指仅从事物的表面现象孤立、静止、片面地议论。", s: "明·沈德符《万历野获编·词臣论劾首揆》夺情大事，有关纲常，且就事论事，未尝旁及云。”" },
  { w: "就正有道", p: ["jiù", "zhèng", "yǒu", "dào"], e: "向有学问和有道德的人请求指正。", s: "《论语·学而》就有道而正焉。”" },
  { w: "居大不易", p: ["jū", "dà", "bù", "yì"], e: "本为唐代诗人顾况以白居易的名字开玩笑◇比喻居住在大城市，生活不容易维持。", s: "唐·张固《幽闲鼓吹》白尚书应举，初至京，以诗谒著作顾况，顾睹姓名，熟视白公曰‘米价方贵，居亦弗易。’”" },
  { w: "居利思义", p: ["jū", "lì", "sī", "yì"], e: "指临财不苟得。", s: "先秦·左丘明《左传·昭公二十八年》居利思义，在约思纯，有守心而无淫行。”" },
  { w: "军法从事", p: ["jūn", "fǎ", "cóng", "shì"], e: "按照军法严办。", s: "《汉书·王莽传》敢有趁灌犯法，辄以军法从事。”" },
  { w: "开国元老", p: ["kāi", "guó", "yuán", "lǎo"], e: "元老政界年辈资望高的人。指建国时资历声望高的人。", s: "《北史·赵普传》伏见山南东道节度使赵普，开国元老，参谋缔构，厚重有识。”" },
  { w: "开合自如", p: ["kāi", "hé", "zì", "rú"], e: "合按照，适合；自如不受阻碍和拘束。打开闭合不受拘束，形容按照自己的意愿办事。", s: "法·法布尔《蝉》腿可以伸缩，前面的爪能够开合自如。”" },
  { w: "开门见山", p: ["kāi", "mén", "jiàn", "shān"], e: "打开门就能看见山。比喻说话或写文章直截了当谈本题，不拐弯抹角。", s: "唐·刘得仁《青龙寺僧院》此地堪终日，开门见数峰。”" },
  { w: "开云见日", p: ["kāi", "yún", "jiàn", "rì"], e: "开散开。拔开云雾，见到太阳。比喻黑暗已经过去，光明已经到来。也比喻误会消除。", s: "《后汉书·袁绍传》旷若开云见日，何喜如之！”" },
  { w: "开云见天", p: ["kāi", "yún", "jiàn", "tiān"], e: "比喻黑暗已经过去，光明已经到来。也比喻误会消除。同开云见日”。", s: "无" },
  { w: "可心如意", p: ["kě", "xīn", "rú", "yì"], e: "符合心意。", s: "宋·朱敦儒《感皇恩》词称心如意，剩活人间几岁？”" },
  { w: "可有可无", p: ["kě", "yǒu", "kě", "wú"], e: "可以有，也可以没有。指有没有都无关紧要。", s: "清·曹雪芹《红楼梦》第二十回因此把一切都看成浊物，可有可无。”" },
  { w: "来处不易", p: ["lái", "chù", "bù", "yì"], e: "表示事情的成功或财物的取得，经过了艰苦努力。", s: "明·朱柏庐《治家格言》一粥一饭，当思来处不易；半丝半缕，恒念物力维艰。”" },
  { w: "来回来去", p: ["lái", "huí", "lái", "qù"], e: "指动作或说话来回不断地重复。", s: "无" },
  { w: "来情去意", p: ["lái", "qíng", "qù", "yì"], e: "事情的内容和原因。", s: "无" },
  { w: "来去分明", p: ["lái", "qù", "fēn", "míng"], e: "形容手续清楚或为人在财物方面不含糊。", s: "无" },
  { w: "来日方长", p: ["lái", "rì", "fāng", "cháng"], e: "来日未来的日子；方正。将来的日子还长着呢。表示事有可为或将来还有机会。", s: "宋·文天祥《与洪端明云岩书》某到郡后，颇与郡人相安，日来四境无虞，早收中熟，觉风雪如期，晚稻亦可望，惟是力绵求牧，来日方…" },
  { w: "来者居上", p: ["lái", "zhě", "jū", "shàng"], e: "后来居上。原指资格浅的新进反居资格老的旧臣之上◇亦用以称赞后起之秀超过前辈。", s: "语出《史记·汲郑列传》陛下用群臣如积薪耳，后来者居上。”" },
  { w: "来之不易", p: ["lái", "zhī", "bù", "yì"], e: "来之使之来。得到它不容易。表示财物的取得或事物的成功是不容易的。", s: "明·朱柏庐《治家格言》一粥一饭，当思来处不易；半丝半缕，恒念物力维艰。”" },
  { w: "老成见到", p: ["lǎo", "chéng", "jiàn", "dào"], e: "见到见识周到。阅历丰富，见解高明。", s: "清·孔尚任《桃花扇》第三十二出有理，有理！老成见到之言，句句合着鄙意。”" },
  { w: "老大无成", p: ["lǎo", "dà", "wú", "chéng"], e: "老大年老。年纪已老，无所成就。", s: "清·李汝珍《镜花缘》第十回既不能显亲扬名，又不能兴邦定业，碌碌人世，殊愧老大无成。”" },
  { w: "老而不死", p: ["lǎo", "ér", "bù", "sǐ"], e: "本是孙子骂旧友原壤年老无德可称术的话，后亦指年老而不利于社会国家或拖累后辈。", s: "《论语·宪问》子曰‘幼而不孙弟，长而无述焉，老而不死是为贼。”" },
  { w: "老于世故", p: ["lǎo", "yú", "shì", "gù"], e: "老老练，富有经验；世故处世经验。指对社会上的一切有很深的阅历。", s: "唐·韩愈《石鼓歌》中朝大官老于事。”" },
  { w: "老之将至", p: ["lǎo", "zhī", "jiāng", "zhì"], e: "多用作自称衰老之语。", s: "宋·陈亮《谢胡参政启》少不如人，所向墙壁；老之将至，乃羐网罗。”" },
  { w: "乐不可极", p: ["lè", "bù", "kě", "jí"], e: "享乐不可过分。", s: "《礼记·曲礼上》志不可满，乐不可极。”" },
  { w: "乐不可言", p: ["lè", "bù", "kě", "yán"], e: "快乐到了极点，没法用语言来表达。", s: "战国·楚·屈原《大招》魂乎归徕，乐不可言只。”" },
  { w: "乐成人美", p: ["lè", "chéng", "rén", "měi"], e: "乐于成全人家的好事。", s: "无" },
  { w: "乐道好古", p: ["lè", "dào", "hǎo", "gǔ"], e: "以守道为乐，喜爱古制。", s: "无" },
  { w: "乐在其中", p: ["lè", "zài", "qí", "zhōng"], e: "喜欢做某事，并在其中获得乐趣。", s: "《论语·述而》饭疏食饮水，曲肱而枕之，乐亦在其中矣。”" },
  { w: "了然无闻", p: ["le", "rán", "wú", "wén"], e: "了然；完全。完全没有听见。", s: "无" },
  { w: "里出外进", p: ["lǐ", "chū", "wài", "lián"], e: "形容不平整、不整齐。", s: "无" },
  { w: "里通外国", p: ["lǐ", "tōng", "wài", "guó"], e: "暗中勾结外国，阴谋叛国。", s: "鲁迅《且介亭杂文·病后杂谈之余》大则指为‘里通外国’，就是现在之所谓‘汉奸’。”" },
  { w: "理所必然", p: ["lǐ", "suǒ", "bì", "rán"], e: "指按道理必定如此。", s: "《弘明集·神不灭论》若有始也，则不能为终，唯无始也然后始终无穷，此自是理所必然。”" },
  { w: "理所不容", p: ["lǐ", "suǒ", "bù", "róng"], e: "道理所不能允许。", s: "无" },
  { w: "理所当然", p: ["lǐ", "suǒ", "dāng", "rán"], e: "当然应当如此。按道理应当这样。", s: "隋·王通《文中子·魏相篇》非辩也，理当然耳。”" },
  { w: "理之当然", p: ["lǐ", "zhī", "dāng", "rán"], e: "理所当然，理应如此。", s: "明·凌濛初《二刻拍案惊奇》第36卷此原是君家之物，今日来取，理之当然。”" },
  { w: "力不从心", p: ["lì", "bù", "cóng", "xīn"], e: "心里想做，可是力量够不上。", s: "《后汉书·西域传》今使者大兵未能得出，如诸国力不从心，东西南北自在也。”" },
  { w: "两两三三", p: ["liǎng", "liǎng", "sān", "sān"], e: "①指三两为群。②形容稀疏。", s: "无" },
  { w: "两全其美", p: ["liǎng", "quán", "qí", "měi"], e: "美美好。指做一件事顾全到双方，使两方面都得到好处。", s: "元·无名氏《连环计》第三折司徒，你若肯与了我呵，堪可两全其美也。”" },
  { w: "两头白面", p: ["liǎng", "tóu", "bái", "miàn"], e: "白面面粉，比喻糊涂或被人蒙骗。对两头都掩饰、隐瞒。形容作事情表里不一，两面糊弄，两头讨好。", s: "元·康进之《李逵负荆》第二折则为你两头白面搬兴废，转背言词说是非。”" },
  { w: "两头三面", p: ["liǎng", "tóu", "sān", "miàn"], e: "形容作事情表里不一，两面糊弄，两头讨好。同两头白面”。", s: "无" },
  { w: "两相情原", p: ["liǎng", "xiāng", "qíng", "yuán"], e: "指双方互相愿意。", s: "无" },
  { w: "两意三心", p: ["liǎng", "yì", "sān", "xīn"], e: "三心二意。心里想这样又想那样，形容犹豫不决或意志不坚定。", s: "明·冯梦龙《喻世明言》第二十七卷休得慕富嫌贫，两意三心，自贻后悔。”" },
  { w: "流年不利", p: ["liú", "nián", "bù", "lì"], e: "流年旧时算命看相的人称一年中所行之运”；利吉利。指人长年里处于不吉利的状态。谓时运不佳。", s: "明·冯梦龙《醒世恒言·杜子春三入长安》想是我流年不利，故此没福消受，以至如此。”" },
  { w: "流水高山", p: ["liú", "shuǐ", "gāo", "shān"], e: "比喻知己或知音。也比喻乐曲高妙。", s: "《列子·汤问》伯牙鼓琴，志在登高山，钟子期曰‘善哉，峨峨兮若泰山。’志在流水，曰‘善哉，洋洋兮若江河。’”" },
  { w: "流水无情", p: ["liú", "shuǐ", "wú", "qíng"], e: "流水一去不复返，毫无情意。比喻时光消逝，无意停留。", s: "唐·白居易《过元家履信宅》落花不语空辞树，流水无情自入地。”" },
  { w: "流言风语", p: ["liú", "yán", "fēng", "yǔ"], e: "犹言流言蜚语×无根据的话。指背后散布的诽谤性的坏话。", s: "无" },
  { w: "六神无主", p: ["liù", "shén", "wú", "zhǔ"], e: "六神道家认为人的心、肺、肝、肾、脾、胆各有神灵主宰，称为六神。形容惊慌着急，没了主意，不知如何才好。", s: "汉·张衡《髑髅赋》五内皆还，六神皆复。” 明·冯梦龙《醒世恒言》卷二十九吓得知县已是六神无主，不有甚心肠去吃酒。”" },
  { w: "龙生九子", p: ["lóng", "shēng", "jiǔ", "zǐ"], e: "古代传说，龙生有九子，九子不成龙，各有所好。比喻同胞兄弟品质、爱好各不相同。", s: "明·徐应秋《玉芝堂谈荟·龙生九子》龙生九子不成龙，各有所好。”" },
  { w: "论德使能", p: ["lùn", "dé", "shǐ", "néng"], e: "盐有道德的人和使用有才能的人。论，通抡”。", s: "无" },
  { w: "论今说古", p: ["lùn", "jīn", "shuō", "gǔ"], e: "从今到古无所不谈，无不评论。", s: "元·张可久《端正好·渔乐》人间开口笑樵渔，会谈今论古。”" },
  { w: "论世知人", p: ["lùn", "shì", "zhī", "rén"], e: "犹言知人论世。指了解一个人并研究他所处的时代。亦泛指鉴别人物，评论世事。", s: "无" },
  { w: "马如流水", p: ["mǎ", "rú", "liú", "shuǐ"], e: "形容人马熙攘。", s: "元·揭傒斯《居庸行》关门两向当天开，马如流水车如雷。”" },
  { w: "马上看花", p: ["mǎ", "shàng", "kàn", "huā"], e: "指粗略行事，走马看花。", s: "明·天然痴叟《石点头·玉箫女再世玉杯缘》分明马上看花，但过眼即忘，何尝在意。”" },
  { w: "没法没天", p: ["méi", "fǎ", "méi", "tiān"], e: "旧指不顾国法和天理，任意干坏事。现多形容违法乱纪，不受管束。", s: "清·曹雪芹《红楼梦》第一百十回你是那里的这么个横强盗，这样没法没天的！我偏要打这里走。”" },
  { w: "没里没外", p: ["méi", "lǐ", "méi", "wài"], e: "里外不分，指说话做事不分场合。", s: "清·曹雪芹《红楼梦》第56回若一味只管没里没外，不与大人争光，凭他生的怎样，也是该打死的。”" },
  { w: "没世无闻", p: ["méi", "shì", "wú", "wén"], e: "指终身不为人知。", s: "无" },
  { w: "美中不足", p: ["měi", "zhōng", "bù", "zú"], e: "大体很好，但还有不足。", s: "明·凌濛初《初刻拍案惊奇》卷二十七破镜重圆，离而复合，固是好事；但王夫人所遭不幸，失身为妾，又不曾根究奸人，报仇雪恨，尚…" },
  { w: "门生故旧", p: ["mén", "shēng", "gù", "jiù"], e: "指学生和旧友。", s: "无" },
  { w: "梦见周公", p: ["mèng", "jiàn", "zhōu", "gōng"], e: "周公西周初著名政治家，孔子心目中的理想人物。原为孔子哀叹自己体衰年老的辞句◇多作为瞌睡的代称。", s: "无" },
  { w: "梦中说梦", p: ["mèng", "zhōng", "shuō", "mèng"], e: "原为佛家语，比喻虚幻无凭◇也比喻胡言乱语。", s: "《大般若波罗蜜多经》卷五九六复次善勇猛，如人梦中说梦所见种种自性。如是所说梦境自性都无所有∥以故？善勇猛，梦尚非有，况有…" },
  { w: "面面相看", p: ["miàn", "miàn", "xiāng", "kàn"], e: "相视无言。形容因紧张或惊惧而束手无策之状。", s: "清·曹雪芹《红楼梦》第一零五回这一言不打紧，唬得贾政上下人等面面相看，喜得番役家人摩拳擦掌，就要往各处动手。”" },
  { w: "面目全非", p: ["miàn", "mù", "quán", "fēi"], e: "非不相似。样子完全不同了。形容改变得不成样子。", s: "清·蒲松龄《聊斋志异·陆判》举手则面目全非。”" },
  { w: "面目一新", p: ["miàn", "mù", "yī", "xīn"], e: "样子完全改变，有了崭新的面貌。", s: "无" },
  { w: "面是心非", p: ["miàn", "shì", "xīn", "fēi"], e: "指表面上是一套，心底里又是一套，表里不一。", s: "无" },
  { w: "面无人色", p: ["miàn", "wú", "rén", "sè"], e: "脸色没有一点血色。形容恐惧到极点或非常虚弱。", s: "《汉书·李广传》广为匈奴所败，吏士皆无人色，广意气自若。”" },
  { w: "面有难色", p: ["miàn", "yǒu", "nán", "sè"], e: "脸上露出为难的神色。", s: "无" },
  { w: "名从主人", p: ["míng", "cóng", "zhǔ", "rén"], e: "事物以主人所称之名为名。", s: "无" },
  { w: "名高天下", p: ["míng", "gāo", "tiān", "xià"], e: "比喻全国闻名。", s: "《史记·鲁仲连邹阳列传》名高天下，而光烛邻国。”" },
  { w: "名过其实", p: ["míng", "guò", "qí", "shí"], e: "名声超过实际才能。", s: "汉·韩婴《韩诗外传》卷一故禄过其功者削，名过其实者损。”" },
  { w: "名声过实", p: ["míng", "shēng", "guò", "shí"], e: "名声超过实际。指虚有其名。", s: "无" },
  { w: "名士风流", p: ["míng", "shì", "fēng", "liú"], e: "名士指恃才放达不拘小节的人。名士的风度和习气。指有才学而不拘礼法。", s: "《后汉书·方术传论》汉世这所谓名士者，其风流可知矣。”" },
  { w: "名重一时", p: ["míng", "zhòng", "yī", "shí"], e: "名名声；一时当代。一个时期内名声很大，受到广泛重视。", s: "宋·释惟白《续传灯录》卷二十七师住径山时，名重一时，如侍郎张公子韶，状元汪公圣锡少卿、冯公济川俱问道。”" },
  { w: "明公正道", p: ["míng", "gōng", "zhèng", "dào"], e: "犹言正式；公开；堂堂正正。同明公正气”。", s: "无" },
  { w: "明公正气", p: ["míng", "gōng", "zhèng", "qì"], e: "犹言正式；公开；堂堂正正。", s: "无" },
  { w: "明公正义", p: ["míng", "gōng", "zhèng", "yì"], e: "犹言正式；公开；堂堂正正。同明公正气”。", s: "无" },
  { w: "明见万里", p: ["míng", "jiàn", "wàn", "lǐ"], e: "对于外界或远方的情况，知道得很清楚。也比喻人有预见。", s: "《后汉书·窦融传》书妪至，河西咸惊，以为天子明见万里之外。”" },
  { w: "明明白白", p: ["míng", "míng", "bái", "bái"], e: "清清楚楚，明确无误；正大光明。", s: "明·施耐庵《水浒传》第45回账目已明明白白，并无分文来去。”" },
  { w: "明月清风", p: ["míng", "yuè", "qīng", "fēng"], e: "只与清风、明月为伴。比喻不随便结交朋友。也比喻清闲无事。", s: "《南史·谢惠传》入吾室者，但有清风；对吾饮者，惟当明月。”" },
  { w: "明知故问", p: ["míng", "zhī", "gù", "wèn"], e: "明明知道，还故意问人。", s: "清·无名氏《绣花鞋》明人何必细说。你也知道是谁，却就是明知故问呢！”" },
  { w: "目不知书", p: ["mù", "bù", "zhī", "shū"], e: "指读书很少或没读过书；不甚识字或不识字。同目不识书”。", s: "无" },
  { w: "目无王法", p: ["mù", "wú", "wáng", "fǎ"], e: "不把国家的法律放在眼里。指人不受约束地胡作非为。", s: "清·吴敬梓《儒林外史》第四十三回他如何敢拿了去，要起赎身的价银来，目无王法已极。”" },
  { w: "目下十行", p: ["mù", "xià", "shí", "háng"], e: "形容看书速度极快。", s: "《京本通俗小说·拗相公》一个首相姓王名安石，临川人也。此人目下十行，书穷万卷。”" },
  { w: "目指气使", p: ["mù", "zhǐ", "qì", "shǐ"], e: "目指动一下眼睛来指物；气使用嘘气声支使人。用眼神和气色指使人。形容骄横傲慢的样子。", s: "汉·刘向《说苑·君道》今王将东面目指气使以求臣，则厮役之材至矣；南面听朝不失揖让之礼以求臣，则人臣之材至矣。”" },
  { w: "目中无人", p: ["mù", "zhōng", "wú", "rén"], e: "眼里没有别人。形容骄傲自大，看不起人。", s: "明·冯梦龙《东周列国志》第九十六回赵奢子赵括，自少喜谈兵法，家传《六韬》、《三略》之书，一览而尽；尝与父奢论兵，指天画地…" },
  { w: "难以为情", p: ["nán", "yǐ", "wéi", "qíng"], e: "指情面上过不去。", s: "无" },
  { w: "难于上天", p: ["nán", "yú", "shàng", "tiān"], e: "比上天还难。形容极其困难，不易实现。", s: "汉·枚乘《上书谏吴王》必若所欲为，危于累卵，难于上天。”" },
  { w: "能上能下", p: ["néng", "shàng", "néng", "xià"], e: "指干部不计较职位高低，不论处于领导岗位或在基层从事实际工作，都能踏踏实实地干。实行能上能下，是对干部职务终身制的一项重要改革。", s: "无" },
  { w: "能说会道", p: ["néng", "shuō", "huì", "dào"], e: "形容很会讲话。", s: "清·曹雪芹《红楼梦》第七十四回仗着他的模样儿比别人标致些，又长了一张巧嘴，天天打扮的象个西施样子，在人跟前能说惯道，抓尖…" },
  { w: "能文能武", p: ["néng", "wén", "néng", "wǔ"], e: "文的武的都行。现常指既能动笔也有实际工作能力。", s: "清·钱采《说岳全传》第三十八回能文能武，方是男子汉。”" },
  { w: "年事已高", p: ["nián", "shì", "yǐ", "gāo"], e: "年事年纪。指一个人的岁数已经很大了。", s: "无" },
  { w: "平安无事", p: ["píng", "ān", "wú", "shì"], e: "平平安安，没出什么事故。", s: "元·无名氏《昊天塔孟良盗骨》第二折哥哥将令，着兄弟巡界河去，平安无事，回哥哥的话来。”" },
  { w: "平白无故", p: ["píng", "bái", "wú", "gù"], e: "平白凭空；故缘故。指无缘无故。", s: "梁斌《红旗谱》三十二眼看平白无故被他们拿去。不，这等于是他们砸明火、路劫！”" },
  { w: "平地起家", p: ["píng", "dì", "qǐ", "jiā"], e: "比喻原来没有基础而建立了一番事业。", s: "无" },
  { w: "平心定气", p: ["píng", "xīn", "dìng", "qì"], e: "指心情平和，态度冷静。", s: "宋·陆九渊《与刘深父书》开卷读书时，整冠肃容，平心定气。”" },
  { w: "平心而论", p: ["píng", "xīn", "ér", "lùn"], e: "平心心情平和，不动感情；论评论。平心静气地给予客观评价。", s: "清·纪昀《阅微草堂笔记·滦阳消夏录一》平心而论，王弻始变旧说，为宋学之萌芽。”" },
  { w: "平心易气", p: ["píng", "xīn", "yì", "qì"], e: "心情平和，态度冷静。同平心静气”。", s: "无" },
  { w: "七大八小", p: ["qī", "dà", "bā", "xiǎo"], e: "①大小不一。②零落的样子。③妻妾众多。", s: "清·刘鹗《老残游记》第十回有几张树根的坐具，却是七大八小的不匀。”清·曹雪芹《红楼梦》第一百八回这十二钗说是金陵的，怎么…" },
  { w: "七开八得", p: ["qī", "kāi", "bā", "dé"], e: "形容反反复复，十分周备。", s: "无" },
  { w: "七老八十", p: ["qī", "lǎo", "bā", "shí"], e: "形容年纪很大。", s: "无" },
  { w: "七了八当", p: ["qī", "le", "bā", "dāng"], e: "形容十分妥帖。", s: "无" },
  { w: "七七八八", p: ["qī", "qī", "bā", "bā"], e: "①犹言差不多。②犹言零零碎碎，各式各样。", s: "无" },
  { w: "七上八下", p: ["qī", "shàng", "bā", "xià"], e: "形容心里慌乱不安。", s: "明·施耐庵《水浒全传》第二十六回那胡正卿心头十五个吊桶打水，七上八下。”" },
  { w: "七生七死", p: ["qī", "shēng", "qī", "sǐ"], e: "佛数谓小乘初果者，尚须往返天上人间，受七度生死，才能证得阿罗汉果。同七死七生”。", s: "无" },
  { w: "七十二行", p: ["qī", "shí", "èr", "háng"], e: "泛指各行各业。", s: "陶行知《自动学胸诗》有个学校真奇怪，小孩自动教小孩。七十二行皆先生，先生不在学如在。”" },
  { w: "七事八事", p: ["qī", "shì", "bā", "shì"], e: "形容事情多而杂乱。", s: "无" },
  { w: "七死七生", p: ["qī", "sǐ", "qī", "shēng"], e: "佛数谓小乘初果者，尚须往返天上人间，受七度生死，才能证得阿罗汉果。亦作七生七死”。", s: "无" },
  { w: "七相五公", p: ["qī", "xiāng", "wǔ", "gōng"], e: "所举皆汉代公卿，后泛指众多的文武大臣。", s: "语出《文选·班固〈西都赋〉》冠盖如云，七相五公。”吕向注七相谓车千秋、黄霸、王商、王嘉、韦贤、平当、魏相。五公张汤、萧望…" },
  { w: "七言八语", p: ["qī", "yán", "bā", "yǔ"], e: "形容人多语杂。", s: "清·李汝珍《镜花缘》第八十三回妹子一心想笑话，你们七言八语，那里还敢理会，实实不曾听得。”" },
  { w: "七足八手", p: ["qī", "zú", "bā", "shǒu"], e: "形容慌张乱闯。同七脚八手”。", s: "沙汀《替身》这时候，那个可怜的盐客，已经在七足八手下打扮好了。”" },
  { w: "起居无时", p: ["qǐ", "jū", "wú", "shí"], e: "起居作息，日常生活。形容日常生活没有规律。", s: "唐·韩愈《送李愿归盘谷序》起居无时，惟适之安。”" },
  { w: "起死回生", p: ["qǐ", "sǐ", "huí", "shēng"], e: "把快要死的人救活。形容医术高明。也比喻把已经没有希望的事物挽救过来。", s: "明·张岱《鲁云谷传》医不经师，方不袭古，每以劫剂胑见起死回生。”" },
  { w: "前古未闻", p: ["qián", "gǔ", "wèi", "wén"], e: "指从来没有听说过。", s: "无" },
  { w: "前无古人", p: ["qián", "wú", "gǔ", "rén"], e: "指以前的人从来没有做过的。也指空前的。", s: "唐·陈子昂《登幽州台歌》前不见古人，后不见来者。”" },
  { w: "清风明月", p: ["qīng", "fēng", "míng", "yuè"], e: "只与清风、明月为伴。比喻不随便结交朋友。也比喻清闲无事。", s: "《南史·谢惠传》入吾室者，但有清风；对吾饮者，惟当明月。”" },
  { w: "清天白日", p: ["qīng", "tiān", "bái", "rì"], e: "指大白天。", s: "无" },
  { w: "情不自已", p: ["qíng", "bù", "zì", "yǐ"], e: "犹情不自禁。感情激动得不能控制。强调完全被某种感情所支配。", s: "无" },
  { w: "情非得已", p: ["qíng", "fēi", "dé", "yǐ"], e: "指情况出于不得已。", s: "无" },
  { w: "情见于色", p: ["qíng", "jiàn", "yú", "sè"], e: "真情从脸色中表现出来。", s: "无" },
  { w: "情理难容", p: ["qíng", "lǐ", "nán", "róng"], e: "容容忍，宽恕。指无论在人情与事理两方面都难以容忍。", s: "元·关汉卿《蝴蝶梦》第二折孩儿每万千死罪犯公徒，那厮每情理难容。”" },
  { w: "情深义重", p: ["qíng", "shēn", "yì", "zhòng"], e: "指情感深远、恩义厚重。", s: "晋·温峤《重与陶侃书》且自顷之顾，绸缪往来，情深义重，著于人士之口。”" },
  { w: "情深意重", p: ["qíng", "shēn", "yì", "zhòng"], e: "情意深重。", s: "清·曹雪芹《红楼梦》第五十八回比如男子丧了妻，或有必当续弦者，也必要续弦为是。便只是不把死的丢过不提，便是情深意重了。”" },
  { w: "情同手足", p: ["qíng", "tóng", "shǒu", "zú"], e: "手足比喻兄弟。交情很深，如同兄弟一样。", s: "唐·李华《吊古战场文》谁无兄弟，如足如手。”" },
  { w: "情同一家", p: ["qíng", "tóng", "yī", "jiā"], e: "比喻情谊深厚，如同一家。", s: "无" },
  { w: "情有可原", p: ["qíng", "yǒu", "kě", "yuán"], e: "按情理，有可原谅的地方。", s: "《后汉书·霍胥传》光之所至，情既可原，而守阙连年，终不见理。”" },
  { w: "情至意尽", p: ["qíng", "zhì", "yì", "jìn"], e: "指对人的情谊已经到极点。", s: "唐·孔颖达疏《诗·大雅·板》我老夫教谏汝，其意乃款款然，情至意尽，何为汝等而未知？”" },
  { w: "取而代之", p: ["qǔ", "é", "dài", "zhī"], e: "指夺取别人的地位而由自己代替。现也指以某一事物代替另一事物。", s: "《史记·项羽本纪》秦始皇游会稽，渡浙江，梁与籍俱观，籍曰‘彼可取而代也。’”" },
  { w: "去故就新", p: ["qù", "gù", "jiù", "xīn"], e: "就归于，留下。除去旧的，留下新的。", s: "《史记·律书》三月也，律中姑洗。”张守节正义《白虎通》云‘沽者，故也。洗者，鲜也。’言万物去故就新，莫不鲜明也。”" },
  { w: "去就之分", p: ["qù", "jiù", "zhī", "fēn"], e: "去就；进退或取舍。分分寸。引申为应持的态度。比喻进取、取舍的分寸。亦作去就之际”。", s: "无" },
  { w: "全心全意", p: ["quán", "xīn", "quán", "yì"], e: "投入全部精力，一点没有保留。", s: "无" },
  { w: "全知全能", p: ["quán", "zhī", "quán", "néng"], e: "无所不知，无所不能。", s: "无" },
  { w: "人百其身", p: ["rén", "bǎi", "qí", "shēn"], e: "百其身自身死一百次。别人愿意死一百次来换取死者的复生。表示对死者极沉痛的悼念。", s: "《诗·秦风·黄鸟》如可赎兮，人百其身。”" },
  { w: "人不自安", p: ["rén", "bù", "zì", "ān"], e: "人心惶惶，动摇不定。", s: "《魏书·慕容盛传》于是上下震局，人不自安，虽忠诚亲戚，亦佥怀离贰。”" },
  { w: "人才出众", p: ["rén", "cái", "chū", "zhòng"], e: "人品才能超出众人。", s: "明·冯梦龙《喻世明言》卷十二年二十五岁，丰姿洒落，人才出众，琴棋书画，无所不通。”" },
  { w: "人多势众", p: ["rén", "duō", "shì", "zhòng"], e: "声势力量大。", s: "清·曹雪芹《红楼梦》第十回话说金荣困人多势众，又兼贾瑞勒令赔了不是，给秦钟磕了头，宝玉方才不吵闹了。”" },
  { w: "人非物是", p: ["rén", "fēi", "wù", "shì"], e: "指人事变迁，景物依旧。", s: "清·洪昻《长生殿·寄情》蓬莱院月悴花憔，昭阳殿人非物是。”" },
  { w: "人间天上", p: ["rén", "jiān", "tiān", "shàng"], e: "人世社会和神仙世界。指景物极美好的处所。多比喻境遇完全不同。", s: "唐·崔颢《七夕词》仙裙玉佩空自知，天上人间不相见。”" },
  { w: "人尽其才", p: ["rén", "jìn", "qí", "cái"], e: "每个人都能充分发挥自己的才能。", s: "《淮南子·兵略训》若乃人尽其才，悉用其力。”" },
  { w: "人情世故", p: ["rén", "qíng", "shì", "gù"], e: "为人处世的道理。", s: "宋·文天祥《送僧了敬序》姑与之委曲于人情世故之内。”明·冯梦龙《醒世恒言》第二十一卷可惜你满腹文章，看不出人情世故。”" },
  { w: "人情之常", p: ["rén", "qíng", "zhī", "cháng"], e: "通常情况下人们共有的情理或态度。", s: "宋·司马光《应诏论体要》凡用一人，必或以为贤，或以为不肖，此固人情之常，自古而然，不足怪也。”" },
  { w: "人取我与", p: ["rén", "qǔ", "wǒ", "yǔ"], e: "取拿；与给。指商人囤积物资，待时出售以获厚利。", s: "《史记·货殖列传》当魏文侯时，李克务尽地力，而白圭乐观时变，故人弃我取，人取我与。”" },
  { w: "人生如梦", p: ["rén", "shēng", "rú", "mèng"], e: "人生如同一场梦。形容世事无定，人生短促。", s: "宋·苏轼《念奴娇·赤壁怀古》词人生如梦，一樽还酹江月。”" },
  { w: "人事不知", p: ["rén", "shì", "bù", "zhī"], e: "指昏迷不醒，失去知觉。同人事不省”。", s: "《红楼梦》第一二○回宝钗哭得人事不知。”" },
  { w: "人我是非", p: ["rén", "wǒ", "shì", "fēi"], e: "是非争执，纠纷。人与人之间的各种利害关系和纠纷。", s: "元·马致远《黄粱梦》第四折一梦中十八年，见了酒色财气，人我是非，贪嗔痴爱，风霜雨雪。”" },
  { w: "人心不古", p: ["rén", "xīn", "bù", "gǔ"], e: "古指古代的社会风尚。旧时指人心奸诈、刻薄，没有古人淳厚。", s: "清·李汝珍《镜花缘》第五十五回奈近来人心不古，都尚奢华。”" },
  { w: "人心如面", p: ["rén", "xīn", "rú", "miàn"], e: "心指思想、感情等。指每个人的思想也象每个人的面貌一样，各不相同。", s: "《左传·襄公三十一年》人心之不同，如其面焉，吾岂敢谓子面如吾面乎？”" },
  { w: "人一己百", p: ["rén", "yī", "jǐ", "bǎi"], e: "别人一次就做好或学会的，自己做一百次，学一百次。比喻以百倍的努力赶上别人。", s: "《礼记·中庸》人一能之，己百之；人十能之，己千之。果能此通矣，虽愚必明，虽柔必强。”" },
  { w: "人云亦云", p: ["rén", "yún", "yì", "yún"], e: "云说；亦也。人家怎么说，自己也跟着怎么说。指没有主见，只会随声附和。", s: "金·蔡松年《槽声同彦高赋》诗槽床过竹春泉句，他日人云吾亦云。”" },
  { w: "人之常情", p: ["rén", "zhī", "cháng", "qíng"], e: "一般人通常有的感情。", s: "南朝·粱·江淹《杂体诗三十八首·序》又贵远贱近，人心向背；重耳轻目，俗之恒弊。”" },
  { w: "人中之龙", p: ["rén", "zhōng", "zhī", "lóng"], e: "比喻人中豪杰。", s: "《晋书·宋纤传》吾而今而后知先生人中之龙也。”" },
  { w: "日不我与", p: ["rì", "bù", "wǒ", "yǔ"], e: "时日不等待我。极言应抓紧时间。", s: "三国·魏·曹植《与吴季重书》然日不我与，曜灵急节，面有过景之速，别有参商之阔。”" },
  { w: "日东月西", p: ["rì", "dōng", "yuè", "xī"], e: "比喻远隔两地，不能相聚。", s: "汉·蔡琰《胡茄十八拍》十六拍兮思茫茫，我与儿兮各一方。日东月西兮徒相望，不得相随兮空断肠。”" },
  { w: "日就月将", p: ["rì", "jiù", "yuè", "jiāng"], e: "就成就；将进步。每天有成就，每月有进步。形容精进不止。也日积月累。", s: "《诗经·周颂·敬之》日就月将，学有缉熙于光明。”" },
  { w: "日以为常", p: ["rì", "yǐ", "wéi", "cháng"], e: "经常做某件事，成了惯例常规。", s: "无" },
  { w: "日引月长", p: ["rì", "yǐn", "yuè", "cháng"], e: "指事物随时光流逝而日渐增长。", s: "语出《国语·齐语》昔吾先君襄公筑台以为高位，田、狩、義、弋，不听国政，卑圣侮士，而唯女是崇……是以国家不日引，不月长。”…" },
  { w: "日月不居", p: ["rì", "yuè", "bù", "jū"], e: "形容时光流逝。", s: "无" },
  { w: "日月经天", p: ["rì", "yuè", "jīng", "tiān"], e: "日月每天都经过天空。比喻光明正大，历久不衰。", s: "南朝·宋·范晔《后汉书·冯衍传上》其事昭昭，日月经天，河海带地，不足以比。”" },
  { w: "日月如流", p: ["rì", "yuè", "rú", "liú"], e: "时光像流水一样迅速消逝。", s: "无" },
  { w: "日月无光", p: ["rì", "yuè", "wú", "guāng"], e: "连太阳和月亮都失去了光彩。比喻极其黑暗。", s: "无" },
  { w: "容头过身", p: ["róng", "tóu", "guò", "shēn"], e: "只要头容得下，身子就过得去。比喻得过且过。", s: "《后汉书·西羌传》今三郡未复，园陵单外，而公卿选懦，容头过身。”" },
  { w: "如此而已", p: ["rú", "cǐ", "ér", "yǐ"], e: "如此象这样；而已罢了。就是这样罢了。", s: "《孟子·尽心上》无为其所不为，无欲其所不欲，如此而已矣。”" },
  { w: "如日方中", p: ["rú", "rì", "fāng", "zhōng"], e: "好象太阳正在天顶。比喻事物正发展到十分兴盛的阶段。", s: "《诗经·邶风·简兮》日之方中，在前上处。”" },
  { w: "如日中天", p: ["rú", "rì", "zhōng", "tiān"], e: "好象太阳正在天顶。比喻事物正发展到十分兴盛的阶段。", s: "《诗经·邶风·简兮》日之方中，在前上处。”" },
  { w: "如是我闻", p: ["rú", "shì", "wǒ", "wén"], e: "如是指佛经经文内容如此；我闻阿难自称我闻之于佛。佛教传说，后为佛经开卷语。", s: "《佛地经论》一如是我闻者，谓总显己闻，传佛教者言如是事，我昔曾闻如是。”" },
  { w: "如手如足", p: ["rú", "shǒu", "rú", "zú"], e: "手足比喻兄弟。比喻兄弟的感情。", s: "唐·李华《吊古战场文》谁无兄弟，如足如手。”" },
  { w: "如无其事", p: ["rú", "wú", "qí", "shì"], e: "象没有那回事一样。形容遇事沉着镇定或不把事情放在心上。", s: "清·李宝嘉《官场现形记》第十八回统领听不见，庄大老爷也听不见，就作为如无其事，不去提他了。”" },
  { w: "如有所失", p: ["rú", "yǒu", "suǒ", "shī"], e: "好像丢失了什么似的。形容心神不安的样子。也形容心里感到空虚。", s: "南朝·宋·刘义庆《世说新语·德行》则鄙吝之心已复生矣。”南朝宋·刘孝标注怅然若有所失。”" },
  { w: "若无其事", p: ["ruò", "wú", "qí", "shì"], e: "象没有那回事一样。形容遇事沉着镇定或不把事情放在心上。", s: "冯德英《苦菜花》第三章王柬芝若无其事地闩上门，又叫她点着灯，他那双眼睛四处巡视着。”" },
  { w: "若有若无", p: ["ruò", "yǒu", "ruò", "wú"], e: "形容事物不清晰或关系不亲密。", s: "明·洪应明《菜根谭·闲适》若有若无，半真半幻，最足以悦人心目而豁人性灵。真天地间一妙境也。”" },
  { w: "若有所失", p: ["ruò", "yǒu", "suǒ", "shī"], e: "好象丢了什么似的。形容心神不定的样子。也形容心里感到空虚。", s: "清·蒲松龄《聊斋志异·黄九郎》生邑邑若有所失，忘啜废枕，日渐委悴。”" },
  { w: "若有所思", p: ["ruò", "yǒu", "suǒ", "sī"], e: "若好像∶像在思考着什么。", s: "唐·陈鸿《长恨传》玉妃茫然退立，若有所思。”" },
  { w: "三从四德", p: ["sān", "cóng", "sì", "dé"], e: "封建礼教束缚妇女的道德标准之一。", s: "《仪礼·丧服·子夏传》妇人有三从之义，无专用之道。故未嫁从父，既嫁从夫，夫死从子。”《周礼·天官》九嫔掌妇学之法，以九教…" },
  { w: "三对六面", p: ["sān", "duì", "liù", "miàn"], e: "人指会同当事双方及中间人或见证人。", s: "茅盾《子夜》回头我自会请三先生来，大家三对六面讲个明白。”" },
  { w: "三夫之对", p: ["sān", "fū", "zhī", "duì"], e: "泛指经过多人传播的流言。同三夫之言”。", s: "《晋书·王瀎传》今臣之信行，未若曾参之著；而谗构沸腾，非徒三夫之对，外内扇助，为二五之应。”" },
  { w: "三夫之言", p: ["sān", "fū", "zhī", "yán"], e: "泛指经过多人传播的流言。", s: "《战国策·秦策二》昔者曾子处费，费人有与曾子同名族者而杀人，人告曾子母曰‘曾参杀人。’曾子母曰‘吾子不杀人。’织自若。有…" },
  { w: "三老四少", p: ["sān", "lǎo", "sì", "shǎo"], e: "①老少众人。②方言。称参加青帮的人。犹言老少爷们或兄弟爷们。", s: "无" },
  { w: "三清四白", p: ["sān", "qīng", "sì", "bái"], e: "指非常清白。", s: "无" },
  { w: "三人为众", p: ["sān", "rén", "wèi", "zhòng"], e: "数目达到三人即可称为众人，已不算少数。", s: "《汉书·高惠高后文功臣表序》三人为众，虽难尽继，宜从尤功。”" },
  { w: "三三两两", p: ["sān", "sān", "liǎng", "liǎng"], e: "三个两个地在一起。形容人数不多。", s: "宋·郭茂倩《乐府诗集》卷四十七引晋人《娇女》诗鱼行不独自，三三两两俱。”宋·辛弃疾《念奴娇·双陆》词袖手旁观初未说，两两…" },
  { w: "三三四四", p: ["sān", "sān", "sì", "sì"], e: "犹三三两两。形容人数不多。", s: "汉·王延寿《梦赋》尔乃三三四四，相随踉■（足旁）而历僻。”" },
  { w: "三三五五", p: ["sān", "sān", "wǔ", "wǔ"], e: "三个一群，五个一伙。", s: "唐·李白《采莲曲》岸上谁家游冶郎，三三五五映垂杨。”" },
  { w: "三十六行", p: ["sān", "shí", "liù", "háng"], e: "旧时对各行各业的通称。", s: "清·李渔《玉搔头》三十六行，行行相妒。”" },
  { w: "三十三天", p: ["sān", "shí", "sān", "tiān"], e: "佛教称欲界第六天为三十三天，即忉利天◇形容最高的地方。", s: "《胜鬾宝窟》卷下此言三十三天者，中国言悉怛梨余恶卫陵，此中唯取怛梨二字为忉利天也。怛梨，忉利，彼国音不同耳。”" },
  { w: "三天两头", p: ["sān", "tiān", "liǎng", "tóu"], e: "隔一天，或几乎每天。形容经常、频繁。", s: "周立波《暴风骤雨》第一部十二西北悬天起了乌黑的云朵，不大一会，瓢泼大雨到来了，夹着炸雷和闪电，因为三天两头地下雨，道上黑…" },
  { w: "三头两面", p: ["sān", "tóu", "liǎng", "miàn"], e: "看对方的脸色而改变态度。比善于迎和奉承和玩弄两面手法。", s: "唐·李商隐《杂篡·愚昧》三头两面趋奉人。”" },
  { w: "三头两日", p: ["sān", "tóu", "liǎng", "rì"], e: "三二天。形容时间相隔很近。", s: "清·西周生《醒世姻缘传》第六回一切日用盘费，三头两日俱是通州差人送来。”" },
  { w: "三头六面", p: ["sān", "tóu", "liù", "miàn"], e: "指当着众人或有关各方之面。", s: "无" },
  { w: "三心二意", p: ["sān", "xīn", "èr", "yì"], e: "又想这样又想那样，犹豫不定。常指不安心，不专一。", s: "元·关汉卿《救风尘》第一折争奈是匪妓，都三心二意。”" },
  { w: "三心两意", p: ["sān", "xīn", "liǎng", "yì"], e: "常指不安心，不专一。同三心二意”。", s: "无" },
  { w: "三言两语", p: ["sān", "yán", "liǎng", "yǔ"], e: "几句话。形容话很少。", s: "元·关汉卿《救风尘》第二折我到那里，三言两句，肯写休书，万事俱休。”" },
  { w: "山高水长", p: ["shān", "gāo", "shuǐ", "cháng"], e: "象山一样高耸，如水一般长流。原比喻人的风范或声誉象高山一样永远存在◇比喻恩德深厚。", s: "唐·刘禹锡《望赋》龙门不见兮，云雾苍苍。乔木何许兮，山高水长。”" },
  { w: "山光水色", p: ["shān", "guāng", "shuǐ", "sè"], e: "水波泛出秀色，山上景物明净。形容山水景色秀丽。", s: "唐·白居易《菩提寺上方晚眺》诗楼阁高低树浅深，山光水色暝暝沈沈。”" },
  { w: "山长水远", p: ["shān", "cháng", "shuǐ", "yuǎn"], e: "比喻道路遥远艰险。", s: "唐·许浑《将为南行陪尚书崔公宴海榴堂》诗谩夸书剑无好处，水远山长步步愁。”" },
  { w: "上下其手", p: ["shàng", "xià", "qí", "shǒu"], e: "比喻玩弄手法，串通做弊。", s: "《左传·襄公二十六年》记载伯州犁有意偏袒公子围，叫皇颉作证，并向皇虻示，举起手说夫子为王子围，寡君之贵介弟也。”把手放下…" },
  { w: "上下同门", p: ["shàng", "xià", "tóng", "mén"], e: "上下指上一辈与下一辈。姑婿与侄婿的互称。", s: "唐·赵璾《因话录》卷三杨仆射於陵在考功时，与李师稷及第。至其子相国嗣复知举，门生集候仆射，而李公在坐，时人谓之杨家上下门…" },
  { w: "上下同心", p: ["shàng", "xià", "tóng", "xīn"], e: "上下一心。", s: "姚雪垠《李自成》第一卷第十七章自成虽然新遭大败，但此人百折不挠，锐意进取，加之重要将领均在，上下同心，亲密无向，又善于整…" },
  { w: "上下一心", p: ["shàng", "xià", "yī", "xīn"], e: "上上下下一条心。", s: "《淮南子·诠言训》上下一心，君臣同志。”" },
  { w: "少气无力", p: ["shǎo", "qì", "wú", "lì"], e: "气不壮，没力量。形容精神不振。", s: "无" },
  { w: "身经百战", p: ["shēn", "jīng", "bǎi", "zhàn"], e: "亲身经历过很多次战斗。比喻况历多，经验丰富。", s: "《资志通鉴·后唐纪·庄宗同光三年》且群臣或从陛下岁久，身经百战，所得不过一州。”" },
  { w: "身外之物", p: ["shēn", "wài", "zhī", "wù"], e: "指财物等身体以外的东西，表示无足轻重的意思。", s: "元·蒋子正《山房随笔》引刘改之（过）诗拔毫已付管城子，烂首曾封关内候。死后不知身外物，也随尊酒伴风流。”" },
  { w: "身无分文", p: ["shēn", "wú", "fēn", "wén"], e: "形容非常贫穷。", s: "无" },
  { w: "身无长处", p: ["shēn", "wú", "cháng", "chù"], e: "除一身之外再没有多余的东西。原指生活俭朴。现形容贫穷。", s: "南朝宋·刘义庆《世说新语·德行》（王恭）对曰‘ 丈人不悉恭，恭作人无长物。’”" },
  { w: "身无长物", p: ["shēn", "wú", "cháng", "wù"], e: "除自身外再没有多余的东西。形容贫穷。", s: "南朝·宋·刘义庆《世说新语·德行》对曰‘ 丈人不悉恭，恭作人无长物。’”" },
  { w: "身先士众", p: ["shēn", "xiān", "shì", "zhòng"], e: "作战时将领亲自带头，冲在士兵前面。现在也用来比喻领导带头，走在群众前面。同身先士卒”。", s: "无" },
  { w: "身做身当", p: ["shēn", "zuò", "shēn", "dāng"], e: "指自己做事自己承当。", s: "无" },
  { w: "深得人心", p: ["shēn", "dé", "rén", "xīn"], e: "得到广大人民的热烈拥护。", s: "无" },
  { w: "深明大义", p: ["shēn", "míng", "dà", "yì"], e: "指识大体，顾大局。", s: "清·文康《儿女英雄传》第二十五回只是要娶到家来作个媳妇，世上这般双瞳如豆、一叶迷山的，以至糊涂下人，又有几个深明大义的呢…" },
  { w: "深文大义", p: ["shēn", "wén", "dà", "yì"], e: "指深奥的大道理。", s: "无" },
  { w: "神兵天将", p: ["shén", "bīng", "tiān", "jiāng"], e: "比喻英勇善战、行动迅捷的军队。", s: "无" },
  { w: "神而明之", p: ["shén", "ér", "míng", "zhī"], e: "指表面玄妙的事理。", s: "《周易·系辞上》化而裁之，存乎变；推而行之，存乎通；神而明之，存乎其人。”" },
  { w: "神气十足", p: ["shén", "qì", "shí", "zú"], e: "神气自以为得意傲慢的神情。形容摆出一副自以为高人一等而了不起的样子。", s: "无" },
  { w: "神情自若", p: ["shén", "qíng", "zì", "ruò"], e: "自若自然，不变常态。神情态度仍和原来一样。", s: "马南邨《燕山夜话·编一套特技”丛书吧》举出最普通的例子来说，当你随便走进一家澡堂的时候，你就会发现有些老工人，能够在滚开…" },
  { w: "神色不动", p: ["shén", "sè", "bù", "dòng"], e: "神色神情。神情显得没有受到惊动而十分镇定。", s: "宋·释道原《景德传灯灵》卷十和尚当时被节度使抛向水中，神色不动，如今何得恁么地？”" },
  { w: "神色自若", p: ["shén", "sè", "zì", "ruò"], e: "自若如常，象原来的样子。神情脸色毫无异样。形容态度镇静。", s: "南朝宋·刘义庆《世说新语·任诞》文王曰‘嗣宗毁顿如此，君不能共忧之，何谓？且有疾而饮酒食肉，固丧礼也。’籍饮啖不辍，神色…" },
  { w: "神意自若", p: ["shén", "yì", "zì", "ruò"], e: "神情脸色毫无异样。形容态度镇静。同神色自若”。", s: "无" },
  { w: "生而知之", p: ["shēng", "ér", "zhī", "zhī"], e: "生下来就懂得知识和道理。这是唯心主义者的观点。", s: "《论语·述而》子曰‘我非生而知之者，好古敏以求之者也。’”" },
  { w: "生公说法", p: ["shēng", "gōng", "shuō", "fǎ"], e: "生公晋末高僧竺道生，世称生公。竺道生解说佛法，能使顽石点头。比喻精通者亲自来讲解，必能透彻说理而使人感化。", s: "《莲社高贤传》竺道生入虎丘山，聚石为徒，讲《涅槃经》，群石皆点头。”" },
  { w: "生生不已", p: ["shēng", "shēng", "bù", "yǐ"], e: "生生中国哲学术语，指变化和新生事物的发生；不已没有终止。形容一切生物新陈代谢，永无停止。", s: "《周易·系辞上》生生之谓易。”宋·周敦颐《太极图说》二气交感，化生万物，万物生生而变化无穷焉。”" },
  { w: "生生世世", p: ["shēng", "shēng", "shì", "shì"], e: "指今生、来世以至永世。", s: "《南史·王敬则传》唯愿后身生生世世不复天王作因缘。”" },
  { w: "生生死死", p: ["shēng", "shēng", "sǐ", "sǐ"], e: "犹言一辈子。指从生至死。", s: "清·周亮工《书影》卷二宽复洒泣诉其父母生生死死之苦日‘傥伊父母必欲归，且随其主母起居耳。’”" },
  { w: "声气相通", p: ["shēng", "qì", "xiāng", "tōng"], e: "彼此串通，互通消息。", s: "明·冯梦龙《警世通言》卷一这相知有几样名色恩德相结者，谓之知己；腹心相照者，谓之知心；声气相求者，谓知知音。”" },
  { w: "声闻过情", p: ["shēng", "wén", "guò", "qíng"], e: "名声超过实际。", s: "《孟子·离娄下》声闻过情，君子耻之。”" },
  { w: "失张失志", p: ["sh", "zhng", "sh", "zhì"], e: "形容举动慌乱，心神不定。", s: "《清平山堂话本·简贴和尚》那婆子听得叫，失张失志，出去迎接来叫的官人。”" },
  { w: "诗礼传家", p: ["shī", "lǐ", "chuán", "jiā"], e: "指以儒家经典及其道德规范世代相传。", s: "无" },
  { w: "诗礼人家", p: ["shī", "lǐ", "rén", "jiā"], e: "世代读书以传统封建礼教为行为准则的人家。", s: "无" },
  { w: "诗礼之家", p: ["shī", "lǐ", "zhī", "jiā"], e: "诗指《诗经》；礼指《周祀》、《仪礼》、《礼记》。旧指世代读书讲究礼教的人家。", s: "明·郎英《七修类稿》卷十六因仍苟且，多为惜财之小而忘大义，奈何诗礼之家亦如此是耶！”" },
  { w: "诗以言志", p: ["shī", "yǐ", "yán", "zhì"], e: "用诗歌表达自己的思想和志趣。亦作诗言志”、诗以道志”。", s: "无" },
  { w: "十二万分", p: ["shí", "èr", "wàn", "fēn"], e: "形容程度极深。", s: "无" },
  { w: "十发十中", p: ["shí", "fā", "shí", "zhōng"], e: "射十次皆中的。形容善射。", s: "无" },
  { w: "十光五色", p: ["shí", "guāng", "wǔ", "sè"], e: "形容景象纷繁，色彩绚丽。", s: "无" },
  { w: "十全十美", p: ["shí", "quán", "shí", "měi"], e: "十分完美，毫无欠缺。", s: "无" },
  { w: "十生九死", p: ["shí", "shēng", "jiǔ", "sǐ"], e: "形容历尽艰险。", s: "唐·韩愈《八月十五赠张功曹》诗十生九死到官所，幽居默默如藏逃。”" },
  { w: "十十五五", p: ["shí", "shí", "wǔ", "wǔ"], e: "①指十个一群，五个一组。形容错乱不齐。②指每十里五里。", s: "无" },
  { w: "十死不问", p: ["shí", "sǐ", "bù", "wèn"], e: "指即使犯十次死罪也予宽恕。", s: "无" },
  { w: "十死一生", p: ["shí", "sǐ", "yī", "shēng"], e: "形容生命非常危险。", s: "《汉书·孝宣许皇后传》妇人免乳大故，十死一生。”" },
  { w: "十有八九", p: ["shí", "yǒu", "bā", "jiǔ"], e: "指绝大多数，大致不差，差不离。", s: "唐·杜甫《负薪行》土风坐男使女立，男当门户女出入。十有八九负薪归，卖薪得钱应供给。”" },
  { w: "十之八九", p: ["shí", "zhī", "bā", "jiǔ"], e: "比喻有极大的可能性。", s: "清·刘献廷《广阳杂记》第二卷十之八九皆守之以僧，名不正，言不顺，莫此为甚。”" },
  { w: "时不可失", p: ["shí", "bù", "kě", "shī"], e: "时时机，机会；失错过。抓住时机，不可错过。", s: "《战国策·秦策四》臣闻敌不可易，时不可失。”" },
  { w: "时不我与", p: ["shí", "bù", "wǒ", "yǔ"], e: "我与与我”的倒装；与等待。时间不会等待我们的。嗟叹时机错过，追悔不及。", s: "《论语·阳货》日月逝矣，岁不我与。”" },
  { w: "时易世变", p: ["shí", "yì", "shì", "biàn"], e: "时代变迁，世事也不一样。", s: "晋·鲁褒《钱神论》当今之急，何用清谈？时易世变，古今异俗。”" },
  { w: "实心实意", p: ["shí", "xīn", "shí", "yì"], e: "指真诚实在的心意。", s: "清·曹雪芹《红楼梦》第一○九回五儿听了，句句都是宝玉调戏之意，知这位呆爷却是真心实意的话。”" },
  { w: "食方于前", p: ["shí", "fāng", "yú", "qián"], e: "形容吃的阔气。同食前方丈”。", s: "无" },
  { w: "食为民天", p: ["shí", "wéi", "mín", "tiān"], e: "指粮食是人民赖以生存的最为重要的东西。", s: "无" },
  { w: "食指大动", p: ["shí", "zhǐ", "dà", "dòng"], e: "原指有美味可吃的预兆，后形容看到有好吃的东西而贪婪的样子。", s: "《左传·宣公四年》楚人献鼋于郑灵公，公子宋与子家将见，子公之食指动。”" },
  { w: "使心别气", p: ["shǐ", "xīn", "bié", "qì"], e: "指发脾气。", s: "无" },
  { w: "士死知己", p: ["shì", "sǐ", "zhī", "jǐ"], e: "士有才识的人。为了报答知己，不惜牺牲生命。亦作士为知己者死”。", s: "无" },
  { w: "世道人情", p: ["shì", "dào", "rén", "qíng"], e: "泛指社会的道德风尚和人们的思想情感等。同世道人心”。", s: "无" },
  { w: "世道人心", p: ["shì", "dào", "rén", "xīn"], e: "社会的风气，人们的思想。", s: "无" },
  { w: "世风日下", p: ["shì", "fēng", "rì", "xià"], e: "指社会风气一天不如一天。", s: "欧阳山《苦斗》五二真是人心不同，各如其面！说世风日下，就是～！”" },
  { w: "事不过三", p: ["shì", "bù", "guò", "sān"], e: "指同样的事不宜连作三次。", s: "明·吴承恩《西游记》第二十七回常言道‘事不过三。’我若不去，真是个下流无耻之徒。”" },
  { w: "事出有因", p: ["shì", "chū", "yǒu", "yīn"], e: "事情的发生是有原因的。", s: "叶圣陶《得失》但是一想到事出有因，他就只好假装没有听见。”" },
  { w: "事无大小", p: ["shì", "wú", "dà", "xiǎo"], e: "事情不分大小。形容什么事都管。", s: "《文选·诸葛亮〈出师表〉》愚以为宫中之事，事无大小，悉以咨之。”宋·司马光《资治通鉴》卷第一百八十五委萧瑀以庶政，事无大…" },
  { w: "事无二成", p: ["shì", "wú", "èr", "chéng"], e: "谓公事和私事不能两全。", s: "《左传·成公八年》礼无加货，事无二成。”杜预注公私不两成。”" },
  { w: "势不可当", p: ["shì", "bù", "kě", "dāng"], e: "当抵挡。形容来势十分迅猛，不能抵挡。", s: "《晋书·郗鉴传》群逆纵逸，其势不可当，可以算屈，难以力竞。”明·罗贯中《三国演义》第一百十九回山上数处精兵杀下，势不可当…" },
  { w: "是非得失", p: ["shì", "fēi", "dé", "shī"], e: "正确与错误，得到的与失去的。", s: "无" },
  { w: "是非分明", p: ["shì", "fēi", "fēn", "míng"], e: "正确与错误非常分明。", s: "东汉·班固《汉书·刘向传》故贤圣之君，博观始终，穷极事情，而是非分明。”" },
  { w: "是非之心", p: ["shì", "fēi", "zhī", "xīn"], e: "分辨是非得失的能力。", s: "无" },
  { w: "是古非今", p: ["shì", "gǔ", "fēi", "jīn"], e: "是认为对；非认为不对，不以为然。指不加分析地肯定古代的，否认现代的。", s: "《史记·秦始皇本纪》有敢偶语《诗》《书》者弃市。以古非今者族。吏见知不举者与同罪。”《汉书·元帝纪》俗儒不达时宜，好是古…" },
  { w: "是是非非", p: ["shì", "shì", "fēi", "fēi"], e: "把对的认为是对的，把错的认为是错的。比喻是非、好坏分得非常清楚。", s: "《荀子·修身》是是非非谓之知，非是是非谓之愚。”" },
  { w: "手足之情", p: ["shǒu", "zú", "zhī", "qíng"], e: "手足比喻兄弟。比喻兄弟的感情。", s: "唐·李华《吊古战场文》谁无兄弟，如足如手。”宋·苏辙《为兄轼下狱上书》臣窃哀其志，不胜手足之情。”" },
  { w: "书不尽言", p: ["shū", "bù", "jìn", "yán"], e: "书书信。信中难以充分表达其意◇多作书信结尾习用语。", s: "《易·系辞上》子曰‘书不尽言，言不尽意。’”" },
  { w: "书不尽意", p: ["shū", "bù", "jìn", "yì"], e: "指文辞难充分达意◇多作书信结尾习用语。", s: "《北齐书·文苑传·祖鸿勋》与阳休之书曰‘……已矣哉，书不尽意。’”" },
  { w: "书生之见", p: ["shū", "shēng", "zhī", "jiàn"], e: "指读书人不切实际或不合时宜的见解。", s: "宋·邵博《闻见后录》卷一予谓议者以本朝养兵为大费，欲复寓兵于农之法，书生之见，可言而不可用者哉。”" },
  { w: "水光山色", p: ["shuǐ", "guāng", "shān", "sè"], e: "泛指山水景色。", s: "无" },
  { w: "水色山光", p: ["shuǐ", "sè", "shān", "guāng"], e: "水波泛出秀色，山上景物明净。形容山水景色秀丽。", s: "唐·白居易《菩提寺上方晚眺》诗楼阁高低树浅深，山光水色暝暝沈沈。”" },
  { w: "水天一色", p: ["shuǐ", "tiān", "yī", "sè"], e: "水光与天色相浑。形容水天相接的辽阔景象。", s: "唐·王勃《滕王阁诗序》落霞与孤鹜齐飞，秋水共长天一色。”" },
  { w: "水远山长", p: ["shuǐ", "yuǎn", "shān", "cháng"], e: "①指路程遥远。同水远山遥”。②指山河辽阔。", s: "无" },
  { w: "说东道西", p: ["shuō", "dōng", "dào", "xī"], e: "说东家，讲西家。形容没有中心地随意说。", s: "宋·释惟白《续传灯录》卷二十那堪长老鼓两片皮，摇三寸舌，说东道西，指南言北。”" },
  { w: "说古道今", p: ["shuō", "gǔ", "dào", "jīn"], e: "从今到古无所不谈，无不评论。形容话题广泛。同说古谈今”。", s: "无" },
  { w: "说今道古", p: ["shuō", "jīn", "dào", "gǔ"], e: "从今到古无所不谈，无不评论。", s: "元·张可久《端正好·渔乐》人间开口笑樵渔，会谈今论古。”" },
  { w: "说来话长", p: ["shuō", "lái", "huà", "cháng"], e: "表示事情很复杂，不是几句话就能说清楚（多指不大愉快的事）。", s: "清·曹雪芹《红楼梦》第八十回哥儿若问我的膏药，说来话长，其中细理，一言难尽。”" },
  { w: "说来说去", p: ["shuō", "lái", "shuō", "qù"], e: "①反复阐说。②犹言总而言之。", s: "无" },
  { w: "说三道四", p: ["shuō", "sān", "dào", "sì"], e: "形容不负责任地胡乱议论。", s: "清·崔灏《通俗编·言笑》莫学他人不知朝暮，走启蒙乡村，说三道四。”" },
  { w: "说是道非", p: ["shuō", "shì", "dào", "fēi"], e: "评说是非。也指搬弄口舌。同说是谈非”。", s: "无" },
  { w: "说一不二", p: ["shuō", "yī", "bù", "èr"], e: "说怎么样就怎么样。形容说话算数。", s: "清·张春帆《宦海》第四回这个时候的邵孝廉，就是个小小的制台一般，说一是一，说二是二，庄制军没有一回驳过他的。”" },
  { w: "死得其所", p: ["sǐ", "dé", "qí", "suǒ"], e: "所处所，地方；得其所得到合适的地方。指死得有价值，有意义。", s: "《魏书·张普惠传》人生有死，死得其所，夫复何恨。”" },
  { w: "死而后已", p: ["sǐ", "ér", "hòu", "yǐ"], e: "已停止。死了以后才罢手。形容为完成一种责任而奋斗终身。", s: "《论语·泰伯》士不可以不弘毅，任重而道远。仁以为己任，不亦重乎？死而后已，不亦远乎？”" },
  { w: "四方八面", p: ["sì", "fāng", "bā", "miàn"], e: "到处；各个方面。", s: "宋·释道原《景德传灯录·怀岳禅师》忽遇四方八面来怎么生？”宋·杨万里《过百家渡四绝句》之二莫问早行奇绝处，四方八面野香来…" },
  { w: "四方之志", p: ["sì", "fāng", "zhī", "zhì"], e: "志志向。指远大的志向。亦作志在四方”。", s: "无" },
  { w: "四面八方", p: ["sì", "miàn", "bā", "fāng"], e: "指各个方面或各个地方。", s: "宋·释道原《景德传灯录》卷二十忽遇四面八方怎么生？”" },
  { w: "四时之气", p: ["sì", "shí", "zhī", "qì"], e: "本指一年四季的气象，后以备四时之气”喻指人的气度弘远。", s: "无" },
  { w: "四书五经", p: ["sì", "shū", "wǔ", "jīng"], e: "四书亦称四子书，即《大学》、《中庸》、《论语》、《孟子》；五经《诗》、《书》、《礼》、《易》、《春秋》。指儒家经典。", s: "汉·班固《白虎通·五经》五经何谓？谓《易》、《尚书》、《诗》、《礼》、《春秋》也。”宋·朱熹著有《四书集注》。" },
  { w: "四战之地", p: ["sì", "zhàn", "zhī", "dì"], e: "指四面平坦，无险可守，容易受攻击的地方。", s: "《史记·乐毅列传》赵，四战之地也，其民习兵，伐之不可。”《后汉书·荀彧传》颖川，四战之地也，天下有变，常为兵冲。”" },
  { w: "四战之国", p: ["sì", "zhàn", "zhī", "guó"], e: "指四面平坦，无险可守，容易受攻击的地方。", s: "《商君书·兵守》四战之国贵守战，负海之国贵攻战。”《史记·乐毅列传》赵，四战之国也，其民习兵，伐之不可。”" },
  { w: "四至八道", p: ["sì", "zhì", "bā", "dào"], e: "旧时标志土地界域的用语。表示四面八方所到之处及通往的道路。", s: "无" },
  { w: "所见所闻", p: ["suǒ", "jiàn", "suǒ", "wén"], e: "看到的和听到的。", s: "宋·王安石《慈溪县学记》则士朝夕所见所闻，无非所以治天下国家之道。”" },
  { w: "太平无事", p: ["tài", "píng", "wú", "shì"], e: "指时世安宁和平，也指生活清静无忧。", s: "明·焦竑《玉堂丛语·方正》惟高堂厚禄身享太平无事之日者，见月则乐也。”" },
  { w: "太平无象", p: ["tài", "píng", "wú", "xiàng"], e: "指太平盛世并无一定标志◇讽刺反动统治者粉饰升平。", s: "《资治通鉴·唐文宗太和六年》会上御延英，谓宰相曰‘天下何时当太平，卿等亦有意于此乎？’僧孺对曰‘太平无象。今四夷不至交侵…" },
  { w: "天不作美", p: ["tiān", "bù", "zuò", "měi"], e: "天不成全美事。多指要进行的事情因刮风下雨而受到了影响。", s: "孙犁《芸斋琐谈（四）》天不作美，忽然飘起雪花来。”" },
  { w: "天成地平", p: ["tiān", "chéng", "dì", "píng"], e: "成成功；平治平。原指禹治水成功而使天之生物得以有成◇常比喻一切安排妥帖。", s: "《尚书·大禹谟》帝曰‘俞！地平天成，六府三事，允治。万世永赖，时乃工。’”《左传·文公十八年》舜臣尧，举八恺，使主后土，…" },
  { w: "天从人原", p: ["tiān", "cóng", "rén", "yuán"], e: "指事情的发展恰如所望。", s: "无" },
  { w: "天大地大", p: ["tiān", "dà", "dì", "dà"], e: "形容极大。", s: "无" },
  { w: "天道人事", p: ["tiān", "dào", "rén", "shì"], e: "天道天理。人事人力所能做到的事。天道人事不可违背。意谓大势所趋。", s: "《元史·谦希宪传》因为书与宋四川统制余玠，谕以天道人事，玠得书愧感自守，不敢复轻动。”" },
  { w: "天地不容", p: ["tiān", "dì", "bù", "róng"], e: "天地天地之间，人世间。容宽容。天地所不能容纳。指大逆不道、罪孽深重的人与事。", s: "无" },
  { w: "天高地下", p: ["tiān", "gāo", "dì", "xià"], e: "①比喻尊卑有别。②比喻各种情势。", s: "无" },
  { w: "天高日远", p: ["tiān", "gāo", "rì", "yuǎn"], e: "指偏远地区。比喻离帝王很远。", s: "无" },
  { w: "天公地道", p: ["tiān", "gōng", "dì", "dào"], e: "形容十分公平合理。", s: "清·岭南羽衣女士《东欧女豪杰》第三回如今人人的脑袋里头既都有了一个社会平等，政治自由，是个天公地道的思想。”" },
  { w: "天经地义", p: ["tiān", "jīng", "dì", "yì"], e: "经规范，原则；义正理。天地间历久不变的常道。指绝对正确，不能改变的道理。也指理所当然的事。", s: "《左传·昭公二十五年》夫礼，天之经也，地之义也，民之行也。”" },
  { w: "天理不容", p: ["tiān", "lǐ", "bù", "róng"], e: "天理天道；容容忍、宽容。旧指做事残忍，灭绝人性，为天理所不容。", s: "元·无名氏《朱砂担》第四折才见得冤冤相报，方信道天理难容。”" },
  { w: "天理难容", p: ["tiān", "lǐ", "nán", "róng"], e: "旧指做事残忍，灭绝人性，为天理所不容。", s: "元·无名氏《朱砂担》第四折才见得冤冤相报，方信道天理难容。”" },
  { w: "天理人情", p: ["tiān", "lǐ", "rén", "qíng"], e: "天然的道理和人的常情。", s: "清·文康《儿女英雄传》第三十六回你可晓得一念不违天理人情，天地鬼神会暗中阿护；一念背了天理人情，天地鬼神也就会立刻不容。…" },
  { w: "天平地成", p: ["tiān", "píng", "dì", "chéng"], e: "指万事安排妥当，天下太平。", s: "《左传·僖公二十四年》《夏书》曰‘地平天成’，称也。”" },
  { w: "天清日白", p: ["tiān", "qīng", "rì", "bái"], e: "犹言光天化日，大白天。", s: "明·凌濛初《初刻拍案惊奇》卷十五不然时今日天清日白，在你家里搜出人腿来，人目昭彰，一传出去，不到得轻放过了你。”" },
  { w: "天上人间", p: ["tiān", "shàng", "rén", "jiān"], e: "一个在天上，一个在人间。多比喻境遇完全不同。", s: "南唐·李煜《浪淘沙》词流水落花春去也，天上人间。”" },
  { w: "天外有天", p: ["tiān", "wài", "yǒu", "tiān"], e: "指某一境界之外更有无穷无尽的境界。多用来表示人的眼界受客观条件的限制，认识的领域需要不断扩大。也表示美好的境界阅历不尽。亦作山外有山”、峰外有峰”", s: "《敦煌曲·何满子四首》其四金河一去路千千，欲到天边更有天。”" },
  { w: "天王老子", p: ["tiān", "wáng", "lǎo", "zǐ"], e: "比喻至尊至贵、最有权威的人。", s: "无" },
  { w: "天无二日", p: ["tiān", "wú", "èr", "rì"], e: "日太阳，比喻君王。天上没有两个太阳。旧喻一国不能同时有两个国君。比喻凡事应统于一，不能两大并存。", s: "《礼记·曾子问》天无二日，土无二王，家无二主，尊无二上。”" },
  { w: "天下第一", p: ["tiān", "xià", "dì", "yī"], e: "形容没有人能比得上。", s: "《后汉书·胡广传》试以章奏，安帝以广为天下第一。”" },
  { w: "天下太平", p: ["tiān", "xià", "tài", "píng"], e: "处处平安无事。指大治之世。", s: "《吕氏春秋·大乐》天下太平，万物安宁。”" },
  { w: "天下一家", p: ["tiān", "xià", "yī", "jiā"], e: "视天下人为一家，和睦相处。也指全国统一。", s: "《礼记·礼运》故圣人耐以天下为一家，以中国为一人者，非意之也。”" },
  { w: "天长地老", p: ["tiān", "cháng", "dì", "lǎo"], e: "犹天长地久。", s: "明·高濂《玉簪记·词媾》两情浓同下蓝桥，战兢兢欢娱较少，成就了凤友鸾交，休忘却天长地老！”" },
  { w: "天知地知", p: ["tiān", "zhī", "dì", "zhī"], e: "天知道，地知道。指人人都知道。亦指只有天知道，地知道，没有别人知道。", s: "无" },
  { w: "天作之合", p: ["tiān", "zuò", "zhī", "hé"], e: "合配合∶象是上天给予安排，很完美地配合到一起。祝人婚姻美满的话。", s: "《诗经·大雅·大明》天监在下，有命既集，文王初载，天作之合。”" },
  { w: "通家之好", p: ["tōng", "jiā", "zhī", "hǎo"], e: "指两家交情深厚，象一家人一样。", s: "元·秦简夫《东堂老》第四折有西邻赵国器，是这扬州奴父亲，与老夫三十载通家之好。”" },
  { w: "通力合作", p: ["tōng", "lì", "hé", "zuò"], e: "通力一起出力。不分彼此，一齐出力。", s: "《论语·颜渊》盍彻乎”朱熹注一夫受田百亩，而与同沟共井之人通力合作，计亩均收。”" },
  { w: "通前至后", p: ["tōng", "qián", "zhì", "hòu"], e: "从开头到结尾。全部，整个。同通前彻后”。", s: "《平妖传》第十一回先从左壁上起，将手捻定，通前至后，凡有字处，次等拂过，共一十三张。”" },
  { w: "通时合变", p: ["tōng", "shí", "hé", "biàn"], e: "做理能适应客观情况的变化，懂得变通，不死守常规。同通权达变”。", s: "清·梅曾亮《复上汪尚书书》立者非他，通时合变，不随俗为陈言者是已。”" },
  { w: "同德同心", p: ["tóng", "dé", "tóng", "xīn"], e: "谓思想行动完全一致。同同心同德”。", s: "《旧唐书·马燧传》长城压境，巨舰济川，同德同心，扶危持颠。”明·罗贯中《平山冷燕》第一回然君臣同德同心，于兹可见。”" },
  { w: "同德一心", p: ["tóng", "dé", "yī", "xīn"], e: "指全心全意为共同目标努力。", s: "无" },
  { w: "同利相死", p: ["tóng", "lì", "xiāng", "sǐ"], e: "指有共同利益，就能舍命相助。", s: "无" },
  { w: "同年而语", p: ["tóng", "nián", "ér", "yǔ"], e: "犹言相提并论。把不同的人或不同的事放在一起谈论或看待。", s: "无" },
  { w: "同日而道", p: ["tóng", "rì", "ér", "dào"], e: "把不同的人或不同的事放在一起谈论或看待。同同日而论”。", s: "无" },
  { w: "同日而论", p: ["tóng", "rì", "ér", "lùn"], e: "犹言相提并论。把不同的人或不同的事放在一起谈论或看待。", s: "无" },
  { w: "同日而言", p: ["tóng", "rì", "ér", "yán"], e: "把不同的人或不同的事放在一起谈论或看待。同同日而论”。", s: "《晋书·郗鉴传》及愍怀太子之废，可谓柔而有正。武秋失节之士，何可同日而言！”" },
  { w: "同日而语", p: ["tóng", "rì", "ér", "yǔ"], e: "指相提并论。", s: "《战国策·赵策二》夫破人之与破于人也，臣人之与臣于人也，岂可同日而言之哉？”" },
  { w: "同声同气", p: ["tóng", "shēng", "tóng", "qì"], e: "比喻亲密无间，志趣相合。同同声共气”。", s: "清·黄小配《廿载繁华梦》第四回故小弟要进京里寻个知己，代他干营，好来任这海关监督，这时同声同气，才好做事。”" },
  { w: "同心合德", p: ["tóng", "xīn", "hé", "dé"], e: "指思想统一，信念一致。同同心同德”。", s: "无" },
  { w: "同心合力", p: ["tóng", "xīn", "hé", "lì"], e: "团结一致，共同努力。", s: "《书·泰誓中》予有乱臣十人，同心同德。”" },
  { w: "同心合意", p: ["tóng", "xīn", "hé", "yì"], e: "指心志一致。同同心一意”。", s: "无" },
  { w: "同心同德", p: ["tóng", "xīn", "tóng", "dé"], e: "同德为同一目的而努力。指思想统一，信念一致。", s: "《尚书·泰誓中》予有乱臣十人，同心同德。”" },
  { w: "同心一德", p: ["tóng", "xīn", "yī", "dé"], e: "指思想统一，信念一致。同同心同德”。", s: "无" },
  { w: "同心一力", p: ["tóng", "xīn", "yī", "lì"], e: "团结一致，共同努力。同同心协力”。", s: "无" },
  { w: "同心一意", p: ["tóng", "xīn", "yī", "yì"], e: "指心志一致。", s: "《三国志·吴志·鲁肃传》肃请得奉命吊表二子……及说备使抚表众，同心一意，共治曹操。”" },
  { w: "头面人物", p: ["tóu", "miàn", "rén", "wù"], e: "指在社会上有较大名声或势力而又经常抛头露面的人。", s: "王蒙《悠悠寸草心》小小的理发室也反映着人世的沧桑，何况到这里来整容的颇多头面人物。”" },
  { w: "头上安头", p: ["tóu", "shàng", "ān", "tóu"], e: "比喻多余和重复。", s: "宋·释道原《景德传灯录》卷十九饶你道有什么事，犹是头上着头，雪上加霜。”宋·黄庭坚《拙轩颂》头上安头，屋下盖屋，毕竟巧者…" },
  { w: "头头是道", p: ["tóu", "tóu", "shì", "dào"], e: "本为佛家语，指道无所不在◇多形容说话做事很有条理。", s: "《续传灯录·慧力洞源禅师》方知头头皆是道，法法本圆成。”" },
  { w: "头一无二", p: ["tóu", "yī", "wú", "èr"], e: "唯一，只有一个。", s: "无" },
  { w: "万不得已", p: ["wàn", "bù", "dé", "yǐ"], e: "表示无可奈何，不得不如此。", s: "明·冯梦龙《喻世明言》第十八卷娘子不须挂怀，三载夫妻，恩情不浅，此去也是万不得已，一年半载，便得相逢也。”" },
  { w: "万不失一", p: ["wàn", "bù", "shī", "yī"], e: "形容绝对不会出差错。同万无一失”。", s: "《韩非子·解老》治乡治邦莅天下者，各以此科适观息耗则万不失一。”《史记·淮阴侯列传》韩信曰‘先生相人何如？’对曰‘贵贱在…" },
  { w: "万夫不当", p: ["wàn", "fū", "bù", "dāng"], e: "夫人。当抵挡。上万个人也抵挡不住。形容人非常勇猛。亦作万夫莫当”。", s: "无" },
  { w: "万里无云", p: ["wàn", "lǐ", "wú", "yún"], e: "湛湛蓝天，没有一丝云彩。形容天气晴朗。", s: "元·王实甫《西厢记》第三本第二折碧天万里无云，空劳倦客身心。”" },
  { w: "万世不易", p: ["wàn", "shì", "bù", "yì"], e: "易改变。永远不改变。亦作万代不易”。", s: "无" },
  { w: "万世一时", p: ["wàn", "shì", "yī", "shí"], e: "万世才有这么一个机会。形容机会难得。", s: "《史记·吴王濞列传》慧星出，蝗虫数起，此万世一时，而愁劳圣人之所起也。”" },
  { w: "万死一生", p: ["wàn", "sǐ", "yī", "shēng"], e: "死的可能极大，活的希望极小。比喻冒生命危险。", s: "汉·司马迁《报任少卿书》夫人臣出万死不顾一生之计，赴公家之难，斯已奇矣。”宋·陆游《晚泊》诗身游万死一生地，路入千峰百嶂…" },
  { w: "万无一失", p: ["wàn", "wú", "yī", "shī"], e: "失差错。指非常有把握，绝对不会出差错。", s: "《史记·淮队侯列传》以此参之，万不失一。”汉·枚乘《七发》孔老览观，孟子持筹而算之，万不失一。”" },
  { w: "万众一心", p: ["wàn", "zhòng", "yī", "xīn"], e: "千万人一条心。形容团结一致。", s: "《后汉书·朱擕传》万人一心，犹不可当，况十万乎！”" },
  { w: "王公大人", p: ["wáng", "gōng", "dà", "rén"], e: "国君重臣◇泛指高官贵人。", s: "无" },
  { w: "为国为民", p: ["wéi", "guó", "wéi", "mín"], e: "指不谋私利，为国家和人民效力。", s: "无" },
  { w: "为小失大", p: ["wèi", "xiǎo", "shī", "dà"], e: "为了小利，造成巨大损失。", s: "清·李宝嘉《文明小史》第二十九回你若不肯，他就告诉了大老爷，找你点错处，革掉了你，你能为小失大吗？”" },
  { w: "文风不动", p: ["wén", "fēng", "bù", "dòng"], e: "一点儿也不动。形容没有丝毫损坏或改变。", s: "清·曹雪芹《红楼梦》第二十九回偏生那玉坚硬非常，摔了一下，竟文风不动。”" },
  { w: "文过其实", p: ["wén", "guò", "qí", "shí"], e: "文辞浮夸，不切实际。", s: "《后汉书·冯衍传下》显宗即位，又多短衍以文过其实，遂废于家。”" },
  { w: "文理不通", p: ["wén", "lǐ", "bù", "tōng"], e: "指文章在词句和内容方面都行不通。", s: "《旧五代史·选举志》况此等多不究义，唯攻帖书，文理既不甚通，名第岂可妄与？”" },
  { w: "文人学士", p: ["wén", "rén", "xué", "shì"], e: "泛指文人、文士。", s: "无" },
  { w: "文如其人", p: ["wén", "rú", "qí", "rén"], e: "指文章的风格同作者的性格特点相似。", s: "宋·苏轼《答张文潜书》子由之文实胜仆，而世俗不知，乃以为不如；其为人深不愿人知之，其文如其为人。”" },
  { w: "文武全才", p: ["wén", "wǔ", "quán", "cái"], e: "文才与武功同时具备的人才。", s: "《旧五代史·和凝传》和公文武全才而有志气，后必享重位，尔宜谨事之。”" },
  { w: "文武之道", p: ["wén", "wǔ", "zhī", "dào"], e: "指周文王、周武王治理国家的方法。", s: "先秦·孔子《论语·子张》文武之道未坠于地，在人，贤者识其大者。”" },
  { w: "闻风而动", p: ["wén", "fēng", "ér", "dòng"], e: "风风声，消息。一听到风声，就立刻起来响应。", s: "宋·陈亮《祭赵尉母夫人文》登堂莫及，闻风而起。”" },
  { w: "闻风而起", p: ["wén", "fēng", "ér", "qǐ"], e: "闻听到；风风声，消息。一听到风声，就立刻起来响应。", s: "宋·陈亮《祭赵尉母夫人文》登堂莫及，闻风而起。”" },
  { w: "闻风而至", p: ["wén", "fēng", "ér", "zhì"], e: "一听到消息就来。形容行动迅速。", s: "无" },
  { w: "闻声相思", p: ["wén", "shēng", "xiāng", "sī"], e: "声名声。指思慕、钦仰有声望的人。", s: "《鬼谷子·内揵》君臣上下之事，有远而亲，近而疏，就之不用，去之反求，日进前不御，遥闻声而相思。”" },
  { w: "闻所不闻", p: ["wén", "suǒ", "bù", "wén"], e: "听到从未听到过的。形容事物非常媳。", s: "无" },
  { w: "闻一知二", p: ["wén", "yī", "zhī", "èr"], e: "听到一点就能理解很多。形容善于类推。", s: "《论语·公冶长》赐也何敢望回？回也闻一以知十，赐也闻一以知二。”" },
  { w: "闻一知十", p: ["wén", "yī", "zhī", "shí"], e: "听到一点就能理解很多。形容善于类推。", s: "《论语·公冶长》赐也何敢望回？回也闻一以知十，赐也闻一以知二。”" },
  { w: "问十道百", p: ["wèn", "shí", "dào", "bǎi"], e: "犹言问一答十。形容所知甚多或口齿伶俐。", s: "无" },
  { w: "无大不大", p: ["wú", "dà", "bù", "dà"], e: "指极大。", s: "无" },
  { w: "无大无小", p: ["wú", "dà", "wú", "xiǎo"], e: "①无论大小。指举国上下。②不分年长年幼、辈份大辈份小。", s: "无" },
  { w: "无地可容", p: ["wú", "dì", "kě", "róng"], e: "指无处藏身，形容慌乱、羞愧至极，处境窘迫。", s: "清·曹雪芹《红楼梦》第94回李纨正要劝解，丫头来说，太太来了。袭人等此时无地可容，宝玉等赶忙出来迎接。”" },
  { w: "无地自处", p: ["wú", "dì", "zì", "chǔ"], e: "犹无地自容。形容非常羞愧。", s: "无" },
  { w: "无地自容", p: ["wú", "dì", "zì", "róng"], e: "没有地方可以让自己容身。形容非常羞愧。", s: "《三国志·魏志·管宁传》夙宵战怖，无地自厝。”" },
  { w: "无动为大", p: ["wú", "dòng", "wéi", "dà"], e: "以不变动为至善。无为而治”的一种政治主张。", s: "无" },
  { w: "无动于中", p: ["wú", "dòng", "yú", "zhōng"], e: "心里一点儿也没有触动。指对应该关心、注意的事情毫不关心，置之不理。", s: "清·李宝嘉《官场现形记》第三十三回以至顶到如今，偏偏碰着这位制军是不轻容易见客的，他见也好，不见也好，便也漠然无动于中了…" },
  { w: "无法无天", p: ["wú", "fǎ", "wú", "tiān"], e: "旧指不顾国法和天理，任意干坏事。现多形容违法乱纪，不受管束。", s: "清·曹雪芹《红楼梦》第三十三回你在家不读书也罢了，怎么又做出这无法无天的事来。”" },
  { w: "无方之民", p: ["wú", "fāng", "zhī", "mín"], e: "古指不知礼法的人。", s: "无" },
  { w: "无旧无新", p: ["wú", "jiù", "wú", "xīn"], e: "不分是旧交还是新交。", s: "《尚书大传》卷二上各安其宅，各田其田，毋故毋新。”" },
  { w: "无可比象", p: ["wú", "kě", "bǐ", "xiàng"], e: "没有什么可与譬比。", s: "无" },
  { w: "无可不可", p: ["wú", "kě", "bù", "kě"], e: "①无所不可，都能做到。②犹言不知如何是好。形容情绪激动至极。", s: "无" },
  { w: "无可如何", p: ["wú", "kě", "rú", "hé"], e: "没有什么办法。", s: "无" },
  { w: "无论如何", p: ["wú", "lùn", "rú", "hé"], e: "不管怎样。表示不管条件怎样变化，其结果始终不变。", s: "无" },
  { w: "无情少面", p: ["wú", "qíng", "shǎo", "miàn"], e: "不讲情面。", s: "无" },
  { w: "无情无义", p: ["wú", "qíng", "wú", "yì"], e: "没有一点情义。形容冷酷无情。", s: "清·曹雪芹《红楼梦》第八十二回好！宝玉，我今日才知道你是个无情无义的人了！”" },
  { w: "无人之地", p: ["wú", "rén", "zhī", "dì"], e: "没有人居住的地方。同无人之境”。", s: "无" },
  { w: "无如之何", p: ["wú", "rú", "zhī", "hé"], e: "没有任何办法。", s: "《礼记·大学》小人之使为国家。灾害并至，虽有善者，亦无如之何矣。”" },
  { w: "无声无色", p: ["wú", "shēng", "wú", "sè"], e: "没有声音和色彩。形容平淡不动人。", s: "无" },
  { w: "无事生非", p: ["wú", "shì", "shēng", "fēi"], e: "无缘无故找岔子，存心制造麻烦。", s: "清·李汝珍《镜花缘》第五十八回有不安本分的强盗，有无事生非的强盗。”" },
  { w: "无事生事", p: ["wú", "shì", "shēng", "shì"], e: "犹言无事生非。无缘无故找岔子，存心制造麻烦。", s: "无" },
  { w: "无所不可", p: ["wú", "suǒ", "bù", "kě"], e: "没有什么不可的。", s: "汉·荀悦《前汉记·武帝纪一》蚡事魏其侯无所不可，而爱数顷田？”" },
  { w: "无所不能", p: ["wú", "suǒ", "bù", "néng"], e: "没有什么不能做的。指样样能做。", s: "宋·沈括《梦溪笔谈》卷二十一近岁迎紫姑者极多，大率多能文章歌诗，有极工者，予屡见之，多自称蓬莱谪仙，医卜无所不能，棋与国…" },
  { w: "无所不容", p: ["wú", "suǒ", "bù", "róng"], e: "没有什么不能容纳。极言其宽广。", s: "无" },
  { w: "无所不通", p: ["wú", "suǒ", "bù", "tōng"], e: "通通晓。没有什么不通晓。形容知道的东西很多。", s: "《孝经·感应》孝悌之至，通于神明，光于四海，无所不通。”" },
  { w: "无所不有", p: ["wú", "suǒ", "bù", "yǒu"], e: "什么都有（多指不好的事物）。", s: "唐·李朝威《柳毅传》始见台阁相向，门户千万，奇草珍木，无所不有。”" },
  { w: "无所不在", p: ["wú", "suǒ", "bù", "zài"], e: "到处都存在，到处都有。", s: "无" },
  { w: "无所不知", p: ["wú", "suǒ", "bù", "zhī"], e: "什么事情都知道，没有不懂得的。", s: "《列子·黄帝》圣人无所不知，无所不通，故得引而使之焉。”" },
  { w: "无所不至", p: ["wú", "suǒ", "bù", "zhì"], e: "至到。指没有不到的地方。也指什么坏事都做绝了。", s: "《论语·阳货》既得之，患失之，苟患失之，无所不至矣。”" },
  { w: "无所不作", p: ["wú", "suǒ", "bù", "zuò"], e: "没有不干的事情。指什么坏事都干。同无所不为”。", s: "无" },
  { w: "无所容心", p: ["wú", "suǒ", "róng", "xīn"], e: "不在意，不留意。", s: "无" },
  { w: "无所事事", p: ["wú", "suǒ", "shì", "shì"], e: "事事前一事”为动词，做；后一事”为名词，事情。闲着什么事都不干。", s: "无" },
  { w: "无所用心", p: ["wú", "suǒ", "yòng", "xīn"], e: "没有地方用他的心。指不动脑筋，什么事情都不关心。", s: "《论语·阳货》饱食终日，无所用心，难矣哉。”" },
  { w: "无所用之", p: ["wú", "suǒ", "yòng", "zhī"], e: "没有地方可以用上它。", s: "无" },
  { w: "无天无日", p: ["wú", "tiān", "wú", "rì"], e: "犹言不见天日。比喻社会黑暗，见不到一点光明。", s: "无" },
  { w: "无为而成", p: ["wú", "wéi", "ér", "chéng"], e: "指不倚外力而自然有所成就。", s: "无" },
  { w: "无为自成", p: ["wú", "wéi", "zì", "chéng"], e: "指不倚外力而自然有所成就。同无为而成”。", s: "无" },
  { w: "无相无作", p: ["wú", "xiāng", "wú", "zuò"], e: "①佛教语。指弃绝众相，不事造作。②泛指不务空言。", s: "无" },
  { w: "无言可对", p: ["wú", "yán", "kě", "duì"], e: "对对答，回答。没有话来回答。", s: "宋·释普济《五灯会元》卷四师曰‘这老和尚被我一问直得无言可对。’”" },
  { w: "无一不知", p: ["wú", "yī", "bù", "zhī"], e: "没有什么不知道的。形容知识丰富。", s: "《云笈七签》卷四九引《五符经》知一者，无一之不知也。不知一者，无一能知也。一者，至贵无偶之号也。”" },
  { w: "无与为比", p: ["wú", "yǔ", "wéi", "bǐ"], e: "犹无与伦比，无可比拟。", s: "无" },
  { w: "无中生有", p: ["wú", "zhōng", "shēng", "yǒu"], e: "道家认为，天下万物生于有，有生于无。把没有的说成有。比喻毫无事实，凭空捏造。", s: "《老子》天下万物生于有，有生于无。”" },
  { w: "五光十色", p: ["wǔ", "guāng", "shí", "sè"], e: "形容色彩鲜艳，花样繁多。", s: "南朝梁·江淹《丽色赋》五光徘徊，十色陆离。”" },
  { w: "五花八门", p: ["wǔ", "huā", "bā", "mén"], e: "原指五行阵和八门阵。这是古代两种战术变化很多的阵势。比喻变化多端或花样繁多。", s: "《虞初新志·孙嘉淦》伏龙以西，群峰乱峙，四布罗列，如平沙万幕，八门五花。”" },
  { w: "五色无主", p: ["wǔ", "sè", "wú", "zhǔ"], e: "五色指人脸上的神采；无主无法主宰。形容恐惧而神色不定。", s: "《淮南子·精神训》禹在省方，济于江，黄龙负舟，舟中无人，五色无主。”汉·刘向《新序·杂事》叶公见之，弃而还走，失其魂魄，…" },
  { w: "五心六意", p: ["wǔ", "xīn", "liù", "yì"], e: "形容心思不定。", s: "汉朝焦彦寿《易林》卷十五心六意，岐道多怪。”" },
  { w: "五行八作", p: ["wǔ", "háng", "bā", "zuò"], e: "泛指各行各业。", s: "老舍《龙须沟》第一幕五行八作，就没你这一行。”" },
  { w: "物尽其用", p: ["wù", "jìn", "qí", "yòng"], e: "各种东西凡有可用之处，都要尽量利用。指充分利用资源，一点不浪费。", s: "无" },
  { w: "物是人非", p: ["wù", "shì", "rén", "fēi"], e: "东西还是原来的东西，可是人已不是原来的人了。多用于表达事过境迁。因而怀念故人。", s: "宋·李清照《武陵春》词物是人非事事休，欲语泪先流。”" },
  { w: "下马看花", p: ["xià", "mǎ", "kàn", "huā"], e: "比喻停下来，深入实际，认真调查研究。", s: "无" },
  { w: "先得我心", p: ["xiān", "dé", "wǒ", "xīn"], e: "得适合，契合。比喻别人先说出了自己心里想说的话。", s: "《孟子·告子上》心之所同然者何也？谓理也、义也。圣人先得我心之所同然耳，故理义之悦我心，犹刍豢之悦我口。”" },
  { w: "先见之明", p: ["xiān", "jiàn", "zhī", "míng"], e: "明·指眼力。事先看清问题的能力。指对事物发展的预见性。", s: "《后汉书·杨彪传》愧无日磾先见之明，犹怀老牛舐犊之爱。”" },
  { w: "先来后到", p: ["xiān", "lái", "hòu", "dào"], e: "按照来到的先后确定次序。", s: "明·无名氏《南牢记》第二折也有个先来后到，反教俺无下梢。”" },
  { w: "先礼后兵", p: ["xiān", "lǐ", "hòu", "bīng"], e: "礼礼貌；兵武力。先按通常的礼节同对方交涉，如果行不能，再用武力或其他强硬手段解决。", s: "明·罗贯中《三国演义》第十一回刘备远来救援，先礼后兵，主公当用好言答之，以慢备心，然后进兵攻城，城可破也。”" },
  { w: "先人后己", p: ["xiān", "rén", "hòu", "jǐ"], e: "首先考虑别人，然后想到自己。", s: "《礼记·坊记》子云‘君子贵人而贱己，先人而后己。’”" },
  { w: "先声后实", p: ["xiān", "shēng", "hòu", "shí"], e: "声声势；实实力。比喻先用声势挫折敌方士气，然后交战。", s: "《史记·淮阴侯列传》兵固有先声而后实者，此之谓也。”" },
  { w: "先天不足", p: ["xiān", "tiān", "bù", "zú"], e: "先天人或动物的胚胎时期。原指人或动物生下来体质就不好◇也指事物的根基差。", s: "清·李汝珍《镜花缘》第二十六回小弟闻得仙人与虚合体，日中无影；又老人之子，先天不足，亦或日中无影。寿麻之人无影，不知何故…" },
  { w: "现身说法", p: ["xiàn", "shēn", "shuō", "fǎ"], e: "佛教用语。指佛力广大，能现出种种人相，向人说法。现指以亲身经历和体验为例来说明某种道理。", s: "《愣严经》卷六我与彼前，皆现其身，而为说法，令其成就。”宋·释道原《景德传灯录》卷一亦于十方界中现身说法。”" },
  { w: "相安无事", p: ["xiāng", "ān", "wú", "shì"], e: "相互相；安安稳。指彼此相处没有什么争执或冲突，还过得去。", s: "宋·邓牧《伯牙琴·吏道》古者君民间相安无事者，固不得无吏，而为员不多。”" },
  { w: "相安相受", p: ["xiāng", "ān", "xiāng", "shòu"], e: "指互相帮助，使彼此安居。", s: "无" },
  { w: "相对无言", p: ["xiāng", "duì", "wú", "yán"], e: "指彼此相对说不出话来。", s: "宋·苏轼《江城子·乙卯正月二十日夜记梦》词夜来幽梦忽还乡，小轩窗，正梳妆，相顾无言，唯有泪千行。”" },
  { w: "相生相成", p: ["xiāng", "shēng", "xiāng", "chéng"], e: "互相转化，互相促进。", s: "无" },
  { w: "相形失色", p: ["xiāng", "xíng", "shī", "sè"], e: "失色失去光彩⊥同类的事物相比较，显得大大不如。", s: "秦牧《在仙人掌丛生的地方》仙人掌终于锻炼出现在这样一种使普通植物为之相形失色的倔强性格和卓特风貌。”" },
  { w: "相因相生", p: ["xiāng", "yīn", "xiāng", "shēng"], e: "互相承袭，互相促进。", s: "无" },
  { w: "相与为一", p: ["xiāng", "yǔ", "wéi", "yī"], e: "相与相互。相互结合成为一体。", s: "汉·贾谊《过秦论》诸侯恐惧，同盟而谋弱秦，不爱珍器重宝肥饶之地，以致天下之士，合从缔交，相与为一。”汉·董仲舒《春秋繁露…" },
  { w: "小己得失", p: ["xiǎo", "jǐ", "dé", "shī"], e: "小己个人。指个人的得失。", s: "《史记·司马相如列传》《小雅》讥小己之丢失，其流及上。”" },
  { w: "小家子气", p: ["xiǎo", "jiā", "zi", "qì"], e: "小家子旧指出身低微的人。形容人的言谈举止及做事不大方。", s: "《汉书·霍光传》使乐成小家子得幸将军同，至九卿封侯。”" },
  { w: "小人得志", p: ["xiǎo", "rén", "dé", "zhì"], e: "小人指道德低下或行为不正派的人。指人格卑下的人人取得了权势。", s: "南朝·宋·何承天《为谢晦檄京邑》若使小人得志，君子道消。”" },
  { w: "小小不言", p: ["xiǎo", "xiǎo", "bù", "yán"], e: "指细微的，不值得一提的。", s: "清·李宝嘉《官场现形记》第四十四回我同你老实说彼此顾交情，留下脸，小小不言的事情，我也不追究了。”" },
  { w: "小子后生", p: ["xiǎo", "zǐ", "hòu", "shēng"], e: "泛指少年后辈。", s: "唐·韩愈《送温处士赴河阳军序》小子后生，于何考德而问业焉。”" },
  { w: "心安理得", p: ["xīn", "ān", "lǐ", "dé"], e: "得适合。自以为做的事情合乎道理，心里很坦然。", s: "无" },
  { w: "心比天高", p: ["xīn", "bǐ", "tiān", "gāo"], e: "形容心地高傲或所想超过现实。", s: "清·曹雪芹《红楼梦》第五回霁月难逢，彩云易散。心比天高，身为下贱。”" },
  { w: "心不两用", p: ["xīn", "bù", "liǎng", "yòng"], e: "指一个人的心思一时只能专注于一事。", s: "北齐·刘昼《新论·专学》使左手画方，右手画圆，令一时具成，虽执规矩之心，回剟劂之手，而不能者，由心不两用，则手不并运也。…" },
  { w: "心到神知", p: ["xīn", "dào", "shén", "zhī"], e: "旧时指只诚心敬神，就用不到烦琐的礼仪。比喻对人表示钦佩，不必有什么虚文浮礼。", s: "清·曹雪芹《红楼梦》第十一回大老爷原是好养静的，已修炼成了，也算得是神仙了。太太们这么一说，就叫做‘心到神知’了。”" },
  { w: "心开目明", p: ["xīn", "kāi", "mù", "míng"], e: "犹心明眼亮。形容看问题敏锐，能辨别是非。", s: "无" },
  { w: "心平气定", p: ["xīn", "píng", "qì", "dìng"], e: "心气平定，没有杂念。", s: "无" },
  { w: "心平气和", p: ["xīn", "píng", "qì", "hé"], e: "心情平静，态度温和。指不急躁，不生气。", s: "宋·苏轼《菜羹赋》先生心平而气和，故虽老而体胖。”" },
  { w: "心上心下", p: ["xīn", "shàng", "xīn", "xià"], e: "形容心神不安。", s: "巴金《家》二三觉新连忙到房里去把信写好，叫袁成送去。但是这也还不能使众人安心。众人还是心上心下的，害怕送信的袁成还没有回…" },
  { w: "心神不定", p: ["xīn", "shén", "bù", "dìng"], e: "定安定。心里烦躁，精神不安。", s: "清·曹雪芹《红楼梦》第一百十三回便把丰儿等支开，叫刘老老坐在床前，告诉他心神不宁，如见鬼的样子。”" },
  { w: "心无二用", p: ["xīn", "wú", "èr", "yòng"], e: "指做事要专心，注意力必须集中。", s: "汉·桓谭《新论·专学》使左手画方，右手画圆，令一时俱成，虽执规矩之心，回剟劂之手，而不能成者，由心不两用，则手不并运也。…" },
  { w: "心小志大", p: ["xīn", "xiǎo", "zhì", "dà"], e: "办事小心，抱负远大。", s: "《淮南子·主术训》凡人之论，心欲小而志欲大，智欲圆而行欲方，能欲多而事欲鲜。”" },
  { w: "心知其意", p: ["xīn", "zhī", "qí", "yì"], e: "意意义。心中领会了文章的主旨或技艺的要领。", s: "《史记·五帝本纪》书缺有间矣，心知其意，固难为浅见寡闻道也。”" },
  { w: "新人新事", p: ["xīn", "rén", "xīn", "shì"], e: "具有新的道德品质的人和体现新的高尚社会风尚的事。", s: "无" },
  { w: "新学小生", p: ["xīn", "xué", "xiǎo", "shēng"], e: "指治学时间不长，见闻浅陋、经验不足的后生晚辈。", s: "无" },
  { w: "行家里手", p: ["háng", "jiā", "lǐ", "shǒu"], e: "里手内行人。指精通这种业务的人。", s: "清·吴趼人《二十年目睹之怪现状》批评东西的毛病，说那东西的出处，着实是个行家。”" },
  { w: "形形色色", p: ["xíng", "xíng", "sè", "sè"], e: "形形原指生出这种形体；色色原指生出这种颜色。指各式各样，种类很多。", s: "《列子·天瑞》有形者，有形形者，有色者，有色色者。”" },
  { w: "学非所用", p: ["xué", "fēi", "suǒ", "yòng"], e: "所学的不是将来用得着的东西。比喻学习与实践相脱节。", s: "《后汉书·张衡传》必也学非所用，术有所仰，故临川将济，而舟楫不存焉。”" },
  { w: "学老于年", p: ["xué", "lǎo", "yú", "nián"], e: "指青年人的博学。", s: "《宋史·文苑传七·熊克》克幼而翘秀，既长，好学善属文，郡博士胡宪器之，曰‘子学老于年，他日当以文章显。’”" },
  { w: "言必有物", p: ["yán", "bì", "yǒu", "wù"], e: "指言论或文章内容充实。", s: "清·方苞《进〈四书〉〈文选〉表》故凡所录取，皆以发明义理，清真古雅，言必有物为宗。”" },
  { w: "言不尽意", p: ["yán", "bù", "jìn", "yì"], e: "情意曲折深远，言语难以全部表达。常用于书信末尾，表示说的话没能把意思都表达出来。", s: "《易·系辞上》书不尽言，言不尽意。”" },
  { w: "言多必失", p: ["yán", "duō", "bì", "shī"], e: "话说多了一定有失误。", s: "《鬼谷子·本经符》言多必有数短之处。”" },
  { w: "言过其实", p: ["yán", "guò", "qí", "shí"], e: "实实际。原指言语浮夸，超过实际才能◇也指话说得过分，超过了实际情况。", s: "《三国志·蜀书·马良传》马谡言过其实，不可大用。”" },
  { w: "言来语去", p: ["yán", "lái", "yǔ", "qù"], e: "指谈笑时你一言我一语，彼此应对。", s: "元·曾瑞《留鞋记》第一折他把娇胭腻粉频交易，与我言来语去相调戏。”" },
  { w: "言论风生", p: ["yán", "lùn", "fēng", "shēng"], e: "形容言谈议论时兴致很高，气氛活跃。", s: "清·袁枚《新齐谐·赵李二生》[书生]邀入坐，言论风生。”" },
  { w: "言三语四", p: ["yán", "sān", "yǔ", "sì"], e: "言、语说、讲。形容人多嘴杂，议论纷纷。", s: "元·武汉臣《玉壶春》第三折小生欲待要不去，悬心挂意，怎生撇得？欲待要去呵，又惹的人言三语四，使人惶恐，好两难也呵！”" },
  { w: "言是人非", p: ["yán", "shì", "rén", "fēi"], e: "指言论无可非议，但为人不可取。", s: "明·李贽《史纲评要·宋纪·太祖》徐铉、张洎言是人非。”" },
  { w: "言外之意", p: ["yán", "wài", "zhī", "yì"], e: "指有这个意思，但没有在话里明说出来。", s: "宋·欧阳修《六一诗话》必能状难写之景，如在目前，含不尽之意，见于言外，然后为至矣。”宋·叶梦得《石林诗话》七言难于气象雄…" },
  { w: "言无不尽", p: ["yán", "wú", "bù", "jìn"], e: "把内心的话说尽，毫不保留。", s: "《北齐书·高德政传》德政与帝旧相昵爱，言无不尽。”" },
  { w: "言者不知", p: ["yán", "zhě", "bù", "zhī"], e: "指多言多语的人缺乏智能。", s: "《老子》知者不言，言者不知。”河上公注知者贵行不贵言也。驷不及舌，多言多患。”一本作言者弗知”。" },
  { w: "言之成理", p: ["yán", "zhī", "chéng", "lǐ"], e: "之代词，指所说的话。话说得有一定道理。", s: "《荀子·非十二子》然而其持之有故，其言之成理，足以欺惑愚众。”" },
  { w: "言之无物", p: ["yán", "zhī", "wú", "wù"], e: "指文章或言论空空洞洞，没有实际内容。", s: "毛泽东《反对党八股》空话连篇言之无物的演说，是必须停止的。”" },
  { w: "言之有故", p: ["yán", "zhī", "yǒu", "gù"], e: "所说的话有根据。同言之成理”。", s: "清·魏源《默觚下·治篇六》其言之有故，其持之成理，上傅会乎经义，使人主中其腊毒而不自知，君子所深恶也。”" },
  { w: "言之有礼", p: ["yán", "zhī", "yǒu", "lǐ"], e: "说的话有道理。", s: "无" },
  { w: "言之有理", p: ["yán", "zhī", "yǒu", "lǐ"], e: "说的话有道理。", s: "明·吴承恩《西游记》第四十八回陈老道‘言之有理。’”" },
  { w: "言之有物", p: ["yán", "zhī", "yǒu", "wù"], e: "物内容。文章或讲话有具体内容。", s: "《周易·家人》君子以言有物而行有恒。”" },
  { w: "要而论之", p: ["yào", "ér", "lùn", "zhī"], e: "犹言要而言之。概括地说，简单地说。", s: "《天讨·豕韦之裔〈普告汉人〉》要而论之，满人之人中国也，据其土地山河，窃棋子女玉帛……固古人所谓倒行逆施者矣。”" },
  { w: "要而言之", p: ["yào", "ér", "yán", "zhī"], e: "要简要。概括地说，简单地说。", s: "晋·陆机《五等论》且要而言之，五等之君为己思治，郡县之长为利图物。”" },
  { w: "一本万利", p: ["yī", "běn", "wàn", "lì"], e: "本钱小，利润大。", s: "清·姬文《市声》第二十六回这回破釜沉舟，远行一趟，却指望收它个一本万利哩。”" },
  { w: "一本正经", p: ["yī", "běn", "zhèng", "jīng"], e: "原指一部合乎道德规范的经典◇用以形容态度庄重严肃，郑重其事。有时含讽刺意味。", s: "晋·葛洪《抱朴子·百家》正经为道义之渊海，子书为增深之川流。”" },
  { w: "一表人才", p: ["yī", "biǎo", "rén", "cái"], e: "表指外貌。形容人容貌俊秀端正。", s: "元·关汉卿《望江亭》第一折夫人，放着你这一表人物，怕没有中意的丈夫？”" },
  { w: "一表人物", p: ["yī", "biǎo", "rén", "wù"], e: "形容容貌英俊。表，仪表。", s: "元·郑光祖《倩女离魂》第一折（梅香云）姐姐，那王秀才生的一表人物，聪明浪子，论姐姐这个模样，正和王秀才是一对儿。”元·关…" },
  { w: "一成不变", p: ["yī", "chéng", "bù", "biàn"], e: "成制定，形成。一经形成，不再改变。", s: "《礼记·王制》一成而不可变，故君子尽心焉。”" },
  { w: "一成不易", p: ["yī", "chéng", "bù", "yì"], e: "一经形成，不再改变。同一成不变”。", s: "《明史·历志一》夫天之行度多端，而人之智力有限……惟合古今人之心思，踵事增修，庶几符合。故不能为一成不易之法也。”" },
  { w: "一代风流", p: ["yī", "dài", "fēng", "liú"], e: "指创立风尚、为当时景仰的人物。", s: "宋·陈师道《后山诗注·丞相温公挽词》一代风流尽，三师礼数崇。”" },
  { w: "一得之见", p: ["yī", "dé", "zhī", "jiàn"], e: "见见解。谦虚的说法，指自己对某个问题的见解。", s: "《史记·淮阴侯列传》臣闻智者千虑，必有一失；愚者千虑，必有一得。”" },
  { w: "一德一心", p: ["yī", "dé", "yī", "xīn"], e: "德心意。大家一条心，为一个共同目标而努力。", s: "《尚书·泰誓中》乃一德一心，立定厥功，惟克永世。”" },
  { w: "一定不易", p: ["yī", "dìng", "bù", "yì"], e: "易改变。原指一定下来就不变更，后形容事理正确，不可改变。", s: "《淮南子·主术训》今夫权衡规矩，一定而不易，不为秦楚变节，不为胡越改容。”" },
  { w: "一夫之用", p: ["yī", "fū", "zhī", "yòng"], e: "指仅能当一人之用，而无兼人之能。", s: "《后汉书·冯异传》异一夫之用，不足为强弱。”" },
  { w: "一国三公", p: ["yī", "guó", "sān", "gōng"], e: "公古代诸侯国君的通称。一个国家有三个主持政事的人。比喻事权不统一，使人不知道听谁的话好。", s: "《左传·僖公五年》一国三公，吾谁适从？”" },
  { w: "一己之见", p: ["yī", "jǐ", "zhī", "jiàn"], e: "指一个人的意见。", s: "宋·周煇《清波杂志》卷八近时曾公端伯亦编皇宋百家诗选，去取任一己之见。”" },
  { w: "一家老小", p: ["yī", "jiā", "lǎo", "xiǎo"], e: "指全家人。", s: "明·罗贯中《三国演义》第十回当日接了书信，便与弟曹德及一家老小四十余人，带从者百余人，车百余辆，径望兖州而来。”明·冯梦…" },
  { w: "一家无二", p: ["yī", "jiā", "wú", "èr"], e: "指一家之人没有两样。", s: "元·杨显之《潇湘雨》第一折这个女孩儿，也是有缘，我认了做义女，她自到我家来，倒也亲热，一家无二。”" },
  { w: "一家之学", p: ["yī", "jiā", "zhī", "xué"], e: "自成一家的学派。", s: "汉·司马迁《报任少卿书》亦欲以究天人之际，通古今之变，成一家之言。”汉·班固《典引》司马迁著书成一家之言。”" },
  { w: "一家之言", p: ["yī", "jiā", "zhī", "yán"], e: "指有独特见解自成体系的论著。", s: "汉·司马迁《报任少卿书》亦欲以究天人之际，通古今之变，成一家之言。”汉·班固《典引》司马迁著书成一家之言。”" },
  { w: "一家之作", p: ["yī", "jiā", "zhī", "zuò"], e: "自成一家的著作。", s: "《宋书·范晔传》不得志，乃删众家《后汉书》为一家之作。”" },
  { w: "一见了然", p: ["yī", "jiàn", "le", "rán"], e: "犹一目了然。一眼就看得很清楚。", s: "元·陈栎《勤有堂随录》程泰之《禹贡图》，不惬人意，不能使人一见了然。”" },
  { w: "一见如故", p: ["yī", "jiàn", "rú", "gù"], e: "故老朋友。初次见面就象老朋友一样合得来。", s: "《左传·襄公二十九年》见子产，如旧相识。”宋·张洎《贾氏谭录》李邺侯（泌）为相日，吴人顾况西游长安，邺侯一见如故。”" },
  { w: "一见如旧", p: ["yī", "jiàn", "rú", "jiù"], e: "初次见面就情投意合，如同老朋友一样。", s: "《新唐书·房玄龄传》太宗以敦煌公徇渭北，策杖上谒军门，一见如旧。”" },
  { w: "一来二去", p: ["yī", "lái", "èr", "qù"], e: "指一回又一回，经过一段时间。表示逐渐的意思。", s: "清·曹雪芹《红楼梦》第五十八回一来二去，两个人就装糊涂了，倒象真的一样儿。”" },
  { w: "一马当先", p: ["yī", "mǎ", "dāng", "xiān"], e: "原指作战时策马冲锋在前。形容领先。也比喻工作走在群众前面，积极带头。", s: "明·施耐庵《水浒传》第九十六回即便勒兵列阵，一马当先，驰下山来，犹如天崩地塌之势。”" },
  { w: "一门同气", p: ["yī", "mén", "tóng", "qì"], e: "指同门兄弟。", s: "明·吴承恩《西游记》第六十三回他是我一门同气，我怎么不与他出力辨明冤枉。”" },
  { w: "一门心思", p: ["yī", "mén", "xīn", "sī"], e: "指一心一意。", s: "孙华炳《重赏之下》他自己又到图书馆借来关于数控的书，什么也不顾了，一门心思钻研起来。”" },
  { w: "一面如旧", p: ["yī", "miàn", "rú", "jiù"], e: "初次见面就象老朋友一样。", s: "《晋书·张华传》见华一面如旧，钦华德范，如师资之礼焉。”" },
  { w: "一目十行", p: ["yī", "mù", "shí", "háng"], e: "看书时同时可以看十行。形容看书非常快。", s: "《梁书·简文帝纪》读书十行俱下。”宋·刘克庄《杂记六言五首》诗五更三点待漏，一目十行读书。”" },
  { w: "一目五行", p: ["yī", "mù", "wǔ", "háng"], e: "犹一目十行。形容看书非常快。", s: "《辽史·杨遵勖传》天下之事，丛于枢府，簿书填委。遵勖一目五行俱下，判决如流。”" },
  { w: "一目之士", p: ["yī", "mù", "zhī", "shì"], e: "指见解片面，不能看到事物整体的人。", s: "清·李慈铭《越缦堂读书记·志雅堂杂抄》此书成于元代，道学之风甚盛，而能为是言，此是非之公也。近世一目之士，动以诋斥宋儒为…" },
  { w: "一清二白", p: ["yī", "qīng", "èr", "bái"], e: "比喻十分清白。亦比喻非常清楚。", s: "茅盾《劫后拾遗》四你还不相信我吗？我在这里混了这半年，素来一清二白。”周立波《暴风骤雨》第一部七我姓韩的桥是桥，路是路，…" },
  { w: "一清如水", p: ["yī", "qīng", "rú", "shuǐ"], e: "清·清澈。像流水一样清澈。形容为官廉洁，不贪污、不受贿。也形容十分清洁。", s: "明·周楫《西湖二集·祖统制显灵救驾》你在衙门中一清如水，朝廷知你是个个廉吏，异日定来聘你为官。”" },
  { w: "一日三月", p: ["yī", "rì", "sān", "yuè"], e: "形容对人思念殷切。", s: "《诗·王风·采葛》彼采葛兮，一日不见，如三月兮。”" },
  { w: "一日万里", p: ["yī", "rì", "wàn", "lǐ"], e: "比喻行动非常迅速。", s: "唐·苏鄂《杜阳杂编》卷中且安天下用将帅，如造大舟以越沧海，其功则多，其成则大，一日万里，无所不屈。”" },
  { w: "一日之长", p: ["yī", "rì", "zhī", "zhǎng"], e: "年龄大或资格老的自谦说法。", s: "《论语·先进》子路、曾晳、冉有、公西华侍坐，子曰‘以吾一日长乎尔，毋吾以也。’”" },
  { w: "一身两头", p: ["yī", "shēn", "liǎng", "tóu"], e: "一个人同时有两个主张。比喻无所适从。", s: "汉·焦延寿《易林》卷八一身两头，近适二家，乱不可治。”" },
  { w: "一身五心", p: ["yī", "shēn", "wǔ", "xīn"], e: "比喻杂念很多。", s: "汉·焦延寿《易林》卷一三人异趋，反复迷惑。一身五心，乱无所得。”" },
  { w: "一生九死", p: ["yī", "shēng", "jiǔ", "sǐ"], e: "指经历多次生命危险而幸存。", s: "明·刘道开《畴昔》诗畴昔干戈里，飘零剩此身；一生九死客，两代六朝人。”" },
  { w: "一生一代", p: ["yī", "shēng", "yī", "dài"], e: "指一辈子。同一生一世”。", s: "唐·骆宾王《代女道士王灵妃赠道士李荣》诗相怜相念倍相亲，一生一代一双人。”" },
  { w: "一生一世", p: ["yī", "shēng", "yī", "shì"], e: "一辈子。", s: "清·曹雪芹《红楼梦》第九十三回他倒拿定一个主意说是人生婚配，关系一生一世的事，不是混闹得的。”" },
  { w: "一世龙门", p: ["yī", "shì", "lóng", "mén"], e: "一世一代；龙门后汉时李膺有重名，后起的文人有登门拜访的，称之登龙门。称文人所崇仰的人物。", s: "《世说新语·德行》李元礼风格秀整，高自标持，欲以天下名教是非为己任，后进之士，有升其堂者，皆以为登龙门。”《晋书·王衍传…" },
  { w: "一事不知", p: ["yī", "shì", "bù", "zhī"], e: "比喻知识尚有欠缺。同一物不知”。", s: "《南史·隐逸传·陶弘景》读书万余卷，一事不知，以为深耻。”" },
  { w: "一事无成", p: ["yī", "shì", "wú", "chéng"], e: "连一样事情也没有做成。指什么事情都做不成。形容毫无成就。", s: "唐·白居易《除夜寄微之》诗鬓毛不觉白毵毵，一事无成百不堪。”" },
  { w: "一手一足", p: ["yī", "shǒu", "yī", "zú"], e: "一个人的手足。指单薄的力量。", s: "《礼记·表记》后稷天下之为烈也，岂一手一足哉？”" },
  { w: "一死一生", p: ["yī", "sǐ", "yī", "shēng"], e: "指有关生死的关键时刻。", s: "《史记·汲郑列传》太史公曰始翟公为廷尉，宾客阗门；及废，门外可设雀罗。翟公复为廷尉，宾客欲往，翟公乃大署其门曰‘一死一生…" },
  { w: "一天一地", p: ["yī", "tiān", "yī", "dì"], e: "满天满地。形容到处都是。", s: "清·西周生《醒世姻缘传》第三十四回又兼狄家的觅汉伙伴不曾分得银钱的，心里气他不过，到处去彰扬，不止他本村扬说的一天一地，…" },
  { w: "一通百通", p: ["yī", "tōng", "bǎi", "tōng"], e: "通通晓。一个主要的弄通了，其他的自然也都会弄通。", s: "明·吴承恩《西游记》这猴王也是他一窍通时百窍通，当时习了口诀，自习自练，将七十二般变化，都学成了。”" },
  { w: "一文不名", p: ["yī", "wén", "bù", "míng"], e: "名占有。一个钱都没有。形容非常贫困。", s: "西汉·司马迁《史记·佞幸列传》竟不得名一钱，寄死人家。”" },
  { w: "一无可取", p: ["yī", "wú", "kě", "qǔ"], e: "没有一点儿可以肯定的地方。", s: "明·冯梦龙《醒世恒言·卢太学诗酒傲王侯》心中大怒道‘原来这俗物，一无可取，都只管来缠帐，几乎错认了。”" },
  { w: "一无是处", p: ["yī", "wú", "shì", "chù"], e: "是对，正确。没有一点儿对的或好的地方。", s: "明·张岱《与胡季望》是犹三家村子，使之治山珍海错，烹饪燔炙，一无是处。明眼观之，只发一粲。”" },
  { w: "一无所成", p: ["yī", "wú", "suǒ", "chéng"], e: "一点没有成就。", s: "清·黄遵楷《跋》读先兄病笃之书，谓平生怀抱，一无所成，惟近古体诗能自立耳。”" },
  { w: "一无所得", p: ["yī", "wú", "suǒ", "dé"], e: "什么也没有得到。形容毫无收获。", s: "五代·王定保《唐摭言》卷八然日势既暮，寿儿且寄院中止宿，颢亦怀疑，因命寿儿怀袖，一无所得，颢不得已遂躬自操觚。”" },
  { w: "一无所能", p: ["yī", "wú", "suǒ", "néng"], e: "什么能耐也没有。", s: "清·钱泳《履园丛话·杂记上·定数》又苏州叶某者，性迂拙，一无所能，其父死，既无产业，且有逋负。”" },
  { w: "一无所取", p: ["yī", "wú", "suǒ", "qǔ"], e: "原指一点都没拿◇也形容什么都未得到。", s: "《三国志·魏志·钟会传》裴松之注会前后赐钱帛数百万计，悉送供公家之用，一无所取。”" },
  { w: "一无所闻", p: ["yī", "wú", "suǒ", "wén"], e: "一点也没有听说，丝毫也不知道。", s: "无" },
  { w: "一无所有", p: ["yī", "wú", "suǒ", "yǒu"], e: "什么也没有。指钱财，也指成绩、知识。", s: "《敦煌变文集·庐山远公话》如水中之月，空里之风，万法皆无，一无所有。”" },
  { w: "一无所长", p: ["yī", "wú", "suǒ", "cháng"], e: "没有一点儿专长。", s: "清·吴趼人《二十年目睹之怪现状》第九十回那日记当中，提到他那位叶妹夫，便说他年轻而纨裤习气太重，除应酬外，乃一无所长，又…" },
  { w: "一无所知", p: ["yī", "wú", "suǒ", "zhī"], e: "什么也不知道。", s: "明·冯梦龙《警世通言》卷十五小学生望后便倒，扶起，良久方醒。问之一无所知。”" },
  { w: "一无长物", p: ["yī", "wú", "cháng", "wù"], e: "一无全无；长物多余的东西。除一身之外再没有多余的东西。原指生活俭朴。现形容贫穷。", s: "《晋书·王恭传》吾平生无长物。”" },
  { w: "一五一十", p: ["yī", "wú", "yī", "shí"], e: "五、十计数单位。五个十个地将数目点清。比喻叙述从头到尾，源源本本，没有遗漏。也形容查点数目。", s: "明·施耐庵《水浒全传》第二十五回这妇人听了这话，也不回言，却踅过来，一五一十，都对王婆和西门庆说了。”" },
  { w: "一物不知", p: ["yī", "wù", "bù", "zhī"], e: "对某一事物有所不知。比喻知识尚有欠缺。", s: "汉·扬雄《法言·君子》圣人之于天下，耻一物之不知。”" },
  { w: "一相情原", p: ["yī", "xiāng", "qíng", "yuán"], e: "指单方面的愿望或不考虑客观实际情况的主观意愿。亦作一厢情原”。", s: "无" },
  { w: "一心无二", p: ["yī", "xīn", "wú", "èr"], e: "指一心一意地做某种事情，没有杂念。", s: "《旧唐书·张巡传》诸公为国家戮力守城，一心无二，经年乏食，忠义不衰。”" },
  { w: "一心一德", p: ["yī", "xīn", "yī", "dé"], e: "大家一条心，为一个共同目标而努力。", s: "《书·泰誓中》乃一德一心，立定厥功，惟克永世。”" },
  { w: "一心一力", p: ["yī", "xīn", "yī", "lì"], e: "犹同心协力。团结一致，共同努力。", s: "清·魏源《圣武记》卷九自阖营将弁，以及士卒，无不一心一力。”" },
  { w: "一心一意", p: ["yī", "xīn", "yī", "yì"], e: "只有一个心眼儿，没有别的考虑。", s: "《三国志·魏志·杜恕传》免为庶人，徙章武郡，是岁嘉平元年。”裴松之注引《杜氏新书》故推一心，任一意，直而行之耳。”" },
  { w: "一言不发", p: ["yī", "yán", "bù", "fā"], e: "一句话也不说。", s: "明·冯梦龙《喻世明言》卷一三巧儿听说丈夫把她休了，一言不发，啼哭起来。”" },
  { w: "一言两语", p: ["yī", "yán", "liǎng", "yǔ"], e: "为数不多的几句话。", s: "《玉娇梨》第二回倒只愁儿子无真实之才，恐怕一言两语露出马脚。”" },
  { w: "一言难尽", p: ["yī", "yán", "nán", "jìn"], e: "形容事情曲折复杂，不是一句话能说清楚的（用在不好的事）。", s: "元·李直夫《虎头牌》第一折我一言难尽，来探望你这歹孩儿索是远路风尘。”" },
  { w: "一以当百", p: ["yī", "yǐ", "dāng", "bǎi"], e: "一人抵过百人。极言勇猛。", s: "清·李渔《比目鱼》第十四回楚玉也自领全军杀将前去。及至两不相对，真个人强马壮，一以当百。杀得那些山贼，抱头而窜。”" },
  { w: "一以当十", p: ["yī", "yǐ", "dāng", "shí"], e: "当相当。一个人抵挡十个人。形容军队英勇善战。", s: "《战国策·齐策一》一而当十，十而当百，百而当千。”《史记·项羽本纪》楚战士无不一以当十，楚兵呼声动天，诸侯军无不人人惴恐…" },
  { w: "一语中人", p: ["yī", "yǔ", "zhōng", "rén"], e: "中中伤。以一句话中伤人。", s: "无" },
  { w: "一元大武", p: ["yī", "yuán", "dà", "wǔ"], e: "指古时祭祀用的牛。", s: "《礼记·曲礼下》凡祭宗庙之礼，牛曰一元大武。”" },
  { w: "一至于此", p: ["yī", "zhì", "yú", "cǐ"], e: "竟到如此地步。", s: "南朝·梁·简文帝《与湘东王书》笔札无情，任其摇礸。甚矣哉！文之横流，一至于此！”" },
  { w: "以古方今", p: ["yǐ", "gǔ", "fāng", "jīn"], e: "用古代人的人事与今天的人事相比。", s: "《北史·长孙嵩传》昔叔孙辞沃壤之地，萧何就穷僻之乡，以古方今，无惭曩哲。”" },
  { w: "以古非今", p: ["yǐ", "gǔ", "fēi", "jīn"], e: "非非难，否定。用历史故事抨击当前的政治。", s: "《史记·秦始皇本纪》有敢偶语《诗》《书》者弃市，以古非今者族。吏见知不举者与同罪。”" },
  { w: "以古喻今", p: ["yǐ", "gǔ", "yù", "jīn"], e: "喻说明。借用古代的事来说明今天的事情或道理。", s: "《北史·长孙嵩传》昔叔孙辞沃壤之地，萧何就穷僻之乡，以古方今，无渐曩哲。”" },
  { w: "以日为年", p: ["yǐ", "rì", "wéi", "nián"], e: "过一日如同过一年的时间那样漫长难熬。形容心情焦急。亦作以日为岁”。", s: "无" },
  { w: "以容取人", p: ["yǐ", "róng", "qǔ", "rén"], e: "只凭容貌来衡量人的品质和才能。", s: "《韩非子·显学》孔子曰‘以容取人乎，失之子羽；以言取人乎，失之宰予。”《孔子家语·子路初见》以容取人，则失之子羽； 以辞…" },
  { w: "以身作则", p: ["yǐ", "shēn", "zuò", "zé"], e: "则准则，榜样。以自己的行动做出榜样。", s: "巴金《家》二十五这其间不顾一切阻碍以身作则做一个开路先锋的便是许倩如。”" },
  { w: "以小见大", p: ["yǐ", "xiǎo", "jiàn", "dà"], e: "从小的可以看出大的，指通过小事可以看出大节，或通过一小部分看出整体。", s: "无" },
  { w: "以心传心", p: ["yǐ", "xīn", "chuán", "xīn"], e: "佛教禅宗用语。指离开语文文字而以慧心相传授。", s: "《六祖大师法宝坛经·行由品》法则以心传心，皆令自悟自解。”" },
  { w: "以心问心", p: ["yǐ", "xīn", "wèn", "xīn"], e: "在心中自问自盘算。", s: "明·凌濛初《初刻拍案惊奇》卷十七［知观］以心问心，忽然道‘有计了。’”" },
  { w: "以言取人", p: ["yǐ", "yán", "qǔ", "rén"], e: "根据人的口才去判断其智能。", s: "《史记·仲尼弟子列传》孔子闻之，曰‘吾以言取人，失之宰予；以貌取人，失之子羽。’”" },
  { w: "以一当十", p: ["yǐ", "yī", "dāng", "shí"], e: "当相当。一个人抵挡十个人。形容军队英勇善战。", s: "《战国策·齐策一》一而当十，十而当百，百而当千。”《史记·项羽本纪》楚战士无不一以当十，楚兵呼声动天，诸侯军无不人人惴恐…" },
  { w: "以一知万", p: ["yǐ", "yī", "zhī", "wàn"], e: "从了解一点到推知其他许多事物。", s: "《荀子·非相》以近知远，以一知万，以微知明，此之谓也。”" },
  { w: "以战去战", p: ["yǐ", "zhàn", "qù", "zhàn"], e: "用战争消灭战争。", s: "《商君书·画策》故以战去战，虽战可也。”" },
  { w: "义不取容", p: ["yì", "bù", "qǔ", "róng"], e: "取容讨好。为追求正义而不取悦于人。指人刚直不阿。", s: "无" },
  { w: "义形于色", p: ["yì", "xíng", "yú", "sè"], e: "形表现；色面容。仗义不平之气在脸上流露出来。", s: "《公羊传·桓公二年》孔父可谓义形于色矣。”" },
  { w: "易子而食", p: ["yì", "zǐ", "ér", "shí"], e: "子指儿女。原指春秋时宋国被围，城内粮尽，百姓交换子女以当食物◇形容灾民极其悲惨的生活。", s: "《公羊传·宣公十五年》易子而食之，析骸而炊之。”" },
  { w: "意气风发", p: ["yì", "qì", "fēng", "fā"], e: "意气意志和气概；风发象风吹一样迅猛。形容精神振奋，气概豪迈。", s: "无" },
  { w: "意气相得", p: ["yì", "qì", "xiāng", "dé"], e: "形容志趣极其相合。", s: "唐·李百药《北齐书·高乾传》魏领军元叉，权重当世，以意气相得，接乾甚厚。”" },
  { w: "意气用事", p: ["yì", "qì", "yòng", "shì"], e: "意气主观偏激的情绪；用事行事。缺乏理智，只凭一时的想法和情绪办事。", s: "清·吴敬梓《儒林外史》第四十六回这是事势相逼，不得不尔。至今想来，究竟还是意气用事，并不曾报效得朝廷，倒惹得同官心中不快…" },
  { w: "意气自如", p: ["yì", "qì", "zì", "rú"], e: "比喻遇事神态自然，十分镇静。同意气自若”。", s: "《史记·李将军列传》会日暮，吏士皆无人色，而广意气自如，益治军。”" },
  { w: "意气自若", p: ["yì", "qì", "zì", "ruò"], e: "自若不改常态，还像原来的样子。神情自然如常。比喻遇事神态自然，十分镇静。亦作意气自如”。", s: "《汉书·李广传》广为匈奴所败，吏士皆无人色，广意气自若。”" },
  { w: "意义深长", p: ["yì", "yì", "shēn", "cháng"], e: "意思含畜深远，耐人寻味。同意味深长”。", s: "无" },
  { w: "意在言外", p: ["yì", "zài", "yán", "wài"], e: "语言的真正用意没有明白说出来，细细体会就知道。", s: "宋·胡仔《苕溪渔隐丛话后集》卷十五此绝句极佳，意在言外，而幽怨之情自见，不待明言之也。”" },
  { w: "因人成事", p: ["yīn", "rén", "chéng", "shì"], e: "因依靠。依靠别人的力量办成事情。", s: "《史记·平原君虞卿列传》公等碌碌，所谓因人成事者也。”" },
  { w: "因小失大", p: ["yīn", "xiǎo", "shī", "dà"], e: "为了小的利益，造成大的损失。", s: "清·黄小配《廿载繁华梦》他却只是不理，只道他身在洋界，可以没事。不知查抄起来，反恐因小失大，他却如何懂得？”" },
  { w: "引而不发", p: ["yǐn", "ér", "bù", "fā"], e: "引拉弓；发射箭。拉开弓却不把箭射出去。比喻善于启发引导。也比喻做好准备暂不行动，以待时机。", s: "《孟子·尽心上》君子引而不发，跃如也。中道而立，能者从之。”" },
  { w: "引古喻今", p: ["yǐn", "gǔ", "yù", "jīn"], e: "征引古代史实或文献来喻说当前的现实。", s: "无" },
  { w: "引喻失义", p: ["yǐn", "yù", "shī", "yì"], e: "引喻引用类似的例证来说明事理。义公正合宜的道理。指说话不恰当，不合道理。", s: "三国蜀·诸葛亮《前出师表》不宜妄自菲薄，引喻失义，以塞忠谏之路也。”" },
  { w: "用兵如神", p: ["yòng", "bīng", "rú", "shén"], e: "调兵遣将如同神人。形容善于指挥作战。", s: "明·施耐庵《水浒全传》第五十九回为头一个先生，姓樊，名瑞，绰号混世魔王，能呼风唤雨，用兵如神。”" },
  { w: "用非其人", p: ["yòng", "fēi", "qí", "rén"], e: "任用了不适当的人才。指用人不当。", s: "无" },
  { w: "用非所学", p: ["yòng", "fēi", "suǒ", "xué"], e: "所用的不是所学的。指学用不一致。", s: "《明史·叶伯巨传》比到京师，而除官多以貌选，所学或非其所用，所用或非其所学。”" },
  { w: "用其所长", p: ["yòng", "qí", "suǒ", "cháng"], e: "使用人的专长。", s: "无" },
  { w: "用天因地", p: ["yòng", "tiān", "yīn", "dì"], e: "利用天时，顺应地利。", s: "《东观汉记·公孙术传》蜀地沃野千里，土壤膏腴……所谓用天因地，成功之资也。”" },
  { w: "用武之地", p: ["yòng", "wǔ", "zhī", "dì"], e: "形容地形险要，利于作战的地方。比喻可以施展自己才能的地方或机会。", s: "《晋书·姚襄载记》洛阳虽小，山河四塞，亦是用武之地。”" },
  { w: "用心用意", p: ["yòng", "xīn", "yòng", "yì"], e: "犹言专心致志。形容一心一意，聚精会神。", s: "姚雪垠《长夜》九其实他并不想晓得正文中讲些什么，他只在聚精会神地，用心用意地，向密密的方块字群中寻找他所要寻找的一个字。…" },
  { w: "用一当十", p: ["yòng", "yī", "dāng", "shí"], e: "比喻以寡敌众。", s: "宋·陈善《扪虱新活·张巡杀爱妾刘昌斩孤甥》君以孤城，用一当十，何以能守？”" },
  { w: "有本有原", p: ["yǒu", "běn", "yǒu", "yuán"], e: "指有根源；源源本本。亦作有本有源”。", s: "唐·韩愈《原毁》虽然，为是者有本有原，怠与忌之谓也。”" },
  { w: "有朝一日", p: ["yǒu", "zhāo", "yī", "rì"], e: "将来有那么一天。", s: "元·无名氏《博望烧屯》第一折有朝一日，我出矛庐指点世人迷，凭着我剑挥星斗，我志逐风雷。”" },
  { w: "有何面目", p: ["yǒu", "hé", "miàn", "mù"], e: "指没有脸见人。", s: "《后汉书·赵苞传》食禄而避难，非忠也，杀母而全义，非孝也，如是，有何面目立于天下。”" },
  { w: "有己无人", p: ["yǒu", "jǐ", "wú", "rén"], e: "自私自利，只顾自己，不顾别人。", s: "无" },
  { w: "有来无回", p: ["yǒu", "lái", "wú", "huí"], e: "只要来了，就回不去。指彻底被消灭。", s: "周立波《暴风骤雨》第一部十三有这玩艺儿，慢说他‘种殃军’，他洋爸爸鬼子来，也给他有来无回。”" },
  { w: "有名无实", p: ["yǒu", "míng", "wú", "shí"], e: "光有空名，实际上并不是那样。", s: "《庄子·则阳》有名有实，是物之居；无名无实，在物之虚。”《国语·晋语八》吾有卿之名而无其实。无以从二三子，吾是以忧，子贺…" },
  { w: "有年无月", p: ["yǒu", "nián", "wú", "yuè"], e: "指日子拖得长久，没有确定的期限。", s: "蔡东藩《后汉演义》第二回百姓又怕当兵，最怕输粮……舟子车夫，又没有多少工资，统皆畏缩不前，眼见得有年无月，不能成事。”" },
  { w: "有气没力", p: ["yǒu", "qì", "méi", "lì"], e: "形容说话声音微弱，作事精神不振。也形容体弱无力。同有气无力”。", s: "明·冯梦龙《醒世恒言》第三十七卷子春一心想着要那老者的银子，又怕他说谎，这两只脚虽则有气没力的，一步步荡到波斯馆来；一双…" },
  { w: "有气无力", p: ["yǒu", "qì", "wú", "lì"], e: "形容说话声音微弱，作事精神不振。也形容体弱无力。", s: "明·冯梦龙《醒世恒言·吴衙内邻舟赴约》正不知舱中另有个替吃饭的，还饿得有气无力哩。”" },
  { w: "有生以来", p: ["yǒu", "shēng", "yǐ", "lái"], e: "从出生到现在。", s: "清·曹雪芹《红楼梦》第一百十八回况你自有生以来，自去世的老太太，以至老爷、太太，视如珍宝。”" },
  { w: "有生之年", p: ["yǒu", "shēng", "zhī", "nián"], e: "一生之中最后的年月，即余年。", s: "清·李汝珍《镜花缘》第68回俾臣得保蚁命，此后有生之年，莫非主上所赐，惟求格外垂怜。”" },
  { w: "有声没气", p: ["yǒu", "shēng", "méi", "qì"], e: "形容说话无精打采。同有声无气”。", s: "茅盾《林家铺子》六林先生叹了一口气，过了一会儿，方才有声没气地说道‘让我死在那边就是了……’”" },
  { w: "有声无气", p: ["yǒu", "shēng", "wú", "qì"], e: "①形容人气息奄奄。②形容说话无精打采。", s: "明·凌濛初《二刻拍案惊奇》卷二十一王禄多说了几句话，渐渐有声无气，挨到黄昏，只有出的气，没有入的气，呜呼哀哉，伏维尚飨。…" },
  { w: "有声无实", p: ["yǒu", "shēng", "wú", "shí"], e: "犹言有名无实。光有空名，实际上并不是那样。", s: "《魏书·李崇传》今若基宇不修，仍同丘畎，即使高皇神享，阙于国阳，宗事之典，有声无实，此臣子所以匪宁，亿兆所以失望也。”" },
  { w: "有声有色", p: ["yǒu", "shēng", "yǒu", "sè"], e: "形容说话或表演精彩生动。", s: "清·洪亮吉《北江诗话》卷一写月有声有色如此，后人复何着笔耶？”" },
  { w: "有死无二", p: ["yǒu", "sǐ", "wú", "èr"], e: "表示意志坚定，虽死不变。", s: "《左传·僖公十五年》必报德，有死无二。”" },
  { w: "有所作为", p: ["yǒu", "suǒ", "zuò", "wéi"], e: "可以做事情，并能取得较大的成绩。", s: "先秦·孟轲《孟子·离娄下》人有不为也，而后可以有为。”" },
  { w: "有天没日", p: ["yǒu", "tiān", "méi", "rì"], e: "比喻说话毫无畏惧和顾忌。", s: "清·曹雪芹《红楼梦》第七回众小厮见说出来的话有天没日的，吓得魂飞魄丧，把他捆起来。”" },
  { w: "有天无日", p: ["yǒu", "tiān", "wú", "rì"], e: "比喻社会非弛暗，没有公道。", s: "元·康进之《李逵负荆》第二折元来个梁山泊有天无日。”" },
  { w: "有我无人", p: ["yǒu", "wǒ", "wú", "rén"], e: "极言其自傲而轻视他人。", s: "蔡东藩《五代史演义》第二回[朱温]到了难星已过，依然趾高气扬，有我无人。”" },
  { w: "有无相通", p: ["yǒu", "wú", "xiāng", "tōng"], e: "互通有无，互相接济。", s: "宋·文天祥《刘定伯墓志铭》朋友有无相通，急难于我乎赴。”" },
  { w: "有物有则", p: ["yǒu", "wù", "yǒu", "zé"], e: "指天地间凡事物皆有其法则、规律。", s: "《诗·大雅·焌民》天生焌民，有物有则。”" },
  { w: "有心无力", p: ["yǒu", "xīn", "wú", "lì"], e: "有愿望和打算，但没有力量付诸实现。", s: "南朝·梁·惠皎《高僧传·义解·竺法旷》贫道必当尽诚上答，正恐有心无力耳。”" },
  { w: "有心有意", p: ["yǒu", "xīn", "yǒu", "yì"], e: "犹言诚心诚意。形容十分真挚诚恳。", s: "无" },
  { w: "有言在先", p: ["yǒu", "yán", "zài", "xiān"], e: "有话说在头里。指事先打了招呼。", s: "明·冯梦龙《醒世恒言》卷二十二他有言在先，你今日不须惊怕。”" },
  { w: "有一得一", p: ["yǒu", "yī", "dé", "yī"], e: "不加也不减，有多少是多少。", s: "无" },
  { w: "有一无二", p: ["yǒu", "yī", "wú", "èr"], e: "只有一个，不会有第二个。指事物独特，极难得。", s: "明·姚子翼《遍地锦传奇·劝主》似这等才调也算得有一无二的了。”" },
  { w: "有意无意", p: ["yǒu", "yì", "wú", "yì"], e: "又像是有意的，又像是无意的。存心与不经意。", s: "南朝·宋·刘义庆《世说新语·文学》庾子嵩作意赋成，从子文康见，问曰若有意邪？非赋之所尽，若无意邪？复何所赋？答曰正在有意…" },
  { w: "有志无时", p: ["yǒu", "zhì", "wú", "shí"], e: "有抱负而时运不济。", s: "《后汉书·赵歧传》汉有逸人，姓赵名嘉。有志无时，命也奈何！”" },
  { w: "有志之士", p: ["yǒu", "zhì", "zhī", "shì"], e: "士对人的尊称。指有理想有抱负的人。", s: "宋·陆九渊《与曾宅之书》惟其生于后世，学绝道丧，异端邪说充塞弥满，遂使有志之士罹此患害，乃与世间凡庸恣情纵欲之人均其陷溺…" },
  { w: "又当别论", p: ["yòu", "dāng", "bié", "lùn"], e: "应当另外作出评价。", s: "明·朱国祯《涌幢小品·世荫不同》至孙许之荫以锦衣，官二品三品，忠臣之后又当别论。”" },
  { w: "又作别论", p: ["yòu", "zuò", "bié", "lùn"], e: "应当另外作出评价。", s: "鲁迅《朝花夕拾·五猖会》他们既然是五猖，便也无法可想，而且自然也就‘又作别论’了。”又《无常》这自然是专就我的故乡而言，…" },
  { w: "于家为国", p: ["yú", "jiā", "wéi", "guó"], e: "为国家为人民。", s: "无" },
  { w: "与民同乐", p: ["yǔ", "mín", "tóng", "lè"], e: "原指君王施行仁政，与百姓休戚与共，同享欢乐◇泛指领导与群众一起游乐，共享幸福。", s: "《孟子·梁惠王下·庄暴见孟子》今王四猎于此，百姓闻王车马之音，见羽旄之美，举欣欣然有喜色而相告曰‘吾王庶几无疾病与，何以…" },
  { w: "与众不同", p: ["yǔ", "zhòng", "bù", "tóng"], e: "跟大家不一样。", s: "清·李汝珍《镜花缘》这是今日令中第一个古人，必须出类拔萃，与众不同，才觉有趣。”" },
  { w: "语四言三", p: ["yǔ", "sì", "yán", "sān"], e: "指信口乱说闲话。", s: "《群音类选·〈分钗记·计诱皮氏〉》为何的语四言三，平白地将人讥诮。”" },
  { w: "语长心重", p: ["yǔ", "cháng", "xīn", "zhòng"], e: "言辞恳切，情意深长。", s: "蔡元培《致公言报”函并符答林琴南君函》公书语长心重，深以外间谣诼纷纭集为北京大学惜，甚感。”" },
  { w: "语重情深", p: ["yǔ", "zhòng", "qíng", "shēn"], e: "犹言语重心长。", s: "严复《以〈渔洋精华录〉寄琥唐山春榆侍郎有诗见述率赋奉答》忽蒙佳什誉过庭，语重情深谁敢荷？”" },
  { w: "语重心长", p: ["yǔ", "zhòng", "xīn", "cháng"], e: "话深刻有力，情意深长。", s: "无" },
  { w: "玉成其美", p: ["yù", "chéng", "qí", "měi"], e: "玉成玉汝于成”的缩语，帮助你有所成，后用为成全之意。成全某件好事。亦作玉成其事”。", s: "无" },
  { w: "玉成其事", p: ["yù", "chéng", "qí", "shì"], e: "玉成成全，内含客气的意思。成全那件事情。", s: "明·冯梦龙《东周列国志》第八回大夫能玉成其事，请以白璧二双，黄金百镒为献。”" },
  { w: "喻之以理", p: ["yù", "zhī", "yǐ", "lǐ"], e: "喻晓喻，开导。用道理来开导说服人。", s: "无" },
  { w: "元元本本", p: ["yuán", "yuán", "běn", "běn"], e: "元元探索原始；本本寻求根本。原指探索事物的根由底细◇指详细叙述事情的全部起因和整个过程，一点不漏。", s: "汉·班固《西都赋》元元本本，殚见洽闻。”" },
  { w: "元元之民", p: ["yuán", "yuán", "zhī", "mín"], e: "众百姓；善良的百姓。", s: "汉·贾谊《过秦论》即元元之民，冀得安其性命，莫不虚心而仰上。”" },
  { w: "原来如此", p: ["yuán", "lái", "rú", "cǐ"], e: "原来表示发现真实情况。原来是这样。", s: "清·曹雪芹《红楼梦》第六十六回原来如此，倒教我们悬了几日心。”" },
  { w: "原原本本", p: ["yuán", "yuán", "běn", "běn"], e: "从头到尾按原来的样子。指详细叙述事情的全部起因和整个过程，一点不漏。", s: "汉·班固《西都赋》元元本本，殚见洽闻。”" },
  { w: "月白风清", p: ["yuè", "bái", "fēng", "qīng"], e: "形容幽静美好的夜晚。", s: "宋·苏轼《后赤壁赋》有客无酒，有酒无肴，月白风清，如此良夜何？”" },
  { w: "月下花前", p: ["yuè", "xià", "huā", "qián"], e: "本指游乐休息的环境◇多指谈情说爱的处所。", s: "唐·白居易《老病》诗尽听笙歌夜醉眠，若非月下即花前。”" },
  { w: "月下老儿", p: ["yuè", "xià", "lǎo", "ér"], e: "神话传说中掌管婚姻之神。借指媒人。", s: "清·曹雪芹《红楼梦》第五十七回管姻缘的有一位月下老儿，预先注定，暗里只用一根红丝，把这两个人的脚绊住……若是月下老人不用…" },
  { w: "月下老人", p: ["yuè", "xià", "lǎo", "rén"], e: "原指主管婚姻的神仙◇泛指媒人。简称月老”。", s: "唐·李复言《续幽怪录》记载传说故事唐朝的韦固路过宋城，遇一老人在月光下翻检一本书。询问后，知道老人是专管人间婚姻的神，翻…" },
  { w: "云开见日", p: ["yún", "kāi", "jiàn", "rì"], e: "拔开云雾，见到太阳。比喻黑暗已经过去，光明已经到来。也比喻误会消除。", s: "《后汉书·袁绍传》旷若开云见日，何喜如之。”" },
  { w: "云开见天", p: ["yún", "kāi", "jiàn", "tiān"], e: "乌云消散，重见天日。比喻社会由乱转治，由黑暗转向光明。", s: "无" },
  { w: "在官言官", p: ["zài", "guān", "yán", "guān"], e: "指处在什么样的地位就说什么样的话。", s: "《礼记·曲礼下》君命，大夫与士肄，在官言官，在府言府，在库言库，在朝言朝。”" },
  { w: "在家出家", p: ["zài", "jiā", "chū", "jiā"], e: "指不出家当和尚，清心寡欲，在家修行。", s: "《法苑珠林》卷一０七在家出家，平等而受。”" },
  { w: "张大其事", p: ["zhāng", "dà", "qí", "shì"], e: "张夸张。把原来的事情夸大。形容言过其实。亦作张皇其事”、张大其辞（词）”、张扬其事”。", s: "唐·韩愈《送杨少尹序》太史氏又能张大其事，为传继二疏踪迹否？”" },
  { w: "长安道上", p: ["cháng", "ān", "dào", "shàng"], e: "长安古都名，在今陕西西安西北。旧喻名利场所。", s: "五代·无名氏《贺圣朝》词长安道上行客，依旧利深名切。”" },
  { w: "长生不老", p: ["cháng", "shēng", "bù", "lǎo"], e: "长生永生。原为道教的话，后也用作对年长者的祝愿语。", s: "《太上纯阳真经·了三得一经》天一生水，人同自然，肾为北极之枢，精食万化，滋养百骸，赖以永年而长生不老。”" },
  { w: "长生不死", p: ["cháng", "shēng", "bū", "sǐ"], e: "生命长存，永不死亡。", s: "晋·葛洪《抱朴子·辨问》长生不死，以此责圣人，何其多乎？”" },
  { w: "正大光明", p: ["zhèng", "dà", "guāng", "míng"], e: "心怀坦白，言行正派。", s: "宋·朱熹《答吕伯恭书》大抵圣贤之心，正大光明，洞然四达。”" },
  { w: "正经八百", p: ["zhèng", "jīng", "bā", "bǎi"], e: "①正经的，严肃认真的。②犹名副其实。", s: "张天民《创业》第二章秦发愤却当了真，正经八百地说‘抗美援朝的时候起的。’”" },
  { w: "正经八本", p: ["zhèng", "jīng", "bā", "běn"], e: "正经的，严肃认真的。同正经八百”。", s: "郭澄清《大刀记》第十八章可是，我们干革命，只要正经八本地干，哪有不忙的时候儿？”" },
  { w: "正名定分", p: ["zhèng", "míng", "dìng", "fēn"], e: "辨正名分，使名实相符。", s: "鲁迅《且介亭杂文二集·非有复译不可》于是有些人又记起了翻译，试来译几篇。但这就又是‘批评家’的材料了，其实，正名定分，他…" },
  { w: "正明公道", p: ["zhèng", "míng", "gōng", "dào"], e: "指正大光明。", s: "清·西周生《醒世姻缘传》第二十二回你这话不怕熏的人慌！你要是正明公道的人，没的敢说你不是个大的们！人干不出来的事，你干出…" },
  { w: "正人君子", p: ["zhèng", "rén", "jūn", "zǐ"], e: "旧时指品行端正的人。现多作讽刺的用法，指假装正经的人。", s: "《旧唐书·崔胤传》胤所悦者阘茸下辈，所恶者正人君子。人人悚惧，朝不保夕。”" },
  { w: "正身明法", p: ["zhèng", "shēn", "míng", "fǎ"], e: "端正自身，严明法纪。", s: "《晋书·元帝纪》二千石令长当袛奉旧宪，正身明法，抑齐豪强，存恤孤独，隐实户口，劝课农桑。”" },
  { w: "正身清心", p: ["zhèng", "shēn", "qīng", "xīn"], e: "端正自己的言行，清静内心。比喻修身养性。", s: "无" },
  { w: "正正经经", p: ["zhèng", "zhèng", "jīng", "jīng"], e: "①严肃而认真。②形容正大光明。", s: "清·李渔《怜香伴·狂喜》哄我正正经经听了半日，只说当真，原来又是说笑。”" },
  { w: "正正气气", p: ["zhèng", "zhèng", "qì", "qì"], e: "正派。", s: "明·凌濛初《二刻拍案惊奇》卷二十八［程朝奉］虽是缠得熟分了，那陈氏也自正正气气，一时也勾搭不上。”" },
  { w: "知地知天", p: ["zhī", "dì", "zhī", "tiān"], e: "地地形天天气。了解地形，了解气候。", s: "无" },
  { w: "知名当世", p: ["zhī", "míng", "dāng", "shì"], e: "知名著名、有名。在当代很著名。", s: "无" },
  { w: "知难而进", p: ["zhī", "nán", "ér", "jìn"], e: "迎着困难上。", s: "无" },
  { w: "知人论世", p: ["zhī", "rén", "lùn", "shì"], e: "原指了解一个人并研究他所处的时代背景。现也指鉴别人物的好坏，议论世事的得失。", s: "《孟子·万章下》颂其诗，读其书，不知其人可乎？是以论其世也。”" },
  { w: "知人下士", p: ["zhī", "rén", "xià", "shì"], e: "知识别。下士屈己尊人。能识别人才并礼贤下士。", s: "无" },
  { w: "知人之明", p: ["zhī", "rén", "zhī", "míng"], e: "能看出人的品行才能的眼力。", s: "无" },
  { w: "知无不言", p: ["zhī", "wú", "bù", "yán"], e: "凡是知道的没有不说的。", s: "宋·苏洵《衡论·远虑》知无不言，言无不尽，百人誉之不加密，百人毁之不加疏。”" },
  { w: "知足常乐", p: ["zhī", "zú", "cháng", "lè"], e: "知道满足，就总是快乐。形容安于已经得到的利益、地位。", s: "先秦·李耳《老子》祸莫大于不知足，咎莫大于欲得，故知足之足常足矣。”" },
  { w: "指东话西", p: ["zhǐ", "dōng", "huà", "xī"], e: "犹言东拉西扯。指说话文不对题或空言不实。", s: "清·李宝嘉《官场现形记》第七回三荷包再问问他，他便指东话西，一味支吾。又说临时我自来照料。”又说连我也不懂得甚么。”三荷…" },
  { w: "指东说西", p: ["zhǐ", "dōng", "shuō", "xī"], e: "①见指东话西”。②犹言指桑骂槐。", s: "曹禺《雷雨》第三幕你要骂我就骂我，别指东说西，欺负妈妈好说话。”" },
  { w: "指日可下", p: ["zhǐ", "rì", "kě", "xià"], e: "表示不久就可以攻下。", s: "郭沫若《革命春秋·北伐途次》这最后的抵抗如被冲破，武昌城便指日可下。”" },
  { w: "至高无上", p: ["zhì", "gāo", "wú", "shàng"], e: "至最。高到顶点，再也没有更高的了。", s: "《淮南子·缪称训》道至高无上，至深无下，平乎准，直乎绳，圆乎规，方乎矩。”汉·许慎《说文解字·一部》天，颠也。至高无上，…" },
  { w: "至理名言", p: ["zhì", "lǐ", "míng", "yán"], e: "至最；名有名声的。最正确的道理，最精辟的言论。", s: "老舍《鼓书艺人》十二‘你不自轻自贱，人家就不能看轻你’。这话倒说得不错，这也是至理名言。”" },
  { w: "至人无梦", p: ["zhì", "rén", "wú", "mèng"], e: "至人指思想道德等方面达到最高境界的人。品德高尚的人，不会做想入非非的梦。", s: "清·钱彩《说岳全传》第五十九回自古至人无梦，梦境忽来，未必无兆。”" },
  { w: "至死不变", p: ["zhì", "sǐ", "bù", "biàn"], e: "纛到。到死不改变（现常用在坏的方面）。", s: "《礼记·中庸》国无道，至死不变，强哉矫。”" },
  { w: "志同道合", p: ["zhì", "tóng", "dào", "hé"], e: "道途径。志趣相同，意见一致。", s: "《三国志·魏志·陈思王植传》昔伊尹之为媵臣，至贱也，吕尚之处屠钓，至陋也，乃其见举于汤武、周文，诚道合志同，玄漠神通，岂…" },
  { w: "志在四方", p: ["zhì", "zài", "sì", "fāng"], e: "四方天下。有远大的抱负和理想。", s: "明·冯梦龙《东周列国志》第二十五回妾闻‘男子志在四方’。君壮年不出图仕，乃区区守妻子坐困乎？”" },
  { w: "众多非一", p: ["zhòng", "duō", "fēi", "yī"], e: "指类别甚多，不止一种。", s: "汉·王充《论衡·别通》孔子道美，故譬以宗庙，众多非一，故喻以百官。”" },
  { w: "众人国士", p: ["zhòng", "rén", "guó", "shì"], e: "众人普通人；国士国中杰出的人物。指一般人和国中杰出的人才。", s: "《战国策·赵策一》臣事范中行氏，范中行氏以众人遇臣，臣故众人报之；知伯以国士遇臣，臣故国士报之。”" },
  { w: "众少成多", p: ["zhòng", "shǎo", "chéng", "duō"], e: "犹积少成多。指只要不断积累，就会从少变多。", s: "《汉书·董仲舒传》众少成多，积小致钜。”" },
  { w: "众所周知", p: ["zhòng", "suǒ", "zhōu", "zhī"], e: "大家普遍知道的。", s: "《玉娇梨》第二十回城中宣杂难住，莫苦就在众所周知石村卜一居，与白公为邻。”" },
  { w: "周而不比", p: ["zhōu", "ér", "bù", "bǐ"], e: "周亲和、调合；比勾结。关系密切，但不勾结。指与众相合，但不做坏事。", s: "《论语·为政》子曰‘君子周而不比。’”" },
  { w: "自成一家", p: ["zì", "chéng", "yī", "jiā"], e: "指在某一方面的学问或技术有独到的见解或独特的做法，能自成体系。", s: "《北史·祖莹传》作文须自出机杼，成一家风骨。”" },
  { w: "自出一家", p: ["zì", "chū", "yī", "jiā"], e: "指在某一方面的学问或技术有独到的见解或独特的做法，能自成体系。", s: "《魏书·祖莹传》文章须自出机杼，成一家风骨，何能共人同生活也。”" },
  { w: "自得其乐", p: ["zì", "dé", "qí", "lè"], e: "自己能从中得到乐趣。", s: "明·陶宗仪《辍耕录》卷二十白翎雀生于乌桓朔漠之地，雌雄和鸣，自得其乐。”" },
  { w: "自高自大", p: ["zì", "gāo", "zì", "dà"], e: "自以为了不起。", s: "北齐·颜之推《颜氏家训·勉学》见人读数十卷书，便自高大，凌忽长者，轻慢同列。”" },
  { w: "自然而然", p: ["zì", "rán", "ér", "rán"], e: "自由发展，必然这样。指非人力干预而自然如此。", s: "《牟子理惑篇》夫吉凶之与善恶，犹善恶之乘形声，自然而然，不得相免也。”" },
  { w: "自食其力", p: ["zì", "shí", "qí", "lì"], e: "依靠自己的劳动所得来生活。", s: "《礼记·礼器》食力无数。”陈浩集说食力，自食其力之人。”" },
  { w: "自食其言", p: ["zì", "shí", "qí", "yán"], e: "指说了话不算数。", s: "《尚书·汤誓》尔无不信，朕不食言。”" },
  { w: "自我表现", p: ["zì", "wǒ", "biǎo", "xiàn"], e: "显示或宣扬自己的优点，使自己突出。", s: "苏雪林《郁达夫及其作品》现代文艺里‘自我表现’，之特多，原是当然的道理。”" },
  { w: "自我作古", p: ["zì", "wǒ", "zuò", "gǔ"], e: "作古创始。由我创造。指不沿袭前人。", s: "唐·刘知己《史通·称谓》唯魏收远不师古，近非因俗，自我作故，无所宪章。”" },
  { w: "自我作故", p: ["zì", "wǒ", "zuò", "gù"], e: "作故创始。由我创造。指不沿袭前人。", s: "唐·刘知己《史通·称谓》唯魏收远不师古，近非因俗，自我作故，无所宪章。”" },
  { w: "自言自语", p: ["zì", "yán", "zì", "yǔ"], e: "自己一个人低声嘀咕。", s: "元·无名氏《桃花女》第四折你这般鬼促促的，在这自言自语，莫不要出城去砍那桃树吗？”" },
  { w: "自用则小", p: ["zì", "yòng", "zé", "xiǎo"], e: "自用只凭自己的主观意图行事，不虚心向人求教。主观武断，就办不成大事。", s: "《尚书·仲虺之诰》好问则裕，自用则小。”" },
  { w: "自有公论", p: ["zì", "yǒu", "gōng", "lùn"], e: "指事情的是非曲直公众自然会有评论。", s: "南朝·宋·刘义庆《世说新语·品藻》抜庾公呴又问‘何者居其右？’王曰‘自有人。’又问‘何者是？’王曰‘噫！其自有公论。’”…" },
  { w: "自知之明", p: ["zì", "zhī", "zhī", "míng"], e: "自知自己了解自己；明看清事物的能力。指了解自己的情况，对自己有正确的估计。", s: "《老子》第三十三章知人者智也，自知者明也。”" },
  { w: "自作主张", p: ["zì", "zuò", "zhǔ", "zhāng"], e: "指没有经过上级或有关方面同意，就擅自处置。", s: "元·无名氏《谢金吾》第三折但那杨景是一个郡马，怎好就是这等自做主张，将他只一刀哈喇了。”" },
  { w: "自作自受", p: ["zì", "zuò", "zì", "shòu"], e: "自己做了蠢事坏事，自己倒霉。", s: "宋·释普济《五灯会元》僧问金山颖‘一百二十斤铁枷，教阿谁担？’颖曰‘自作自受。’”" },
  { w: "足兵足食", p: ["zú", "bīng", "zú", "shí"], e: "粮食、军备充足。", s: "宋·胡鍂《耕禄稿·代田万顷到任谢表》秉戈执耒，宜为足兵足食之思；牧马饭牛，盍讲且战且耕之政。”" },
  { w: "足不出门", p: ["zú", "bù", "chū", "mén"], e: "不出大门一步。指闭门自守。", s: "明·凌濛初《初刻拍案惊奇》卷二十五却说苏盼奴自赵司户去后，足不出门，一客不见，只等襄阳来音。”" },
  { w: "足食足兵", p: ["zú", "shí", "zú", "bīng"], e: "食粮食；兵武器。粮食充足，武备修整。", s: "《论语·颜渊》子贡问政。子曰‘足食足兵，民信之矣。’”" },
  { w: "作古正经", p: ["zuò", "gǔ", "zhèng", "jīng"], e: "犹言一本正经。", s: "艾芜《一个女人的悲剧》五陈家驼背子板起面孔，作古正经地说‘我刚才想了好一阵，一定是那会事情’”" },
  { w: "做人做世", p: ["zuò", "rén", "zuò", "shì"], e: "指在社会上立身行事。", s: "欧阳山《三家巷》二四咱俩都快要走进社会——做人做世了，你怎么还只管任性胡来呢！”又《苦斗》六一咱们来到这震南农场，原来不…" },
  { w: "做张做势", p: ["zuò", "zhāng", "zuò", "shì"], e: "装模作样，故意做出一种姿态。", s: "语出《醒世恒言·卖油郎独占花魁》那些有势有力的不肯出钱，专要讨人便宜。及至肯出几两银子的，女儿又嫌好道歉，做张做智的不肯…" }
];
